[' Here's a C function that initializes and populates a dynamically allocated array of `NFAPI_L2_RXUEINFO_PDU` structures. The function also includes a logging mechanism to track successful allocations and failures during the process.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    uint32_t rnti;
    uint32_t srb1_rlc_status;
    uint32_t rrc_cgi;
} RX_UE_INFORMATION_TAG;

typedef struct {
    size_t capacity;
    size_t size;
    RX_UE_INFORMATION_TAG** rx_ues;
} NFAPI_L2_RXUEINFO_PDU;

void log(const char* message) {
    printf("%s\n", message);
}

NFAPI_L2_RXUEINFO_PDU* init_rxueinfo_pdu(size_t capacity) {
    NFAPI_L2_RXUEINFO_PDU* pdu = malloc(sizeof(NFAPI_L2_RXUEINFO_PDU));
    if (!pdu) {
        log("Failed to allocate memory for PDU.");
        return NULL;
    }

    pdu->capacity = capacity;
    pdu->size = 0;
    pdu->rx_ues = calloc(capacity, sizeof(RX_UE_INFORMATION_TAG*));
    if (!pdu->rx_ues) {
        log("Failed to allocate memory for RX_UES array.");
        free(pdu);
        return NULL;
    }

    return pdu;
}

void add_ue_info(NFAPI_L2_RXUEINFO_PDU* pdu, const RX_UE_INFORMATION_TAG* ue) {
    if (pdu->size >= pdu->capacity) {
        log("Resizing array due to capacity reached.");
        pdu->capacity *= 2;
        pdu->rx_ues = realloc(pdu->rx_ues, sizeof(RX_UE_INFORMATION_TAG*) * pdu->capacity);
    }

    pdu->rx_ues[pdu->size] = malloc(sizeof(RX_UE_INFORMATION_TAG));
    if (!pdu->rx_ues[pdu->size]) {
        log("Failed to allocate memory for RX_UE.");
        return;
    }

    memcpy(pdu->rx_ues[pdu->size], ue, sizeof(RX_UE_INFORMATION_TAG));
    pdu->size++;
}

void free_rxueinfo_pdu(NFAPI_L2_RXUEINFO_PDU* pdu) {
    for (size_t i = 0; i < pdu->size; ++i) {
        free(pdu->rx_ues[i]);
    }
    free(pdu->rx_ues);
    free(pdu);
}
```

This code defines the necessary structures and functions to manage the dynamic array of `NFAPI_L2_RXUEINFO_PDU` structures. The `init_rxueinfo_pdu()` function initializes a new PDU, while the `add_ue_info()` function adds UE information to an existing PDU. The `free_rxueinfo_pdu()` function deallocates memory for a given PDU.

The logging mechanism is implemented using the `log()` function, which prints messages to standard output. This can be replaced with a more robust logging library if needed.

