#include <chrono>

struct ParserOptions {
    std::string inputFile;
    std::string outputFile;
    std::string rules;
    int maxChunkSizeKB;
    bool enableLogging;
};

class ChunkProcessor {
public:
    virtual void process(const std::vector<char>& data) = 0;

protected:
    std::mutex mtx;
    std::ofstream logFile;

    void log(const std::string& message) {
        if (options.enableLogging) {
            std::lock_guard<std::mutex> lock(mtx);
            logFile << message << std::endl;
        }
    }
};

class JsonChunkProcessor : public ChunkProcessor {
public:
    void process(const std::vector<char>& data) override {
        Json::CharReaderBuilder builder;
        Json::CharReader* reader = builder.newCharReader();
        Json::Value root;
        std::string errors;

        bool parsingSuccessful = reader->parse(data.data(), data.data() + data.size(), &root, &errors);
        delete reader;

        if (parsingSuccessful) {
            // Process the JSON data according to the given rules
        } else {
            log("JSON parsing error: " + errors);
        }
    }
};

class XmlChunkProcessor : public ChunkProcessor {
public:
    void process(const std::vector<char>& data) override {
        tinyxml2::XMLDocument doc;
        std::string err;

        if (doc.LoadBuffer(data.data(), data.size(), &err)) {
            // Process the XML data according to the given rules
        } else {
            log("XML parsing error: " + err);
        }
    }
};

void processChunk(const ParserOptions& options, ChunkProcessor* processor, const std::vector<char>& chunk) {
    // Measure processing time for this chunk
    auto start = std::chrono::high_resolution_clock::now();
    processor->process(chunk);
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();

    // Log the processing time and overall file size for this chunk
}

void processFile(const ParserOptions& options) {
    boost::asio::io_context ioContext;
    boost::asio::basic_stream_buf<char> inputBuffer(std::ifstream(options.inputFile, std::ios::binary));
    boost::asio::basic_stream_buf<char> outputBuffer;
    boost::asio::async_read_until(ioContext, inputBuffer, '\n', [&](boost::system::error_code ec, std::size_t length) {
        if (!ec) {
            auto chunk = std::vector<char>(inputBuffer.data(), inputBuffer.data() + length);
            inputBuffer.consume(length);

            // Create a processor instance based on the given rules
            ChunkProcessor* processor;
            if (options.rules == "json") {
                processor = new JsonChunkProcessor();
            } else if (options.rules == "xml") {
                processor = new XmlChunkProcessor();
            }

            processChunk(options, processor, chunk);

            // Write the processed data to the output buffer
            outputBuffer.append(chunk.begin(), chunk.end());

            // Continue reading more chunks asynchronously
            boost::asio::async_read_until(ioContext, inputBuffer, '\n', [&](boost::system::error_code ec, std::size_t length) {
                if (!ec) {
                    processFile(options);
                }
            });
        } else if (ec != boost::asio::error::eof) {
            std::cerr << "Error reading input file: " << ec.message() << std::endl;
        }
    });

    ioContext.run();
}

int main(int argc, char* argv[]) {
    if (argc != 6) {
        std::cerr << "Usage: " << argv[0] << " <input_file> <output_file> <rules> <max_chunk_size_KB> <enable_logging>" << std::endl;
        return 1;
    }

    ParserOptions options{argv[1], argv[2], argv[3], std::stoi(argv[4]), std::stoi(argv[5]) > 0};
    processFile(options);

    return 0;
}
```

