public interface HashService {
    String generateHash(String input, String algorithm, String format) throws Exception;
}
```

3. Service Implementation:

```java
import org.apache.commons.codec.digest.Md5Crypt;
import org.apache.commons.codec.digest.Sha256Crypt;
import java.security.NoSuchAlgorithmException;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.Base64;

public class HashServiceImpl implements HashService {
    private Connection connection;

    public HashServiceImpl(Connection connection) {
        this.connection = connection;
    }

    @Override
    public String generateHash(String input, String algorithm, String format) throws Exception {
        if (algorithm.equalsIgnoreCase("MD5")) {
            MessageDigest md = Md5Crypt.getMd5Crypt();
            byte[] digest = md.digest(input.getBytes());
            String result;
            if (format.equalsIgnoreCase("hexadecimal")) {
                result = bytesToHex(digest);
            } else if (format.equalsIgnoreCase("base64")) {
                result = Base64.getEncoder().encodeToString(digest);
            } else {
                throw new Exception("Invalid format: " + format);
            }
            logOperation(input, algorithm, result);
            return result;
        } else if (algorithm.equalsIgnoreCase("SHA-256")) {
            MessageDigest md = Sha256Crypt.getSha256Crypt();
            byte[] digest = md.digest(input.getBytes());
            String result;
            if (format.equalsIgnoreCase("hexadecimal")) {
                result = bytesToHex(digest);
            } else if (format.equalsIgnoreCase("base64")) {
                result = Base64.getEncoder().encodeToString(digest);
            } else {
                throw new Exception("Invalid format: " + format);
            }
            logOperation(input, algorithm, result);
            return result;
        } else {
            throw new NoSuchAlgorithmException("Unknown algorithm: " + algorithm);
        }
    }

    private void logOperation(String input, String algorithm, String hash) {
        try {
            PreparedStatement ps = connection.prepareStatement("INSERT INTO hashes_log (user_id, timestamp, input_length, algorithm, format, hash) VALUES (?, ?, ?, ?, ?, ?)");
            ps.setLong(1, 1); // Replace with actual user ID
            ps.setTimestamp(2, new java.sql.Timestamp(System.currentTimeMillis()));
            ps.setInt(3, input.length());
            ps.setString(4, algorithm);
            ps.setString(5, format);
            ps.setString(6, hash);
            ps.executeUpdate();
        } catch (SQLException e) {
            // Handle SQL exceptions here
        }
    }

    private String bytesToHex(byte[] digest) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : digest) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }
}
```

4. Main Class:

```java
import java.sql.*;

public class Main {
