    public CustomPasswordValidator(IDateTime dateTime)
    {
        _dateTime = dateTime;
    }

    public override async Task<IdentityResult> ValidateAsync(UserManager<ApplicationUser> manager, ApplicationUser user, string password)
    {
        // Check if the user has received a password reset email within the last 24 hours
        var lastPasswordResetEmail = await _context.PasswordResets
            .Where(pr => pr.UserId == user.Id && pr.SentOn >= _dateTime.UtcNow.AddHours(-24))
            .FirstOrDefaultAsync();

        if (lastPasswordResetEmail != null)
