            return IdentityResult.Failed(new IdentityError() { Code = "PasswordResetEmailLimit", Description = "Password reset email limit reached." });
        }

        // Call the base ValidateAsync method to perform additional validations
        await base.ValidateAsync(manager, user, password);
    }
}
