angular.module('myApp')
  .factory('FieldUpdater', ['$http', '$q', function($http, $q) {
    var resourceId = null;
    var urlList = [];

    function updateFields(resourceId, url, fieldNames) {
      this.resourceId = resourceId;
      this.urlList = urlList;

      var deferred = $q.defer();

      angular.forEach(fieldUpdates(), function(field) {
        if (fieldNames.indexOf(field.name) !== -1 && resourceId === field.resourceId) {
          sendRequest(field);
        }
      });

      function fieldUpdates() {
        return document.querySelectorAll('#dialogFields input[type="text"]');
      }

      function sendRequest(field) {
        var request = $http({
          method: 'GET',
          url: url + field.name,
          responseType: 'json'
        });

        request.then(
          function successCallback(response) {
            updateFieldValue(field, response.data);
            deferred.resolve(urlList);
          },
          function errorCallback() {
            console.error('Error updating field:', field.name);
            deferred.reject();
          }
        );
      }

      function updateFieldValue(field, newValue) {
        field.value = newValue;
        field.dispatchEvent(new Event('input'));
      }

      function handleTimeout() {
        console.error('Timeout while waiting for parent window response.');
        deferred.reject();
      }

      var timeoutId = setTimeout(handleTimeout, 10000);

      request.then(null, null, function onRequestComplete() {
        clearTimeout(timeoutId);
      });

      return deferred.promise;
    }

    return {
      updateFields: updateFields
    };
  }]);
```

