use log::{debug, error};
use reqwest_middleware::Logger;
use reqwest_retry::Retry;

struct Config {
    base_url: String,
    query_params: HashMap<String, String>,
    timeout: Duration,
    max_retries: u32,
    retry_backoff_factor: f64,
    log_level: log::LevelFilter,
}

impl Config {
    fn new(base_url: &str) -> Self {
        Config {
            base_url: base_url.to_string(),
            query_params: HashMap::new(),
            timeout: Duration::from_secs(10),
            max_retries: 3,
            retry_backoff_factor: 2.0,
            log_level: log::LevelFilter::Info,
        }
    }
}

struct HttpClient {
    config: Arc<Config>,
    client: Client,
}

impl HttpClient {
    fn new(config: Config) -> Self {
        let client = Client::builder()
            .timeout(config.timeout)
            .json_body_serializer(JsonBodySerializer)
            .add_middlewares(vec![Logger::new()])
            .build()
            .unwrap();

        HttpClient { config: Arc::new(config), client }
    }

    async fn get(&self, path: &str) -> Result<Value, reqwest::Error> {
        let mut url = self.config.base_url.clone();
        url.push_str(&path);
        for (key, value) in &self.config.query_params {
            url.push_str(&format!("&{}={}", key, value));
        }

        let request = self
            .client
            .get(&url)
            .retry(Retry::default().backoff(Duration::from_secs_f64(self.config.retry_backoff_factor)));

        match request.send().await {
            Ok(response) => response.json().await,
            Err(e) => Err(e),
        }
    }
}

