function generateReportData($reportId, $length, $charSet) {
    $randomString = bin2hex(random_bytes($length));
    $hashedRandomString = hash('sha256', $randomString);

    $promise = new Promise(
        function (Callable $resolve, Callable $reject) use ($reportId) {
            $context = stream_context_create([
                'http' => [
                    'header' => "Content-type: application/x-www-form-urlencoded\r\n",
                ],
            ]);
            $apiResponse = @file_get_contents("/api/v1/reports/{$reportId}", false, $context);

            if ($apiResponse === false) {
                $reject(new Exception("API call failed."));
            } else {
                try {
                    $apiData = json_decode($apiResponse, true);
                } catch (JsonDecodeException $e) {
                    $reject(new Exception("Invalid API response."));
                }
                $resolve([
                    'hashedRandomString' => $hashedRandomString,
                    'metadata' => $apiData,
                ]);
            }
        }
    );

    $promiseChain = $promise->then(
        function ($value) use ($reportId) {
            $filePath = "/data/report_{$reportId}.json";
            if (file_exists($filePath)) {
                $fileContent = file_get_contents($filePath);
                try {
                    $historicalData = json_decode($fileContent, true);
                } catch (JsonDecodeException $e) {
                    throw new Exception("Invalid historical data.");
                }
                return (object) $historicalData;
            } else {
                return new StdClass();
            }
        },
        function ($reason) {
            throw $reason;
        }
    );

    return $promiseChain->wait();
}
