#include <mutex>
#include <atomic>

class OctreeNode {
public:
    std::vector<std::unique_ptr<OctreeNode>> children;
    double featureSize, position[3];
    bool isLeaf;
    std::vector<double> data;

    OctreeNode(double featureSize, double x, double y, double z)
        : featureSize(featureSize), position{x, y, z}, isLeaf(false) {}
};

class Octree {
private:
    std::unique_ptr<OctreeNode> root;
    double featureSize, spatialResolution, initialCapacity, maxCapacity;
    std::mutex mutex;
    std::atomic<int> nodeCount{0};

public:
    Octree(double featureSize, double spatialResolution, int initialDataCapacity, int maxDataCapacity)
        : featureSize(featureSize), spatialResolution(spatialResolution),
          initialCapacity(static_cast<int>(pow(8, std::ceil(std::log2(spatialResolution / featureSize))) * initialDataCapacity)),
          maxCapacity(maxDataCapacity) {
        root = std::make_unique<OctreeNode>(featureSize, 0, 0, 0);
    }

    OctreeNode* allocateNode() {
        if (nodeCount >= maxCapacity) {
            // Implement garbage collection strategy here
        }

        auto node = std::make_unique<OctreeNode>(featureSize, root->position[0] + featureSize * nodeCount[0],
                                                  root->position[1] + featureSize * (nodeCount[0] % 2),
                                                  root->position[2] + featureSize * (nodeCount[0] % 4));
        nodeCount++;
        return node.get();
    }

    void insert(OctreeNode* node, double x, double y, double z, const std::vector<double>& data) {
        std::lock_guard<std::mutex> lock(mutex);

        if (node->isLeaf) {
            node->data.insert(node->data.end(), data.begin(), data.end());
        } else {
            auto it = std::find_if(node->children.begin(), node->children.end(), [](const auto& child) {
                return child->position[0] <= x && child->position[1] <= y && child->position[2] <= z;
            });

            if (it == node->children.end()) {
                it = node->children.begin();
                std::advance(it, 8);
            }

            it->insert(data.begin(), data.end());
        }
    }

    // Implement traversal, update, and other operations here
};
```

