class Attack {
public:
    int id;
    int cooldown;
    double effectiveness;

    Attack(int _id, int _cooldown, double _effectiveness) : id(_id), cooldown(_cooldown), effectiveness(_effectiveness) {}
};

class GameCharacter {
public:
    GameCharacter(const std::vector<Attack>& attacks, int criticalHitResetCooldownSeconds = 3)
        : attacks_(attacks), criticalHitResetCooldown_(criticalHitResetCooldownSeconds), lastAttackTime_(0) {}

    void performAttack() {
        auto now = std::time(nullptr);
        if (now - lastAttackTime_ >= globalCooldown_) {
            int randomAttackIndex = rand() % attacks_.size();
            for (size_t i = 0; i < randomAttackIndex; ++i) {
                if (!attacks_[i].cooldown || attacks_[i].cooldown <= now - lastAttackTime_) {
                    logAttack(attacks_[i].id, now);
                    attacks_[i].cooldown = now + attacks_[i].cooldown;
                    lastAttackTime_ = now;
                    break;
                }
            }
        }
    }

