using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private readonly Dictionary<Type, (float min, float max, bool inclusive)> _ranges = new();
    private readonly Dictionary<Type, Random> _randomGenerators = new();

    public void SetRange<T>(T min, T max, bool inclusive = true)
    {
        if (!_ranges.ContainsKey(typeof(T)))
            _ranges.Add(typeof(T), (default!, default!, false));

        if (_randomGenerators.ContainsKey(typeof(T)) && !_randomGenerators[typeof(T)].IsInitialized)
            _randomGenerators[typeof(T)] = new Random();

        _ranges[typeof(T)] = (Convert.ChangeType(min, typeof(T)), Convert.ChangeType(max, typeof(T)), inclusive);
    }

    public T GenerateValue<T>(bool isInclusive) where T : struct
    {
        if (!_randomGenerators.ContainsKey(typeof(T)) || !_randomGenerangers[typeof(T)].IsInitialized)
            _randomGenerators[typeof(T)] = new Random((int)_ranges[typeof(T)].min.GetHashCode());

        var range = _ranges[typeof(T)];
        return (isInclusive ? _randomGenerators[typeof(T)].Next(Convert.ToInt32(range.min), Convert.ToInt32(range.max + 1)) : _randomGenerators[typeof(T)].Next(Convert.ToInt32(range.min) + 1, Convert.ToInt32(range.max)))
            .ToString()
            .Cast<T>();
    }

    public Vector2 GenerateVector2() => new Vector2(GenerateValue<float>(), GenerateValue<float>());

    public Vector3 GenerateVector3() => new Vector3(GenerateValue<float>(), GenerateValue<float>(), GenerateValue<float>());

    public override string ToString()
    {
        var sb = new StringBuilder();
        foreach (var range in _ranges.Values)
        {
            sb.AppendLine($"Type: {range.GetType().Name}, Min: {range.min}, Max: {range.max}, Inclusive: {range.inclusive}");
        }
        return sb.ToString();
    }

    public void Validate()
