public (TiffImageInfo, string MD5Hash, bool DetailedMode) ProcessImageAndComputeHash(string tiffFilePath, string textToHash, bool detailedMode)
{
    var imageInfo = new TiffImageInfo();
    using (var fileStream = File.OpenRead(tiffFilePath))
    {
        if (!Tiff.TryReadFrom(fileStream, out imageInfo))
            throw new Exception("Failed to read TIFF image.");
    }

    var bitsPerSample = imageInfo.BitsPerSample[0];
    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 && bitsPerSample != 8 && bitsPerSample != 16)
        throw new Exception($"Unsupported number of bits per sample: {bitsPerSample}.");

    var extraSamples = new List<ExtraSampleInfo>();
    if (detailedMode)
    {
        for (int i = 1; i < imageInfo.BitsPerSample.Length; i++)
        {
            var sampleInfo = new ExtraSampleInfo
            {
                SampleNumber = i,
                PhotometricInterpretation = imageInfo.PhotometricInterpretation[i],
                Compression = imageInfo.Compression[i],
                Photometry = imageInfo.Photometry[i],
                FillOrder = imageInfo.FillOrder[i]
            };
            extraSamples.Add(sampleInfo);
        }
    }

    using (var md5 = MD5.Create())
    {
        var textBytes = Encoding.UTF8.GetBytes(textToHash);
        var hashBytes = md5.ComputeHash(textBytes);
        var hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

        return (imageInfo, hashString, detailedMode);
    }
}
