#include <openssl/aes.h>
#include <openssl/rand.h>
#include <argon2/argon2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define IV_LENGTH 16
#define KEY_LENGTH 32

typedef struct {
    AES_KEY aes;
    unsigned char iv[IV_LENGTH];
} aes_ctx;

aes_ctx* aes_init(const char *password, const char *salt) {
    unsigned char key[KEY_LENGTH], derived_key[KEY_LENGTH];
    argon2i_context ctx;
    argon2i_password_hash_t ph;
    aes_ctx *aes = malloc(sizeof(aes_ctx));

    if (argon2i_init(&ctx, ARGON2id, 1 << 14, 1, 1)) {
        fprintf(stderr, "Failed to initialize Argon2\n");
        return NULL;
    }

    argon2i_passwd_hash_start(&ctx, password, strlen(password), salt);
    argon2i_passwd_hash_update(&ctx, NULL, 0);
    argon2i_passwd_hash_final(derived_key, &ph, sizeof(derived_key));

    memcpy(key, derived_key, KEY_LENGTH);

    AES_set_encrypt_key(key, 256, &aes->aes.encrypt);
    RAND_bytes(aes->iv, IV_LENGTH);

    return aes;
}
```

This code initializes an AES-256-CBC cipher using the given password and derives the encryption key from it using Argon2. The function allocates memory for the AES context and sets the initialization vector (IV) randomly.

