#include <cstdlib>
#include <system_error>
#include <unistd.h>
#include <cstringh>

int processImageAndData(const char* inputJpeg, const char* outputPdf, const char* serializedData) {
    char command[1024];
    snprintf(command, sizeof(command), "./processImageAndData.sh %s %s %s", inputJpeg, outputPdf, serializedData);

    pid_t child = fork();
    if (child == -1) {
        std::cerr << "Fork failed: " << strerror(errno) << std::endl;
        return 1;
    }

    if (child > 0) { // Parent process
        int status;
        waitpid(child, &status, 0);
        if (WIFEXITED(status)) {
            if (WEXITSTATUS(status) != 0) {
                std::cerr << "Command execution failed with exit code: " << WEXITSTATUS(status) << std::endl;
            }
        } else {
            std::cerr << "Command execution failed" << std::endl;
        }
    } else { // Child process
        if (execlp("./processImageAndData.sh", "./processImageAndData.sh", inputJpeg, outputPdf, serializedData, NULL) == -1) {
            perror("Execlp failed");
            exit(EXIT_FAILURE);
        }
    }

    return 0;
}
