#include <stdio.h>
#include <string.h>
#include <openssl/des.h>
#include <openssl/err.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    char *password;
    void *connection;
    void (*callback)(char*);
} Credential;

typedef struct {
    unsigned char key[3*DES_key_size];
    unsigned char iv[DES_iv_size];
    long max_time_ms;
} Config;

int validateAndDecrypt(Credential *cred, char *encryptedMessage, Config *config, void (*callbackFunction)(char*)) {
    if (!cred || !encryptedMessage || !config || !callbackFunction) return -1; // Invalid parameters

    if (!cred->password) return -2; // Empty password

    if (!cred->connection || strcmp(cred->connection->title, "INVALID_TITLE") == 0) return -3; // Invalid connection

    if (!cred->callback) return -4; // Null callback function

    if (config->max_time_ms <= 0) return -5; // Invalid max time

    DES_key_schedule key_schedule;
    DES_set_key_unchecked(&key_schedule, config->key);

    unsigned char decrypted[128];
    int decrypted_len = DES_decrypt3_CBC(&key_schedule, iv, encryptedMessage, strlen(encryptedMessage), decrypted, NULL);

    if (decrypted_len < 0) return -6; // Decryption failure

    pthread_t thread;
    struct timespec time_limit = {config->max_time_ms / 1000, (config->max_time_ms % 1000) * 1e6};
    if (pthread_create(&thread, NULL, decryption_thread, (void*){.message=decrypted, .len=decrypted_len, .callback=callbackFunction})) return -7; // Thread creation failure

    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);
    while (difftime(current_time.tv_sec, clock_gettime(CLOCK_REALTIME, &current_time).tv_sec) < time_limit.tv_sec + time_limit.tv_nsec / 1e9) {
        pthread_testcancel();
    }

    pthread_cancel(thread);
    if (pthread_join(thread, NULL)) return -8; // Thread join failure

    return 0; // Success
}

void* decryption_thread(void *args) {
    void *message = args;
    size_t len = ((char*)message - (char*)args + sizeof(size_t)) / sizeof(char);
    char *decrypted_message = malloc(len);
    memcpy(decrypted_message, message, len);

    ((void (*)(char*))((char*)callbackFunction - (char*)args + sizeof(void*)))(decrypted_message);

    free(decrypted_message);
    return NULL;
}
```']

