typedef struct {
    char event_type[32];
    char transaction_id[64];
    double amount;
    char currency[4];
    char customer_id[32];
    char status[16];
} Event;

bool validate_event(const char *json, size_t length) {
    jsmn_parser parser;
    jsmntok_t tokens[10];
    int token_count = 0;

    jsmn_init(&parser);
    int result = jsmn_parse(json, length, sizeof(tokens), &parser);
    if (result < 0) {
        return false;
    }

    if (token_count < 6 || token_count > 7) {
        return false;
    }

    const char *names[] = {"event_type", "transaction_id", "amount", "currency", "customer_id", "status"};
    for (int i = 0; i < 6; ++i) {
        if (strcmp(tokens[i].name, names[i]) != 0) {
            return false;
        }
    }

    // Custom validation rules for different environments
    const char *env = "production";
    if (strcmp(tokens[0].name, "event_type") == 0 && strcmp(tokens[1].name, "transaction_id") == 0) {
        if (strcmp(tokens[0].string, "payment_succeeded") != 0 && strcmp(tokens[0].string, "payment_failed") != 0) {
            return false;
        }

        if (!isalnum(tokens[1].string[0]) || tokens[1].string[0] == '\0') {
            return false;
        }

        if (strlen(tokens[1].string) > 63) {
            return false;
        }

        if (strcmp(tokens[2].name, "amount") != 0 || tokens[2].type != JSMN_FLOAT) {
            return false;
        }

        if (tokens[2].value <= 0.0) {
            return false;
        }

        if (strcmp(tokens[3].name, "currency") != 0 || strlen(tokens[3].string) > 3) {
            return false;
        }

        // Optional fields validation
        if (token_count == 6 && strcmp(env, "development")) {
            if (strcmp(tokens[4].name, "customer_id") != 0) {
                return false;
            }

            if (strlen(tokens[4].string) > 31) {
                return false;
            }
        }

        if (token_count == 7 && strcmp(tokens[5].name, "status") != 0) {
            return false;
        }

        if (strcmp(tokens[5].string, "completed") != 0 && strcmp(tokens[5].string, "failed") != 0) {
            return false;
        }
    }

    return true;
}

void fraud_detection_callback(bool is_fraudulent, const Event *event, void *userdata) {
    if (is_fraudulent) {
        printf("Fraud detected for transaction %s\n", event->transaction_id);
        // Log the event and mark it as fraudulent in your system
    } else {
        // Process the transaction or continue with other operations
    }
}

bool process_event(const char *json, size_t length) {
    Event event;
    memcpy(event.transaction_id, json + jsmn_find_token(json, length, "transaction_id"), strlen(json + jsmn_find_token(json, length, "transaction_id")) + 1);

    if (!validate_event(json, length)) {
        return false;
    }

    // Asynchronously call the fraud detection service
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, &fraud_detection_callback, (void *)&event);

    return true;
}
```

This code defines a `validate_event()` function that checks the JSON structure and values against the given requirements. It also includes an example of asynchronous fraud detection using pthreads. You can replace the `fraud_detection_callback()` with your actual implementation for integrating with an external service.']

