            var json = await File.ReadAllTextAsync(_filePath);
            return JsonConvert.DeserializeObject<DataObject>(json);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading data from binary file: {ex}");
            return new DataObject { IsValid = false };
