public class RestApiDataSource : IDataSource<DataObject>
{
    private readonly string _apiUrl;

    public RestApiDataSource(string apiUrl) => _apiUrl = apiUrl;

    private HttpClient _httpClient = new HttpClient();

    public async Task<DataObject> LoadDataAsync()
    {
        try
        {
            var response = await _httpClient.GetAsync(_apiUrl);
            response.EnsureSuccessStatusCode();
            var json = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<DataObject>(json);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading data from REST API: {ex}");
            return new DataObject { IsValid = false };
        }
    }
}

public class DataLoaderFactory
{
    private readonly ConcurrentDictionary<string, IDataSource<DataObject>> _dataSources;

    public DataLoaderFactory() => _dataSources = new ConcurrentDictionary<string, IDataSource<DataObject>>();

    public void AddDataSource(IDataSource<DataObject> dataSource) => _dataSources[dataSource.GetType().Name] = dataSource;

    public async Task<DataObject> LoadDataAsync(string dataSourceName)
    {
        if (!_dataSources.TryGetValue(dataSourceName, out var dataSource))
            throw new Exception($"Unknown data source: {dataSourceName}");

        return await dataSource.LoadDataAsync();
    }
}
