```rust
use std::env;
use std::fs::File;
use std::io::{self, Write};
use log::{LevelFilter, SetLoggerError, Logger};
use reqwest::blocking::get;
use serde_json::from_str;
use tokio::runtime::Runtime;
use tokio::task;

mod config {
    pub const LOG_LEVEL: &'static str = std::env::var("LOG_LEVEL").unwrap_or_else(|_| "info".to_string());
}

fn init_logger() -> Result<(), SetLoggerError> {
    let timestamp = chrono::Utc::now().format("%Y-%m-%d %H:%M:%S");
    let mut builder = log::Builder::new();
    builder.filter(None, level_filter)
        .format_timestamp(|t| format!("{}", t))
        .format_target(false)
        .format_message(|msg| format!("{}", msg))
        .init()?;

    let mut log_file = File::create("app.log").unwrap();
    io::stdout().write_all(b"Logging to app.log\n")?;
    writeln!(log_file, "Logging to app.log")?;

    Ok(())
}

fn level_filter(record: &log::Record) -> bool {
    let level = record.level();
    match config::LOG_LEVEL.as_str() {
        "debug" => level <= log::LevelFilter::Debug,
        "info" => level <= log::LevelFilter::Info,
        "warn" => level <= log::LevelFilter::Warn,
        "error" => level <= log::LevelFilter::Error,
        _ => false,
    }
}

async fn fetch(url: &str) {
    match get(url).send().await {
        Ok(response) => {
            let json = response.json::<serde_json::Value>::await?;
            println!("{:#?}", json);
        }
        Err(e) => log::error!("Error fetching data from {}: {}", url, e),
    }
}

async fn process(data: &serde_json::Value) {
    // Process the data here
    println!("Processed data: {:#?}", data);
}

fn main() {
    if let Err(e) = init_logger() {
        log::error!("Failed to initialize logger: {}", e);
        return;
    }

    let args: Vec<String> = env::args().collect();
    let runtime = Runtime::new().unwrap();

    match args.len() {
        1 => println!("Usage: {} <command> [arguments]", args[0]),
        2 => match &args[1] {
            "fetch" => {
                let url = "https://jsonplaceholder.typicode.com/todos/1";
                runtime.block_on(task::spawn(fetch(url)));
            }
            "process" => {
                let data = r#"{"title": "Task", "completed": false}"#;
                runtime.block_on(task::spawn(process(&from_str(data).unwrap())));
            }
            _ => println!("Unknown command: {}", args[1]),
        },
        _ => {
            let cmd = &args[1];
            let args = &args[2..];

            match cmd.as_str() {
                "fetch" => runtime.block_on(task::spawn(fetch(&args[0]))),
                "process" => runtime.block_on(task::spawn(process(&from_str(&args[0]).unwrap()))),
                _ => println!("Unknown command: {}", cmd),
            }
        }
    }
}
```

This example demonstrates a simple logging mechanism, error handling for asynchronous tasks, and support for configuring the log level via an environment variable. It also includes basic examples of fetching data from an API and processing it in memory. You can extend this code to handle more complex command-line arguments and asynchronous functions as needed.']

