```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <limits.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* create_node(int data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void append(Node** head_ref, Node* new_node) {
    if (*head_ref == NULL) {
        *head_ref = new_node;
        return;
    }
    Node* last = *head_ref;
    while (last->next != NULL)
        last = last->next;
    last->next = new_node;
}

int max_element(Node* head) {
    int max = INT_MIN;
    while (head != NULL) {
        if (head->data > max)
            max = head->data;
        head = head->next;
    }
    return max;
}

int count_elements(Node* head) {
    int count = 0;
    while (head != NULL) {
        count++;
        head = head->next;
    }
    return count;
}

void save_to_file(const char* filename, Node* head) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        perror("Error opening the file");
        return;
    }

    Node* current = head;
    while (current != NULL) {
        fprintf(file, "%d\n", current->data);
        current = current->next;
    }

    fclose(file);
}

void print_help() {
    printf("Usage: list_integers [options]\n");
    printf("\nOptions:\n");
    printf("-i, --input <filename>   Use the specified file as input\n");
    printf("-o, --output <filename>  Save output to the specified file\n");
    printf("-h, --help               Display this help message\n");
}

int main(int argc, char* argv[]) {
    Node* head = NULL;
    int max = INT_MIN;
    int count = 0;
    const char* input_filename = NULL;
    const char* output_filename = NULL;

    static struct option long_options[] = {
        {"input", required_argument, 0, 'i'},
        {"output", required_argument, 0, 'o'},
        {"help", no_argument, 0, 'h'},
        {0, 0, 0, 0}
    };

    int option_index = 0;
    while (1) {
        int c = getopt_long(argc, argv, "i:o:h", long_options, &option_index);
        if (c == -1)
            break;

        switch (c) {
            case 'i':
                input_filename = optarg;
                break;
            case 'o':
                output_filename = optarg;
                break;
            case 'h':
                print_help();
                return 0;
            default:
                fprintf(stderr, "Invalid option\n");
                print_help();
                return 1;
        }
    }

    if (input_filename) {
        FILE* file = fopen(input_filename, "r");
        if (!file) {
            perror("Error opening the input file");
            return 1;
        }

        char buffer[10];
        while (fscanf(file, "%s", buffer) != EOF) {
            int number = atoi(buffer);
            if (number <= INT_MIN || number > INT_MAX) {
                fprintf(stderr, "Invalid integer: %s\n", buffer);
                continue;
            }
            append(&head, create_node(number));
            count++;
            max = fmax(max, number);
        }

        fclose(file);
    } else {
        char buffer[10];
        while (fscanf(stdin, "%s", buffer) != EOF) {
            int number = atoi(buffer);
            if (number <= INT_MIN || number > INT_MAX) {
                fprintf(stderr, "Invalid integer: %s\n", buffer);
                continue;
            }
            append(&head, create_node(number));
            count++;
            max = fmax(max, number);
        }
    }

    if (output_filename && head != NULL) {
        save_to_file(output_filename, head);
    }

    printf("Maximum value: %d\n", max);
    printf("Number of elements: %d\n", count);

    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    return 0;
}
```

This program uses a linked list to store the integers and handles both standard input and file input. It supports the `-i`, `--input`, `-o`, and `--output` options for specifying the input and output files, as well as the `-h` or `--help` option for displaying help. The program also checks for invalid inputs and ensures efficient memory usage by freeing the linked list after processing.']

