#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>

typedef void (*hash_func)(const char*, unsigned char*);

struct hash {
    const char *name;
    hash_func func;
    struct hash *next;
};

static struct hash *cache = NULL;
static size_t cache_size = 0;

void add_to_cache(const char *lib, const char *symbol, void *data) {
    if (cache_size >= cache_size) {
        cache_size *= 2;
        struct hash **new_cache = realloc(cache, cache_size * sizeof(struct hash*));
        if (!new_cache) {
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }
        cache = new_cache;
    }

    struct hash *hash = malloc(sizeof(struct hash));
    if (!hash) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }

    hash->name = strdup(symbol);
    hash->func = (hash_func)dlsym(dlopen(lib, RTLD_LAZY), symbol);
    if ((*hash->func) == NULL) {
        fprintf(stderr, "Error loading %s from %s\n", symbol, lib);
        exit(EXIT_FAILURE);
    }
    hash->next = cache[cache_size - 1];
    cache[cache_size - 1] = hash;
}

struct hash *get_hash(const char *name) {
    for (size_t i = 0; i < cache_size; ++i) {
        struct hash *hash = cache[i];
        while (hash != NULL) {
            if (strcmp(hash->name, name) == 0) {
                return hash;
            }
            hash = hash->next;
        }
    }
    return NULL;
}

void cleanup() {
    for (size_t i = 0; i < cache_size; ++i) {
        struct hash *hash = cache[i];
        while (hash != NULL) {
            struct hash *temp = hash;
            hash = hash->next;
            free(temp->name);
            free(temp);
        }
    }
    free(cache);
}
```

This code defines a simple cache for cryptographic hash functions, which are represented by a struct containing their name and function pointer. The `add_to_cache()` function dynamically loads symbols from shared libraries using dlopen/dlsym. The `get_hash()` function searches the cache for a given hash function by name.

The `cleanup()` function releases all allocated resources when needed. This example does not include error handling for missing components or corrupted data in the shared library, as requested. To handle these cases, you can modify the code to check the return values of dlopen and dlsym functions and print appropriate error messages.

For future extensibility, you can add new components by defining their structs and adding them to the cache using `add_to_cache()`. This approach allows for easy addition of new components without significant code changes. However, keep in mind that performance and maintainability may be affected as the cache size increases or when dealing with a large number of components.']

