std::vector<std::string> vec;
std::mutex mtx;
std::function<void(const std::string&)> logCallback;

void updateVectorElements(int i, int j, const std::function<void(int)>& swapLogCallback) {
    if (i < 0 || i >= vec.size() || j < 0 || j >= vec.size()) {
        std::lock_guard<std::mutex> lock(mtx);
        logCallback("Invalid indices, no action taken");
        return;
    }

    if (i == j) return; // No need to swap with self

    auto temp = vec[i];
    vec[i] = vec[j];
    vec[j] = temp;

    logCallback(std::string("Swapped elements at index ") + std::to_string(i) + " and " + std::to_string(j));
}

void log(const std::string& message) {
    if (logCallback) {
        logCallback(message);
    } else {
        std::cout << message << std::endl;
    }
}
```

