```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <atomic>
#include <boost/math/distributions.hpp>

namespace RandomEngine {
    class MTGenerator {
        public:
            MTGenerator(unsigned long seed) : _engine(seed), _instanceCount(0) {
                std::lock_guard<std::mutex> lock(_instancesMutex);
                if (++_instanceCount > 1) {
                    throw std::runtime_error("Only one instance of MTGenerator per thread is allowed.");
                }
            }

            ~MTGenerator() {
                std::lock_guard<std::mutex> lock(_instancesMutex);
                if (--_instanceCount == 0) {
                    _engine.seed(static_cast<unsigned>(std::time(nullptr)));
                }
            }

            int generate(int lowerBound, int upperBound) {
                return _engine() % (upperBound - lowerBound + 1) + lowerBound;
            }

            void reset(unsigned long newSeed) {
                std::lock_guard<std::mutex> lock(_instancesMutex);
                _engine.seed(newSeed);
            }

        private:
            boost::mt19937 _engine;
            static std::atomic<int> _instanceCount;
            static std::mutex _instancesMutex;
    };

    std::atomic<int> MTGenerator::_instanceCount = 0;
    std::mutex MTGenerator::_instancesMutex;
}
```

