    public class PageUpdateController : ControllerBase
    {
        private readonly ConcurrentDictionary<string, UpdateLock> _locks = new ConcurrentDictionary<string, UpdateLock>();
        private readonly IPageRepository _pageRepository;
        private readonly IAuthenticationService _authenticationService;

        public PageUpdateController(IPageRepository pageRepository, IAuthenticationService authenticationService)
        {
            _pageRepository = pageRepository;
            _authenticationService = authenticationService;
        }

        [HttpPost]
        [Route("api/update-element")]
        public async Task<IActionResult> UpdateElement([FromBody] UpdateElementRequest request)
        {
            if (!ModelState.IsValid)
                return BadRequest(ModelState);

            var authenticationResult = await _authenticationService.AuthenticateAsync();
            if (!authenticationResult.Succeeded)
                return Unauthorized(authenticationResult.Errors);

            UpdateLock lockObject;
            if (!_locks.TryAdd(request.PageSectionId, new UpdateLock(request.PageSectionId)))
            {
                // Lock already exists, wait for it to be released
                while (_locks[request.PageSectionId].IsLocked) await Task.Delay(TimeSpan.FromSeconds(1));
                lockObject = _locks[request.PageSectionId];
            }
            else
                lockObject = new UpdateLock(request.PageSectionId);

            try
            {
                var page = await _pageRepository.GetPageAsync(request.PageSectionId);
                if (page == null) throw new Exception($"Page with ID '{request.PageSectionId}' not found.");

                var element = page.Sections.FirstOrDefault(s => s.Id == request.ElementId);
                if (element == null) throw new Exception($"Element with ID '{request.ElementId}' not found in section with ID '{request.PageSectionId}'. ");

                ValidateHtmlContent(request.Content);

                element.Content = request.Content;
                await _pageRepository.SaveChangesAsync();

                lockObject.ReleaseLock();
                _locks.TryRemove(request.PageSectionId, out _);

                LogOperation(operationType: OperationType.Update, pageSectionId: request.PageSectionId, elementId: request.ElementId);

                return Ok();
            }
            catch (Exception ex)
            {
                lockObject.ReleaseLock();
                _locks.TryRemove(request.PageSectionId, out _);

                LogOperation(operationType: OperationType.Error, pageSectionId: request.PageSectionId, elementId: request.ElementId, errorMessage: ex.Message);

                return StatusCode((int)HttpStatusCode.InternalServerError, new { Error = ex.Message });
            }
        }

        private void ValidateHtmlContent(string content)
        {
