class FileAndUserManager {
  constructor() {
    this.fileCache = new Map();
    this.retryCount = 3;
    this.retryInterval = 1000; // milliseconds
  }

  async readFile(filePath) {
    const cachedFile = this.fileCache.get(filePath);

    if (cachedFile) return Promise.resolve(cachedFile);

    try {
      const fileContent = await new Promise((resolve, reject) => {
        const validateFilePath = (path) => {
          // Add your validation logic here
          // For example:
          // if (!fs.existsSync(path)) return false;
          // if (!path.match(/^[\w\/\-\.]+\.[a-zA-Z0-9]+$/)) return false;
          return true;
        };

        if (validateFilePath(filePath)) {
          const readFileStream = fs.createReadStream(filePath);
          let fileData = '';

          readFileStream.on('data', (chunk) => {
            fileData += chunk;
          });

          readFileStream.on('end', () => resolve(fileData));
          readFileStream.on('error', (err) => reject(err));
        } else {
          const errorMessage = `Invalid or non-existent file path: ${filePath}`;
          console.error(`[READ_FILE] Error: ${errorMessage}`);
          return Promise.reject(new CustomError(errorMessage));
        }
      });

      this.fileCache.set(filePath, fileContent);
      return Promise.resolve(fileContent);
    } catch (err) {
      console.error(`[READ_FILE] Error: ${err.message}`);
      if (this.retryCount > 0) {
        setTimeout(() => this.readFile(filePath), this.retryInterval);
        this.retryCount--;
      } else {
        return Promise.reject(new CustomError(`Failed to read file after ${this.retryCount} retries: ${filePath}`));
      }
    }
  }

