async function runTests(label, f, timeout) {
  const startTime = new Date().getTime();
  let result;

  try {
    // Load the module using ES modules syntax
    const module = await import(`./${moduleName}`);

    // Extract the test function from the provided callback
    const testFunction = f;

    // Create a Promise for the test execution
    const testPromise = new Promise(async (resolve, reject) => {
      try {
        // Execute the test function with the module's exports
        await testFunction(module.default);
        resolve();
      } catch (error) {
        reject(error);
      }
    });

    // Timeout the test execution if necessary
    const timeoutPromise = new Promise((_, reject) =>
      setTimeout(() => reject(new Error(`Test "${label}" timed out after ${timeout}ms`)), timeout)
    );

    // Run the test and handle the results
    try {
      await Promise.race([testPromise, timeoutPromise]);
      result = { success: true };
    } catch (error) {
      result = { error };
    }
  } catch (moduleLoadError) {
    result = { error: moduleLoadError };
  }

  // Log the test results and reset the logger for the next test
  logger.log(`Test "${label}": ${JSON.stringify(result)}`);
  logger.reset();

  // Calculate and log the execution time of the test
  const endTime = new Date().getTime();
  const executionTime = endTime - startTime;
  logger.log(`Test "${label}" execution time: ${executionTime}ms`);
}
```

