```javascript
const axios = require('axios'); // Importing Axios for API calls
const fs = require('fs'); // Importing File System for reading external JSON file
const lodash = require('lodash'); // Importing Lodash for utility functions

// Load books data from an external JSON file
const booksData = JSON.parse(fs.readFileSync('books.json', 'utf8'));

// Function to process the text and count book occurrences
function countBookOccurrences(text) {
  // Create an object to store book counts
  const bookCounts = {};

  // Split the text into smaller chunks to improve performance
  const chunkSize = 10000;
  const chunks = lodash.chunk(text, chunkSize);

  let totalRequests = 0;
  let requestsInProgress = 0;

  // Process each chunk concurrently using Promise.all
  const promises = chunks.map((chunk) => {
    return new Promise(async (resolve) => {
      requestsInProgress++;

      // Make API calls for each chunk and cache results
      const apiCalls = chunk
        .toLowerCase()
        .match(/(\b(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b)/g);

      const apiResults = {};
      let apiResult;

      while ((apiResult = apiCalls.shift())) {
        if (!apiResults[apiResult]) {
          totalRequests++;
          apiResults[apiResult] = axios.get(`https://text-processing-api.com/parse?text=${encodeURIComponent(apiResult)}`)
            .then((response) => response.data)
            .catch((error) => console.error(`Error fetching data for ${apiResult}:`, error));
        }

        Promise.all([...Object.values(apiResults)]).then((results) => {
          results.forEach((result) => {
            if (result && result.book) {
              bookCounts[result.book] = (bookCounts[result.book] || 0) + 1;
            }
          });

          requestsInProgress--;
          resolve();
        });
      }
    });
  });

  // Wait for all promises to resolve and handle errors
  Promise.all(promises).catch((error) => console.error(`Error processing text:`, error));

  // Format the output in title case
  return lodash.mapValues(bookCounts, (value, key) => ({ ...key.toTitleCase(), count: value }));
}
```

