function refreshDialogFields(fieldNames, url, retries = 3) {
  const MAX_RETRIES = 3;

  function sendMessage(fieldName) {
    window.parent.postMessage({ type: 'REFRESH_FIELD', fieldName, url }, '*');
  }

  function handleMessage(event) {
    if (event.data && event.data.type === 'REFRESH_FIELD_RESULT') {
      const { fieldName, result, success } = event.data;
      if (success) {
        angular.element(document.querySelector(`[ng-model='${fieldName}']`)).val(result);
      } else {
        // Handle failed update and display error message to the user
      }
    }
  }

  function refreshField(fieldName) {
    let attempts = 0;
    const fieldElement = angular.element(document.querySelector(`[ng-model='${fieldName}']`));

    if (!fieldElement || !fieldElement.length) {
      // Handle case where the field does not exist
      return;
    }

    function updateField() {
      sendMessage(fieldName);
      attempts++;

      if (attempts <= MAX_RETRIES) {
        setTimeout(() => {
          if (!window.parent || !window.parent.postMessage) {
            // Handle network issues or parent window not responding
          } else {
            refreshField(fieldName);
          }
        }, attempts * 1000);
      } else {
        // Handle maximum retries reached
      }
    }

    updateField();
  }

  fieldNames.forEach(refreshField);

  window.addEventListener('message', handleMessage, false);
}
