public class ValueRangeGenerator {
    private static final ExecutorService executor = Executors.newCachedThreadPool();
    private static final ConcurrentMap<Integer, Range> generators = new ConcurrentHashMap<>();

    public static void generate(int type, int min, int max) {
        generators.computeIfAbsent(type, k -> new Range(min, max)).generate();
    }

    private static class Range {
        private final int min;
        private final int max;
        private final Random random = new Random();

        public Range(int min, int max) {
            this.min = min;
            this.max = max;
        }

        public void generate() {
            switch (min <= max ? type : -type) {
                case Integer.TYPE:
                    System.out.println(random.ints(min, max + 1).findFirst().getAsInt());
                    break;
                case Float.TYPE:
                    System.out.println(random.doubles(min / (float) max, 1f).findFirst().floatValue());
                    break;
            }
        }
    }

    public static Map<String, List<String>> calculateEntityWeaknesses(List<Entity> entities) {
        ConcurrentHashMap<String, List<String>> result = new ConcurrentHashMap<>();
        entities.forEach(entity -> result.computeIfAbsent(entity.name, k -> new ArrayList<>()).add(entity.weaknesses));
        return result;
    }
}

class Entity {
    String name;
    List<String> weaknesses;

    public Entity(String name, List<String> weaknesses) {
        this.name = name;
        this.weaknesses = weaknesses;
    }
}
