struct Data {
    int id;
    unsigned char data[1024]; // Adjust size as needed
};

class AsyncReducer {
public:
    using ReduceCallback = std::function<void(const Data&)>;
    AsyncReducer(ReduceCallback reduce_callback, int num_threads);
    void add_data(const Data& data);
    void start();

private:
    ReduceCallback reduce_callback_;
    int num_threads_;
    std::vector<std::thread> threads_;
    std::queue<Data> queue_;
    std::mutex queue_mtx_;
    std::condition_variable cv_;
    bool done_ = false;

    void worker();
};

AsyncReducer::AsyncReducer(ReduceCallback reduce_callback, int num_threads)
    : reduce_callback_(reduce_callback), num_threads_(num_threads) {}

void AsyncReducer::add_data(const Data& data) {
    std::lock_guard<std::mutex> lock(queue_mtx_);
    queue_.push(data);
    cv_.notify_one();
}

void AsyncReducer::start() {
    for (int i = 0; i < num_threads_; ++i) {
        threads_.emplace_back(worker);
    }
    done_ = true;
    cv_.notify_all();
    for (auto& thread : threads_) {
        thread.join();
    }
}

void AsyncReducer::worker() {
    while (true) {
        std::unique_lock<std::mutex> lock(queue_mtx_);
        cv_.wait(lock, [this] { return !queue_.empty() || done_; });

        if (!queue_.empty()) {
            Data data = queue_.front();
            queue_.pop();
            lock.unlock();

            // Perform cryptographic operations here
            // ...

            reduce_callback_(data);
        }
        else if (done_) {
            break;
        }
    }
}

