            }
            "md5" => {
                let mut digest = Digest::md5();
                let message = b"A 'tasty' message";
                tasks.push(task::spawn(async move {
                    tx.send(digest.compute(message).to_vec()).await.expect("Failed to send data");
                }));
            }
            "sha1" => {
                let mut digest = Digest::sha1();
                // ... (Compute SHA-1 hash and send it via the channel)
            }
            "rsa_sign" => {
                let key = openssl::rsa::PemReader::new(include_bytes!("test_key.pem"))
                    .unwrap()
                    .into_rsa(None)
                    .unwrap()
                    .as_private_key()
                    .unwrap();
                let message = b"Signed message";
                let signature = key.sign(EVP_PKEY_RSA, &Digest::sha1(), message).unwrap();
                tasks.push(task::spawn(async move {
                    tx.send(signature).await.expect("Failed to send data");
                }));
            }
            "rsa_verify" => {
                let key = openssl::rsa::PemReader::new(include_bytes!("test_pubkey.pem"))
                    .unwrap()
                    .into_rsa(None)
                    .unwrap()
                    .as_public_key()
                    .unwrap();
                let message = b"Verification message";
                let signature = include_bytes!("test_signature.der");
                tasks.push(task::spawn(async move {
                    key.verify(EVP_PKEY_RSA, &Digest::sha1(), signature, message).unwrap();
                }));
            }
            _ => println!("Unknown task: {}", arg),
        }
    }

    for handle in tasks {
        handle.await;
    }

    let url = "wss://example.com/websocket";
    let (socket, response) = connect_async(url).await.unwrap();

    // Send all received data to the WebSocket
    while let Some(data) = rx.recv().await {
        socket.write_message(Message::Binary(data)).await.unwrap();
    }

    if let Some(result) = response.into_parts().0 {
        println!("WebSocket connection result: {:?}", result);
    }
}
