```java
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.io.File;
import java.nio.file.*;
import java.util.concurrent.*;

public class FileManager {
    private static final Logger logger = LoggerFactory.getLogger(FileManager.class);
    private ExecutorService executor;

    public FileManager() {
        int numberOfThreads = Runtime.getRuntime().availableProcessors();
        executor = Executors.newFixedThreadPool(numberOfThreads);
    }

    public void manageFiles(String[] filePaths, String command) {
        for (String filePath : filePaths) {
            File file = new File(filePath);
            if (!file.exists()) {
                logger.error("File not found: {}", filePath);
                continue;
            }

            try {
                Files.deleteIfExists(file.toPath());
                logger.info("Deleted file: {}", filePath);
            } catch (Exception e) {
                logger.error("Error deleting file: {}", filePath, e);
            }
        }

        Runnable runnable = () -> {
            try {
                Process process = new ProcessBuilder(command, filePaths).start();
                int exitCode = process.waitFor();
                if (exitCode == 0) {
                    logger.info("Command executed successfully");
                } else {
                    logger.error("Command execution failed with exit code: {}", exitCode);
                }
            } catch (Exception e) {
                logger.error("Error executing command", e);
            }
        };

        executor.submit(runnable);
    }
}
```']

