```rust
use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader};
use tokio::sync::mpsc::channel;
use tokio::task::spawn_blocking;
use md5;
use sqlx::Pool;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} <database_url>", args[0]);
        return Ok(());
    }

    let db_url = &args[1];
    let db_pool = Pool::connect(db_url).await?;

    let (sender, receiver) = channel(128);

    for file in std::fs::read_dir(".")? {
        let file = file?;
        let file_path = file.path();
        let file_reader = BufReader::new(File::open(file_path)?);

        spawn_blocking(move || {
            for line in file_reader.lines() {
                if let Ok(line) = line {
                    let hash = md5::compute(line.as_bytes());
                    let hash_string = format!("{:x}", hash);

                    sqlx::query!("INSERT INTO hashes (hash) VALUES ($1)", &hash_string)
                        .execute(db_pool.get()?)
                        .unwrap();
                }
            }
        })
        .spawn()
        .then(|result| {
            match result {
                Ok(_) => {},
                Err(e) => eprintln!("Error processing file: {}", e),
            }
            sender.send(()).unwrap();
        });
    }

    while let Some(_) = receiver.recv().await {}

    Ok(())
}
```

This code reads all files in the current directory, processes each line asynchronously by computing its MD5 hash and storing it in a database using sqlx. The Tokio runtime is used to manage concurrent tasks, ensuring high throughput and low latency.']

