// Set up the maximum file size and allowed extensions
const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10 MB
const ALLOWED_EXTENSIONS = ['jpg', 'jpeg', 'png', 'gif', 'pdf'];

// Define the function for handling file uploads
router.post('/upload', upload.single('file'), async (req, res) => {
  const file = req.file;

  // Validate file size and type
  if (!file || file.size > MAX_FILE_SIZE || !ALLOWED_EXTENSIONS.includes(path.extname(file.originalname).toLowerCase())) {
    return res.status(400).send({ error: 'Invalid file' });
  }

  // Define the API endpoint for the storage service
  const STORAGE_API = 'https://your-storage-service-api.com/upload';

  try {
    // Upload the file to the storage service using Axios
    const response = await axios.post(STORAGE_API, file.buffer, {
      headers: {
        'Content-Type': file.mimetype,
      },
    });

    // Log relevant metadata for auditing purposes
    console.log(`File uploaded: ${file.originalname} - Size: ${file.size} bytes`);
    console.log(`Response status: ${response.status}`);
    console.log(`Upload URL: ${response.data.url}`);

    // Resolve the promise with the uploaded file's URL
    return res.send({ url: response.data.url });
  } catch (error) {
    // Handle network interruptions, API timeouts, and other errors
    console.error(`Error during file upload: ${error}`);

    // Implement customizable retry logic for failed uploads
    if (error.response && error.response.status === 503) {
      // If the server is temporarily unavailable, retry after a delay
