                                                std::function<std::shared_ptr<Octree>(const std::string& element, const std::string& class_, const std::string& id)> initCallback,
                                                const Config& config) {
    if (root.size() > sizeLimit) return nullptr;

    auto octree = initCallback(root, "", "");
    std::vector<std::shared_ptr<Octree>> children;

    // Recursively traverse the DOM and build the octree
    for (auto node : /* Your DOM traversal function here */) {
        std::string element = node->element();
        std::string class_ = node->class_();
        std::string id = node->id();

        domCallback(element, class_, id);

        auto child = initCallback(element, class_, id);
        if (child) {
            octree->addChild(std::move(child));
            children.push_back(child);
        }
    }

    // Balance the octree and handle memory allocation for children
    octree->balance(children, config.leafNodes);

    return octree;
}
