#include <stdio.h>
#include <string.h>
#include <tiffio.h>
#include <exif/ExifTag.h>

typedef struct {
    int orientation;
    char resolution_unit;
    double width, height;
} ImageMetadata;

ImageMetadata process_image(const char *filename) {
    TIFF *tif = TIFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error: Unable to open file %s\n", filename);
        exit(1);
    }

    ImageMetadata metadata;
    metadata.orientation = -1; // Initialize with an invalid value

    // Read EXIF tags
    ttag_t tag;
    for (int i = 0; TIFFGetField(tif, i, &tag); ++i) {
        if (tag == ExifTagNewIFD) {
            for (int j = 0; TIFFGetField(tif, tag, &tag); ++j) {
                if (tag == ExifTagOrientation) {
                    TIFFGetField(tif, tag, &metadata.orientation);
                } else if (tag == ExifTagResolutionUnit) {
                    TIFFGetField(tif, tag, &metadata.resolution_unit);
                } else if (tag == ExifTagXResolution || tag == ExifTagYResolution) {
                    double xr, yr;
                    TIFFGetField(tif, tag, &xr, &yr);
                    metadata.width = xr;
                    metadata.height = yr;
                }
            }
        }
    }

    // Correct orientation if necessary
    switch (metadata.orientation) {
        case 3:
            metadata.width = metadata.height;
            metadata.height = -1 * metadata.width;
            break;
        case 6:
            metadata.width = -1 * metadata.width;
            metadata.height = metadata.height;
            break;
        case 8:
            metadata.width = -1 * metadata.height;
            metadata.height = -1 * metadata.width;
            break;
    }

    TIFClose(tif);
    return metadata;
}
```

