#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define CHAR_SET "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
#define MAX_KEY_LENGTH 10
#define MAX_STRING_LENGTH 50
#define MIN_INT_VALUE 0
#define MAX_INT_VALUE INT_MAX

typedef struct Record {
    long offset;
    int key;
    char* str;
} Record;

int create_records(Record** records, size_t num_records, size_t max_string_length) {
    *records = (Record*)calloc(num_records, sizeof(Record));
    if (*records == NULL) {
        perror("Memory allocation failure");
        return 1;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].offset = i;
        (*records)[i].key = i + 1;

        size_t key_length = strlen((*records)[i].key);
        if (key_length > MAX_KEY_LENGTH) {
            fprintf(stderr, "Key length exceeded maximum allowed value\n");
            free(*records);
            return 2;
        }

        size_t str_len = key_length + max_string_length + 1;
        (*records)[i].str = (char*)calloc(str_len, sizeof(char));
        if ((*records)[i].str == NULL) {
            fprintf(stderr, "Memory allocation failure for string\n");
            for (size_t j = 0; j < i; ++j) free((*records)[j].str);
            free(*records);
            return 1;
        }

        srand(time(NULL) + i);
        int random_int = rand() % (MAX_INT_VALUE - MIN_INT_VALUE + 1) + MIN_INT_VALUE;
        (*records)[i].key = random_int;

        for (size_t j = 0; j < str_len; ++j) {
            if (j < key_length) (*records)[i].str[j] = (*records)[i].key[j];
            else (*records)[i].str[j] = CHAR_SET[rand() % strlen(CHAR_SET)];
        }
        (*records)[i].str[str_len - 1] = '\0';
    }

    return 0;
}

void free_records(Record* records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) free(records[i].str);
    free(records);
}
```

