bool add_node(RX_UE_INFORMATION_TAG tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication) {
    pthread_mutex_lock(&list_lock);
    Node* current = head;
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list_lock);
        return false;
    }

    new_node->tag = tag;
    new_node->rnti = rnti;
    new_node->crc_indication = crc_indication;
    new_node->next = NULL;

    while (current->next && current != head) {
        current = current->next;
    }

    current->next = new_node;
    pthread_mutex_unlock(&list_lock);
    return true;
}

void trim() {
    pthread_mutex_lock(&list_lock);
    Node* current = head->next;
    Node* temp;

    while (current && max_size > 1) {
        temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list_lock);
}

void clear() {
    pthread_mutex_lock(&list_lock);
    Node* current = head->next;
    Node* next;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    head->next = NULL;
    pthread_mutex_unlock(&list_lock);
}
```

