#include <stdio.h>
#include <string.h>

#define MAX_CONNECTIONS 10
static int num_connections = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int create_socket(const char *protocol, const char *address, int port) {
    int sockfd, opt = 1;
    struct sockaddr_in serv_addr;
    struct hostent *server;

    if ((server = gethostbyname(address)) == NULL) {
        perror("gethostbyname");
        return -1;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(port);
    serv_addr.sin_addr = *((struct in_addr *)server->h_addr);

    if ((sockfd = socket(AF_INET, (protocol[0] == 't') ? SOCK_STREAM : SOCK_DGRAM, 0)) < 0) {
        perror("socket");
        return -1;
    }

    if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(sockfd);
        return -1;
    }

    if ((protocol[0] == 't') && (bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0)) {
        perror("bind");
        close(sockfd);
        return -1;
    }

    if ((protocol[0] == 't') && (listen(sockfd, SOMAXCONN) < 0)) {
        perror("listen");
        close(sockfd);
        return -1;
    }

    pthread_mutex_lock(&mutex);
    num_connections++;
    if (num_connections > MAX_CONNECTIONS) {
        printf("Maximum number of connections reached\n");
        pthread_mutex_unlock(&mutex);
        close(sockfd);
        return -1;
    }
    pthread_mutex_unlock(&mutex);

    if (protocol[0] == 't') {
        return accept(sockfd, NULL, NULL);
    } else {
        return sockfd;
    }
}
```

