    void add(const NFAPI_CRC_INDICATION_PDU_T& data);
    bool update(int index, const NFAPI_CRC_INDICATION_PDU_T& data);
    bool remove(int index);

private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> list;
    sqlite3* db;

    // Database schema and table creation functions omitted for brevity

    void setRandomCRCFlag(NFAPI_CRC_INDICATION_PDU_T& data) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::bernoulli_distribution dist(0.5); // 50% chance of setting crcFlag to true
        data.crcFlag = dist(gen);
    }

    void saveToDatabase() {
        char* errMsg = nullptr;
        sqlite3_exec(db, "BEGIN TRANSACTION", nullptr, nullptr, &errMsg);
        if (errMsg) {
            std::cerr << "Error starting transaction: " << errMsg << std::endl;
            sqlite3_free(errMsg);
        }

        for (const auto& data : list) {
            char sql[256];
            snprintf(sql, sizeof(sql),
                     "INSERT INTO indications VALUES('%d', '%d', '%d', %s)",
                     data.tag, data.rnti, data.crcTag, data.crcFlag ? "1" : "0");
            char* errMsg = nullptr;
            int rc = sqlite3_exec(db, sql, nullptr, nullptr, &errMsg);
            if (rc != SQLITE_OK) {
                std::cerr << "Error inserting data: " << errMsg << std::endl;
                sqlite3_free(errMsg);
            }
        }

        sqlite3_exec(db, "COMMIT", nullptr, nullptr, &errMsg);
        if (errMsg) {
            std::cerr << "Error committing transaction: " << errMsg << std::endl;
            sqlite3_free(errMsg);
        }
    }
};
