```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t UE_ID;
    uint8_t SFI;
    uint8_t UL_CCCH_MESSAGE_TYPE;
    NFAPI_RRC_MESSAGES *RRC_MESSAGES;
    pthread_mutex_t lock;
} NFAPI_UL_CCCH_MSG_T;

NFAPI_UL_CCCH_MSG_T* create_message(uint32_t UE_ID, uint8_t SFI, uint8_t UL_CCCH_MESSAGE_TYPE) {
    NFAPI_UL_CCCH_MSG_T *msg = (NFAPI_UL_CCCH_MSG_T *)calloc(1, sizeof(NFAPI_UL_CCCH_MSG_T));
    msg->UE_ID = UE_ID;
    msg->SFI = SFI;
    msg->UL_CCCH_MESSAGE_TYPE = UL_CCCH_MESSAGE_TYPE;
    msg->RRC_MESSAGES = NULL;
    pthread_mutex_init(&msg->lock, NULL);
    return msg;
}

void add_rrc_message(NFAPI_UL_CCCH_MSG_T *msg, NFAPI_RRC_MESSAGE rrc_message) {
    NFAPI_RRC_MESSAGES *messages = realloc(msg->RRC_MESSAGES, sizeof(NFAPI_RRC_MESSAGE) * (msg->RRC_MESSAGES ? msg->RRC_MESSAGES_len + 1 : 1));
    if (!messages) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    messages[msg->RRC_MESSAGES_len++] = rrc_message;
    msg->RRC_MESSAGES = messages;
}

void *process_message(void *arg) {
    NFAPI_UL_CCCH_MSG_T *msg = arg;
    // Process the message asynchronously
    pthread_mutex_lock(&msg->lock);
    // Process RRC_MESSAGES here
    for (size_t i = 0; i < msg->RRC_MESSAGES_len; ++i) {
        // Simulate processing delay
        usleep(1000 * rand() % 5000);
        // Process each RRC_MESSAGE here
    }
    pthread_mutex_unlock(&msg->lock);

    static uint64_t last_time = 0;
    static uint64_t messages_processed = 0;
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    double elapsed_seconds = (double)(now.tv_sec - last_time) + (double)(now.tv_nsec - last_time * 1e9) / 1e9;
    messages_processed += msg->RRC_MESSAGES_len;
    last_time = now.tv_sec;

    printf("Processed %llu messages in %.2fs\n", messages_processed, elapsed_seconds);
    return NULL;
}

void init_dynamic_array(NFAPI_UL_CCCH_MSG_T **messages, size_t N) {
    *messages = (NFAPI_UL_CCCH_MSG_T *)calloc(N, sizeof(NFAPI_UL_CCCH_MSG_T));
    if (!*messages) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < N; ++i) {
        (*messages)[i] = create_message(i + 1, i % 5, i % 3);
    }
}

void free_dynamic_array(NFAPI_UL_CCCH_MSG_T *messages, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        free(messages[i].RRC_MESSAGES);
        pthread_mutex_destroy(&messages[i].lock);
        free(messages + i);
    }
    free(messages);
