constexpr size_t MAX_ELEMENTS = 10000;
constexpr size_t STRING_LENGTH_MAX = 32;
constexpr int MIN_INT_VALUE = 0;
constexpr int MAX_INT_VALUE = 1000000;
constexpr char* PRINTABLE_ASCII_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=[]{}|;:'\",.<>?/";

struct Record {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
    long offset;
    int key;
    std::string data;
};

class DynamicList {
public:
    enum class StatusCode { SUCCESS, LIST_FULL, INVALID_RNTI, MEMORY_ERROR };

    DynamicList() : list{}, currentSize{ 0 } {}

    StatusCode add(const Record& record) {
        if (currentSize >= MAX_ELEMENTS) return StatusCode::LIST_FULL;

        list.emplace_back(record);
        ++currentSize;
        return StatusCode::SUCCESS;
    }

    StatusCode update(int rnti, const Record& newRecord) {
        if (rnti < 1 || rnti > currentSize) return StatusCode::INVALID_RNTI;

        auto it = std::find_if(list.begin(), list.end(), [rnti](const Record& record) { return record.key == rnti; });
        if (it == list.end()) return StatusCode::INVALID_RNTI;

        *it = newRecord;
        return StatusCode::SUCCESS;
    }

    StatusCode remove(int index) {
        if (index < 0 || index >= currentSize) return StatusCode::INVALID_RNTI;

        list.erase(list.begin() + index);
        --currentSize;
        return StatusCode::SUCCESS;
    }

    int getCurrentSize() const { return currentSize; }

private:
    std::vector<Record> list;
    int currentSize;
};

