    record.data[rand() % (STRING_LENGTH_MAX + 1 - strlen(record.data))] = '\0'; // Randomly truncate the string further if needed
    record.intField = rand() % (MAX_INT_VALUE - MIN_INT_VALUE + 1) + MIN_INT_VALUE;
}

int main() {
