    size_t count;
    double sum;
} DataSet;

void clear_input() {
    char c;
    while ((c = getchar()) != '\n' && c != EOF);
}

DataSet* create_dataset(size_t max_entries) {
    DataSet* set = (DataSet*)malloc(sizeof(DataSet));
    if (!set) return NULL;

    set->numbers = (double*)calloc(max_entries, sizeof(double));
    if (!set->numbers) {
        free(set);
        return NULL;
    }

    set->count = 0;
    set->sum = 0.0;
    return set;
}

void destroy_dataset(DataSet* set) {
    free(set->numbers);
    free(set);
}

int validate_number(double number, void* arg) {
