    // Return 0 for valid numbers and non-zero for invalid ones.
    return (number < 0 || number > 100) ? 1 : 0;
}

void* read_and_validate(void* arg) {
    DataSet* set = arg;
    double number;

    while (fscanf(stdin, "%lf", &number) == 1 && !feof(stdin)) {
        if (!validate_number(number, set)) {
            set->numbers[set->count] = number;
            set->sum += number;
            set->count++;
        } else {
            printf("Invalid input: %lf. Skipping.\n", number);
        }
        clear_input();
    }

    return NULL;
}

void print_average(DataSet* set) {
    if (set->count == 0) {
        printf("No data available.\n");
        return;
    }

    double average = set->sum / set->count;
    printf("Average: %.2f\n", average);
}

int main(int argc, char** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s max_entries\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t max_entries = atoi(argv[1]);
    DataSet* set = create_dataset(max_entries);

    pthread_t threads[max_entries];

    for (size_t i = 0; i < max_entries; ++i) {
        pthread_create(&threads[i], NULL, read_and_validate, set);
    }

    for (size_t i = 0; i < max_entries; ++i) {
        pthread_join(threads[i], NULL);
    }

    print_average(set);
    destroy_dataset(set);

    return EXIT_SUCCESS;
}
