struct NetworkInterfaceStatusReport {
    std::string name;
    double packetLossRate;
    double throughput;
    double latency;
    bool operationalMode;
};

std::mutex g_dataMutex;
std::vector<NetworkInterfaceStatusReport> g_networkInterfaces;
std::queue<NetworkInterfaceStatusReport> g_updatesQueue;
std::condition_variable g_cv;

void updateNetworkInterface(const NetworkInterfaceStatusReport& report) {
    std::unique_lock<std::mutex> lock(g_dataMutex);
    g_updatesQueue.push(report);
    g_cv.notify_one();
}

void processUpdates() {
    for (;;) {
        std::unique_lock<std::mutex> lock(g_dataMutex);
        g_cv.wait(lock, [] { return !g_updatesQueue.empty(); });

        if (!g_updatesQueue.empty()) {
