};

alignas(64) struct MAC_CONTEXT {
    std::vector<std::unique_ptr<SRB_CONFIG>> srbConfigs;
    std::vector<std::unique_ptr<SRB_BUFFER, std::default_delete<SRB_BUFFER>>> srbBuffers;
    std::mutex mtx;
};

class MAC_CONTEXT_MANAGER {
private:
    std::vector<std::unique_ptr<MAC_CONTEXT>> contexts;
    static std::mutex managerMtx;

public:
    static MAC_CONTEXT* createContext(size_t numSrb) {
        std::lock_guard<std::mutex> lock(managerMtx);
        auto context = std::make_unique<MAC_CONTEXT>();
        if (!context || !context->srbConfigs.reserve(numSrb) || !context->srbBuffers.reserve(numSrb)) {
            context.reset();
            return nullptr;
        }
        for (size_t i = 0; i < numSrb; ++i) {
            if (!context->srbConfigs.emplace_back() || !context->srbBuffers.emplace_back(new SRB_BUFFER)) {
                context->clear(); // Free resources and reset the context
                context.reset();
                return nullptr;
            }
        }
        contexts.push_back(std::move(context));
        std::cout << "Created MAC_CONTEXT instance\n";
        return contexts.back().get();
    }

    static void destroyContext(MAC_CONTEXT* context) {
        if (!context) return;
        std::lock_guard<std::mutex> lock(context->mtx);
        context->clear(); // Free resources and reset the context
        contexts.erase(std::remove_if(contexts.begin(), contexts.end(), [context](const auto& c) { return c.get() == context; }));
        delete context;
    }

    static void logStats() {
        std::lock_guard<std::mutex> lock(managerMtx);
        std::cout << "Number of created MAC_CONTEXT instances: " << contexts.size() << "\n";
    }
};

