// Implement the main function to initialize and run the network service
void start_network_service() {
    // Initialize data structures, signal handlers, and logging system

    // Bind sockets for TCP and UDP protocols
    int tcp_socket = socket(AF_INET, SOCK_STREAM, 0);
    int udp_socket = socket(AF_INET, SOCK_DGRAM, 0);

    struct sockaddr_in tcp_addr, udp_addr;
    memset(&tcp_addr, 0, sizeof(tcp_addr));
    memset(&udp_addr, 0, sizeof(udp_addr));

    tcp_addr.sin_family = AF_INET;
    tcp_addr.sin_port = htons(TCP_PORT);
    tcp_addr.sin_addr.s_addr = INADDR_ANY;

    udp_addr.sin_family = AF_INET;
    udp_addr.sin_port = htons(UDP_PORT);
    udp_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(tcp_socket, (struct sockaddr*)&tcp_addr, sizeof(tcp_addr)) < 0 ||
        bind(udp_socket, (struct sockaddr*)&udp_addr, sizeof(udp_addr)) < 0) {
        perror("Bind error");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections and handle them concurrently using threads
    listen(tcp_socket, MAX_CONCURRENT_CONNECTIONS);
    listen(udp_socket, SOMAXCONN);

    Poller poller;
    poller.timeout = time(NULL) + CONNECTION_TIMEOUT;

    while (true) {
        FD_ZERO(&poller.readfds);
        FD_ZERO(&poller.writefds);

        FD_SET(tcp_socket, &poller.readfds);
        FD_SET(udp_socket, &poller.readfds);

        int maxfd = tcp_socket > udp_socket ? tcp_socket : udp_socket;

        if (select(maxfd + 1, &poller.readfds, NULL, NULL, &poller.timeout) <= 0) {
            // Timeout or error occurred, handle resource exhaustion scenarios
            handle_resource_exhaustion();
            continue;
        }

        if (FD_ISSET(tcp_socket, &poller.readfds)) {
            Connection* new_conn = accept(tcp_socket, NULL, NULL);
            if (new_conn) {
                enqueue_connection(new_conn);
                distribute_traffic(new_conn);
            }
        }

        if (FD_ISSET(udp_socket, &poller.readfds)) {
