```cpp
void DoublyLinkedList::add(const NFAPI_CRC_INDICATION_PDU_T& data) {
    // Check if the list is full and handle fragmentation issues
    // ...

    std::unique_lock<std::mutex> lock(mtx_);

    Node* newNode = new Node{data, nullptr, nullptr};
    if (buffer_.empty()) {
        buffer_.push_back(*newNode);
    } else {
        auto last = buffer_.back();
        last->next = newNode;
        newNode->prev = &last;
        buffer_.push_back(*newNode);
    }
}

bool DoublyLinkedList::remove(uint32_t rnti) {
    std::unique_lock<std::mutex> lock(mtx_);

    auto it = buffer_.begin();
    while (it != buffer_.end()) {
        if (it->data.rnti == rnti) {
            if (it == buffer_.begin()) {
                buffer_.pop_front();
            } else if (it == buffer_.get_back()) {
                buffer_.pop_back();
            } else {
                it->prev->next = it->next;
                it->next->prev = it->prev;
                buffer_.erase(it);
                delete it;
            }
            return true;
        }
        ++it;
    }
    return false;
}

size_t DoublyLinkedList::size() const {
    std::unique_lock<std::mutex> lock(mtx_);
    return buffer_.size();
}

uint64_t DoublyLinkedList::sumOfRNTIs() const {
    uint64_t sum = 0;
    std::unique_lock<std::mutex> lock(mtx_);
    for (const auto& node : buffer_) {
        sum += node.data.rnti;
    }
    return sum;
}

