void logListOperations(DoublyLinkedList& list, uint32_t interval) {
    boost::asio::io_service ioService;
    boost::asio::deadline_timer timer(ioService, boost::posix_time::seconds(interval));

    while (true) {
        timer.async_wait([&](const boost::system::error_code& ec) {
            if (!ec) {
                BOOST_LOG_TRIVIAL(info) << "List operations: Added=" << list.size() - oldSize_ << ", Removed=" << oldSize_ - list.size();
                oldSize_ = list.size();
            }
            timer.expires_at(timer.expiry() + boost::posix_time::seconds(interval));
            ioService.run_one();
        });
    }
}
