int dns_resolve_wait(DnsResolver* resolver, int timeout_ms) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec = (timeout_ms % 1000) * 1000000;

    pthread_mutex_lock(&resolver->lock);
    while (true) {
        if (!resolver->error_code && memcmp(resolver->ip_address, "\0", 4) != 0) {
            break;
        }

        pthread_cond_wait(&resolver->cond, &resolver->lock);
        clock_gettime(CLOCK_REALTIME, &ts);
        if (timespecdiff(ts, resolver->start_time, &ts) > ts) {
            resolver->error_code = TIMEOUT;
            break;
        }
    }
    pthread_mutex_unlock(&resolver->lock);

    return resolver->error_code;
}
```

