```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <thread>
#include <mutex>
#include <random>
#include <cstdlib>
#include <ctime>

struct Record {
    int value;
};

class DataContainer {
public:
    DataContainer(size_t offsetSize, size_t keySize, size_t recordSize) :
        offsets_(offsetSize), keys_(keySize), records_(recordSize), index_(0) {}

    ~DataContainer() {
        free(offsets_);
        free(keys_);
        free(records_);
    }

    bool initialize(const std::string& offsetFilePath, const std::string& keyFilePath) {
        std::ifstream offsetFile(offsetFilePath);
        if (!offsetFile.is_open()) {
            std::cerr << "Error opening offset file: " << offsetFilePath << std::endl;
            return false;
        }

        std::ifstream keyFile(keyFilePath);
        if (!keyFile.is_open()) {
            std::cerr << "Error opening key file: " << keyFilePath << std::endl;
            return false;
        }

        loadData(offsetFile, keys_, index_);
        loadData(keyFile, offsets_, index_);

        // Initialize records with random values within a specified range
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, INT_MAX / 2);

        for (size_t i = 0; i < index_; ++i) {
            records_[i].value = dis(gen);
        }

        return true;
    }

    Record& getRecordByKey(int key) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (size_t i = 0; i < index_; ++i) {
            if (keys_[i] == key) {
                return records_[i];
            }
        }
        throw std::out_of_range("Key not found");
    }

private:
    void loadData(std::istream& input, std::vector<long>& data, size_t& index) {
        long value;
        while (input >> value) {
            if (index >= data.size()) {
                data.resize(data.size() * 2);
            }
            data[index++] = value;
        }
    }

    std::vector<long> offsets_;
    std::vector<int> keys_;
    std::vector<Record> records_;
    size_t index_;
    mutex mutex_;
};

// Example usage:
int main() {
    DataContainer container(1024, 1024, 65536);
    if (container.initialize("offsets.txt", "keys.txt")) {
        Record record = container.getRecordByKey(42);
        std::cout << "Record with key 42 has value: " << record.value << std::endl;
    } else {
        std::cerr << "Failed to initialize data container" << std::endl;
    }
}
```

This implementation uses C++11 features and provides a `DataContainer` class that handles the dynamic memory allocation, initializes the arrays with data from external files, generates random values for records, and offers a thread-safe interface to retrieve records by key. The code also includes error handling for potential issues during initialization and resource management upon destruction.']

