CryptoInfo parse_image_and_configure_cipher(const char *filename) {
    CryptoInfo crypto_info = {NULL, 0};

    // Initialize image processing and color management libraries
    tif_t *tif = TIFFOpen(filename, "r");
    if (!tif) {
