        TIFFClose(tif);
        return crypto_info;
    }

    // Determine the appropriate cipher based on image metadata and user preferences
    EVP_CIPHER *cipher = determine_cipher(bits_per_sample, samples_per_pixel, num_extra_samples);
    if (!cipher) {
        TIFFClose(tif);
        fprintf(stderr, "Error: Unsupported bit depth or cipher configuration\n");
        return crypto_info;
    }

    // Initialize the selected cipher and configure it for the image data
    crypto_info.cipher = cipher;
    crypto_info.status = initialize_cipher(cipher);
    if (crypto_info.status != 0) {
        fprintf(stderr, "Error: Unable to initialize cipher\n");
        EVP_CIPHER_free(cipher);
        TIFFClose(tif);
        return crypto_info;
    }

    // Perform any necessary image preprocessing or encryption setup
    prepare_image_for_encryption(tif, cipher);

    // Close the image file and color management libraries
