[' Here's a simplified C++ program that addresses some of the requirements you've mentioned. Note that this is a basic implementation and may not cover all edge cases or optimizations, but it should give you a good starting point.

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <string>
#include <locale>
#include <utility>
#include <cmath>
#include <boost/program_options.hpp>

namespace po = boost::program_options;

struct DataPoint {
    std::string label;
    std::vector<double> measurements;
};

std::istringstream& split(const std::string &s, char delimiter, std::istringstream &ss) {
    ss.clear();
    ss.str(s);
    std::string item;
    while (std::getline(ss, item, delimiter)) {
        if (!item.empty()) {
            ss << item;
        }
    }
    return ss;
}

DataPoint parse_line(const std::string &line) {
    DataPoint dp;
    std::istringstream lineStream(line);
    std::string label;
    double measurement;

    split(line, ',', lineStream);
    if (lineStream >> label) {
        dp.label = label;
        while (lineStream >> measurement) {
            if (measurement >= 0) {
                dp.measurements.push_back(measurement);
            }
        }
    }
    return dp;
}

void process_data(const std::vector<DataPoint> &data) {
    double sum = 0;
    std::map<std::string, int> labelsCount;

    for (const auto &dp : data) {
        for (const auto &m : dp.measurements) {
            if (m >= 0) {
                sum += m;
            }
        }

        auto it = labelsCount.find(dp.label);
        if (it == labelsCount.end()) {
            labelsCount[dp.label] = 1;
        } else {
            it->second++;
        }
    }

    double avg = sum / std::accumulate(data.begin(), data.end(), 0, [](int a, const auto &b) { return a + b.measurements.size(); });
    std::string mostFrequentLabel = *(std::max_element(labelsCount.begin(), labelsCount.end(), [](const auto &a, const auto &b) { return a.second < b.second; }));

    std::cout << "Average: " << avg << "\n";
    std::cout << "Most Frequent Label: " << mostFrequentLabel << "\n";
}

int main(int argc, char *argv[]) {
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help", "Print help messages")
        ("input-file", po::value<std::string>()->default_value("data.csv"), "Input CSV file")
        ("encoding", po::value<std::string>(), "Encoding of the input file (e.g., UTF-8)")
        ("line-ending", po::value<std::string>(), "Line ending of the input file (e.g., LF, CRLF)");

    po::variables_map vm;
    po::store(po::parse_command_line(argc, argv, desc), vm);
    po::notify(vm);

    if (vm.count("help")) {
        std::cout << desc << "\n";
        return 0;
    }

    std::ifstream file(vm["input-file"].as<std::string>(), std::ios_base::in);
    if (!file) {
        std::cerr << "Unable to open file: " << vm["input-file"].as<std::string>() << "\n";
        return 1;
    }

    file.imbue(std::locale(file.getloc(), new std::codecvt_utf8<wint_t>));
    file.imbue(std::locale("", new std::mbr_stateutfcb<wint_t>()));

    std::string line;
    std::vector<DataPoint> data;

    while (std::getline(file, line)) {
        DataPoint dp = parse_line(line);
        if (!dp.label.empty()) {
            data.push_back(dp);
        }
    }

    process_data(data);

    return 0;
}
