```c
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char *key;
    unsigned int key_len;
    unsigned char *iv;
    unsigned int iv_len;
} AESGCM_CTX;

void aes_gcm_init(const char *passphrase, size_t iv_length, int iterations,
                   size_t key_size, size_t block_size,
                   void (*log_event)(const char *event),
                   void (*log_error)(const char *error)) {
    AESGCM_CTX ctx;
    unsigned char pass[256], salt[16];
    EVP_CIPHER_KEYSIZE key_size_aes256gcm = AES_256_GCM_KEYLENGTH;
    int der_key_len, der_iv_len;

    // Generate a random salt for PBKDF2
    if (RAND_bytes(salt, sizeof(salt)) <= 0) {
        log_error("Failed to generate random salt");
        return;
    }

    // Derive the key and IV using PBKDF2 with the given passphrase and parameters
    der_key_len = EVP_PBKDF2_HMAC(EVP_sha256(), passphrase, strlen(passphrase), salt, sizeof(salt), iterations, key_size_aes256gcm, &ctx.key);
    if (der_key_len <= 0) {
        log_error("Failed to derive AES-256-GCM key");
        return;
    }

    der_iv_len = iv_length < block_size ? iv_length : block_size;
    if (der_iv_len != EVP_CIPHER_block_size(EVP_aes_256_gcm())) {
        log_error("Invalid IV length");
        return;
    }

    // Derive the IV using PBKDF2 with the given passphrase and parameters
    if (RAND_bytes(ctx.iv, der_iv_len) <= 0) {
        log_error("Failed to generate random IV");
        return;
    }
    der_iv_len = EVP_PBKDF2_HMAC(EVP_sha256(), passphrase, strlen(passphrase), ctx.iv, der_iv_len, iterations, der_iv_len, NULL);
    if (der_iv_len <= 0) {
        log_error("Failed to derive AES-256-GCM IV");
        return;
    }

    // Initialize the cipher context with the derived key and IV
    if (1 != EVP_EncryptInit_ex(&ctx.ctx, EVP_aes_256_gcm(), NULL, ctx.key, ctx.iv)) {
        log_error("Failed to initialize AES-256-GCM cipher");
        return;
    }

    // Log initialization events
    log_event("AES-256-GCM key derived");
    log_event("AES-256-GCM IV derived");
    log_event("AES-256-GCM cipher initialized");

    ctx.key_len = der_key_len;
    ctx.iv_len = der_iv_len;
}

// ... (Other functions for encrypting, decrypting, releasing resources, etc.)
```

