    public async Task<JToken?> FindFirstMatchingElementAsync(string key, Func<JToken, bool> predicate, CancellationToken cancellationToken = default)
    {
        var root = _jsonDocument.RootElement;

        return await TraverseAndFindAsync(root, key, predicate, cancellationToken);
    }

    private async Task<JToken?> TraverseAndFindAsync(JToken current, string key, Func<JToken, bool> predicate, CancellationToken cancellationToken)
    {
        if (current == null || string.IsNullOrEmpty(key))
            return null;

        var tokenType = current.Type;

        if (tokenType == JTokenType.Array)
        {
            for (int i = 0; i < current.Count && !cancellationToken.IsCancellationRequested; i++)
            {
                var result = await TraverseAndFindAsync(current[i], key, predicate, cancellationToken);
                if (result != null)
                    return result;
            }
        }
        else if (tokenType == JTokenType.Object)
        {
            if (current.TryGetValue(key, out var value))
            {
                if (predicate(value))
                    return value;
            }

            foreach (var property in current.Children())
            {
                var result = await TraverseAndFindAsync(property.Value, key, predicate, cancellationToken);
                if (result != null)
                    return result;
            }
        }

        return null;
    }
}
```

This code defines a `JsonProcessor` class that takes a JSON string and provides an asynchronous method to find the first matching element based on a specified key and predicate. The function uses recursion to traverse through the JSON structure, handling arrays and objects separately. It also supports cancellation tokens for managing long-running operations or partial data updates.

To use this code, you'll need to install the Newtonsoft.Json NuGet package:

```sh
Install-Package Newtonsoft.Json
```"]

