struct ConfigError { enum ErrorCode { EmptyPassword, NullCallback, InvalidTitle }; };

struct Config {
    std::string title;
    std::string password;
    std::function<void()> callback;

    bool validate() const {
        if (password.empty()) return false;
        if (!callback) return false;
        if (title.empty()) return false;
        return true;
    }
};

std::unique_ptr<Config> parse_config(const std::string& filepath) {
    std::ifstream config_file(filepath);
    if (!config_file.is_open()) throw ConfigError::ErrorCode::InvalidTitle;

    std::string line;
    std::unique_ptr<Config> config = std::make_unique<Config>();
    while (std::getline(config_file, line)) {
        std::istringstream iss(line);
        std::string key, value;
        std::getline(iss, key, ':');
        std::getline(iss, value);

        if (key == "title") config->title = value;
        else if (key == "password") config->password = value;
        else if (key == "callback") {
            try {
                config->callback = [=]() { std::function<void()> func; std::istringstream iss(value); iss >> func; func(); };
            } catch (...) {
                throw ConfigError::ErrorCode::NullCallback;
            }
        }
    }

    if (!config->validate()) throw ConfigError::ErrorCode::EmptyPassword;
    return config;
}

int main(int argc, char* argv[]) {
