            if (it != tasks.end()) it->second();
            else if (argv[i] == "--help") {
                // Print help message
            }
        } else if (argv[1]) {
            try {
                auto config = parse_config(argv[i]);
                config->callback();
            } catch (const ConfigError::ErrorCode& e) {
                std::cerr << "Configuration error: " << e << '\n';
                return 1;
            }
        }
    }

    return 0;
}
```

