    ~ThreadSafeList() {
        clear();
        delete [] allocator_;
    }

    void push_back(const NFAPI_CRC_INDICATION_PDU_T& data) {
        std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T, decltype(&free)> new_node(static_cast<NFAPI_CRC_INDICATION_PDU_T*>(allocator_.allocate(sizeof(NFAPI_CRC_INDICATION_PDU_T))), free);
        std::copy(std::begin(data), std::end(data), new_node.get());

        pthread_mutex_lock(&mutex_);
        if (head_ == nullptr) {
            head_ = tail_ = new_node.release();
        } else {
            tail_->next_ = new_node.release();
            tail_ = tail_->next_;
        }
        pthread_mutex_unlock(&mutex_);
    }

    void pop_front() {
        if (head_ == nullptr) return;

        NFAPI_CRC_INDICATION_PDU_T* temp = head_;
        pthread_mutex_lock(&mutex_);
        head_ = head_->next_;
        if (head_ == nullptr) tail_ = nullptr;
        pthread_mutex_unlock(&mutex_);

        allocator_.deallocate(temp, 1);
    }

    void clear() {
        NFAPI_CRC_INDICATION_PDU_T* current = head_;
        while (current != nullptr) {
            NFAPI_CRC_INDICATION_PDU_T* temp = current;
            current = current->next_;
            allocator_.deallocate(temp, 1);
        }
        head_ = tail_ = nullptr;
    }

private:
    std::list<NFAPI_CRC_INDICATION_PDU_T>::iterator head_;
    std::list<NFAPI_CRC_INDICATION_PDU_T>::iterator tail_;
    pthread_mutex_t mutex_;
    void* allocator_[sizeof(NFAPI_CRC_INDICATION_PDU_T)];
};
```

This implementation uses a custom allocator to ensure thread safety and proper memory management. The `ThreadSafeList` class provides methods for pushing elements onto the list (`push_back`) and popping them off (`pop_front`). It also includes a `clear` method for cleaning up all allocated resources when the list is no longer needed.

The custom allocator uses `malloc` and `free` to allocate and deallocate memory, which can be replaced with other thread-safe allocation mechanisms if necessary. The linked list itself is implemented using a C++ STL list, providing efficient insertion and deletion operations.

