```cpp
#include <vector>
#include <unordered_map>
#include <chrono>
#include <iostream>

class GameCharacter {
public:
    struct Attack {
        int id;
        int costEnergy;
        int costStamina;
        int cooldown;
        float effectiveness;
    };

    GameCharacter(const std::vector<Attack>& attacks, int initialEnergy, int initialStamina)
        : m_attacks(attacks), m_energy(initialEnergy), m_stamina(initialStamina), m_lastAttackTime(std::chrono::steady_clock::now()) {}

    void performAttack() {
        auto availableAttacks = getAvailableAttacks();
        if (availableAttacks.empty()) {
            std::cout << "No attacks available.\n";
            return;
        }

        Attack chosenAttack = chooseAttack(availableAttacks);
        performAttack(chosenAttack);
    }

    void update(float deltaTime) {
        auto currentTime = std::chrono::steady_clock::now();
        float elapsedSeconds = std::chrono::duration<float>(currentTime - m_lastAttackTime).count();

        if (elapsedSeconds >= 1.0f) { // Adjustable global cooldown timer reset condition
            m_globalCooldown -= elapsedSeconds;
            m_lastAttackTime = currentTime;
        }

        m_energy += m_energyRegenRate * deltaTime;
        m_stamina += m_staminaRegenRate * deltaTime;

        // Simulate environmental factors affecting energy regen rate and stamina regen rate
        m_energyRegenRate *= getEnvironmentFactorForEnergy();
        m_staminaRegenRate *= getEnvironmentFactorForStamina();
    }

private:
    std::vector<Attack> m_attacks;
    float m_energyRegenRate = 1.0f;
    float m_staminaRegenRate = 1.0f;
    int m_energy;
    int m_stamina;
    std::chrono::steady_clock::time_point m_lastAttackTime;
    float m_globalCooldown = 0.0f; // Adjustable global cooldown timer

    std::vector<Attack> getAvailableAttacks() {
        std::vector<Attack> availableAttacks;
        for (const auto& attack : m_attacks) {
            if (attack.cooldown > m_globalCooldown) continue;
            if (m_energy >= attack.costEnergy && m_stamina >= attack.costStamina) availableAttacks.push_back(attack);
        }
        return availableAttacks;
    }

    Attack chooseAttack(const std::vector<Attack>& availableAttacks) {
        if (availableAttacks.size() == 1) return availableAttacks[0]; // No need to balance when only one attack is available

        float totalEffectiveness = 0.0f;
        for (const auto& attack : availableAttacks) totalEffectiveness += attack.effectiveness;

        float randomValue = RandomNumberGenerator::getRandomFloat(0.0f, totalEffectiveness);
        float cumulativeEffectiveness = 0.0f;
        for (const auto& attack : availableAttacks) {
            cumulativeEffectiveness += attack.effectiveness;
            if (cumulativeEffectiveness > randomValue) return attack;
        }
        // In case all attacks have zero effectiveness, return the first one as a default option
        return availableAttacks[0];
    }

    void performAttack(const Attack& attack) {
        m_energy -= attack.costEnergy;
        m_stamina -= attack.costStamina;
        m_globalCooldown = attack.cooldown;
        m_lastAttackTime = std::chrono::steady_clock::now();

        if (RandomNumberGenerator::getRandomFloat(0.0f, 1.0f) < attack.effectiveness * 0.5f) { // Critical hit condition
            m_globalCooldown = 0.0f;
        }

        LogManager::logAttack(attack.id, m_lastAttackTime);
    }
};
```

