#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <limits.h>

typedef struct Config {
    unsigned int max_exec_time; // Maximum execution time per truncation operation (in microseconds)
    size_t max_memory_usage; // Maximum memory usage (in bytes)
} Config;

char* truncate_path(const char *path, const char *config_file, unsigned int max_depth) {
    struct stat file_stat;
    struct stat link_stat;
    ssize_t path_len = strlen(path);
    char *truncated_path = malloc(path_len + 1); // Allocate memory for the truncated path
    memcpy(truncated_path, path, path_len + 1); // Copy the original path to the truncated path

    Config config;
    FILE *config_fp = fopen(config_file, "r");
    if (config_fp == NULL) {
        perror("Error opening configuration file");
        free(truncated_path);
        return NULL;
    }

    fscanf(config_fp, "%u %zu", &config.max_exec_time, &config.max_memory_usage);
    fclose(config_fp);

    unsigned int current_depth = 0;
    char *token = strtok(path, "/"); // Split the path by '/' to get its components
    while (token != NULL && current_depth < max_depth) {
        if (current_depth > 0) {
            // Check memory usage and execution time constraints
            clock_t start = clock();
            if (stat(truncated_path, &file_stat) == -1 || S_ISDIR(file_stat.st_mode)) {
                double elapsed_time = (double)(clock() - start) / CLOCKS_PER_SEC;
                if (elapsed_time > config.max_exec_time * 1e-6) {
                    fprintf(stderr, "Exceeded maximum execution time for truncation operation\n");
                    free(truncated_path);
                    return NULL;
                }
            }

            if (config.max_memory_usage > 0 && (size_t)sysconf(_SC_PAGE_SIZE) * (file_stat.st_size + strlen(token) + 1) > config.max_memory_usage) {
                fprintf(stderr, "Exceeded maximum memory usage\n");
                free(truncated_path);
                return NULL;
            }
        }

        if (token[0] == '.') { // Handle special cases like '.' and '..'
            if (strcmp(token, ".") == 0) {
                token = NULL; // Skip the current component
            } else if (strcmp(token, "..") == 0) {
                if (current_depth > 0) {
                    char *last_slash = strrchr(truncated_path, '/');
                    if (last_slash != NULL) {
                        last_slash[0] = '\0'; // Remove the last directory component from the truncated path
                        current_depth--;
                    }
                }
                token = NULL; // Skip the current component
            }
        }

        if (token != NULL) {
            current_depth++;
            char *next_token = strtok(NULL, "/"); // Get the next path component
            if (next_token == NULL && current_depth < max_depth) {
                token = NULL; // No more components to process
            }
        }

        if (token != NULL) {
            size_t new_len = strlen(truncated_path) + strlen(token) + 2; // Account for the '/' separator and null terminator
            truncated_path = realloc(truncated_path, new_len);
            strcat(truncated_path, "/");
            strcat(truncated_path, token);
        }
    }

    // Handle symbolic links efficiently and consistently across platforms
    if (S_ISLNK(file_stat.st_mode)) {
        ssize_t link_path_len = readlink(path, NULL, 0);
        char *link_path = malloc(link_path_len + 1);
        if (readlink(path, link_path, link_path_len + 1) != -1) {
            char abs_link_path[PATH_MAX];
            if (realpath(link_path, abs_link_path) != NULL) {
                free(link_path);
                struct stat link_stat;
                if (stat(abs_link_path, &link_stat) == -1 || S_ISDIR(link_stat.st_mode)) {
                    char *new_truncated_path = truncate_path(abs_link_path, config_file, max_depth);
                    free(truncated_path);
                    if (new_truncated_path != NULL) {
                        truncated_path = new_truncated_path;
                    } else {
                        free(abs_link_path);
                        return NULL;
                    }
                } else {
                    free(abs_link_path);
                }
            } else {
                free(link_path);
            }
        } else {
            perror("Error reading symbolic link");
            free(link_path);
            return NULL;
        }
    }

    return truncated_path;
}
```

