[' Here's a C++ implementation of the requested function using the Modern C++ library (https://en.cppreference.com/w/cpp/header/memory) for memory management and the TinyXML2 library (http://tinyxml2.sourceforge.net/) for parsing the external configuration file.

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <memory>
#include <sstream>
#include <fstream>
#include <tinyxml2/tinyxml2.h>

struct NodeData {
    std::string type;
    std::map<std::string, std::string> attributes;
    std::vector<std::string> metadata;
    std::string content;
};

class DOMTraversal {
public:
    explicit DOMTraversal(size_t maxSize, const std::function<int(const NodeData&)>& callback, bool includeWhitespace, const std::string& configFile)
        : m_maxSize(maxSize), m_callback(callback), m_includeWhitespace(includeWhitespace), m_buffer(""), m_currentNode(nullptr), m_config(parseConfigFile(configFile)) {}

    ~DOMTraversal() {
        clear();
    }

    std::string traverse(const tinyxml2::XMLNode* root) {
        m_currentNode = root;
        if (traverseInternal()) {
            return m_buffer.str();
        }
        clear();
        return nullptr;
    }

private:
    bool traverseInternal() {
        if (!m_currentNode || m_buffer.length() >= m_maxSize) {
            return false;
        }

        NodeData nodeData;
        nodeData.type = m_currentNode->Name();
        for (const auto& attribute : m_currentNode->Attributes()) {
            nodeData.attributes[attribute.Name()] = attribute.Value();
        }
        for (const auto& metadata : m_config[m_currentNode->Name()]) {
            nodeData.metadata.push_back(metadata);
        }
        std::stringstream contentStream;
        for (const auto* child : m_currentNode->Children()) {
            if (child->Type() == tinyxml2::XML_TEXT) {
                contentStream << child->GetText();
            } else if (traverseInternal()) {
                contentStream << *m_buffer;
                if (!m_includeWhitespace && !contentStream.str().empty()) {
                    contentStream << '/';
                }
                contentStream << *child->ToElement()->Name();
            }
        }
        nodeData.content = contentStream.str();

        int errorCode = m_callback(nodeData);
        if (errorCode != 0) {
            return false;
        }

        if (!m_includeWhitespace && !nodeData.content.empty()) {
            m_buffer << '/';
        }
        m_buffer << nodeData.type;
        for (const auto& attribute : nodeData.attributes) {
            m_buffer << ' ' << attribute.first << '="' << attribute.second << '"';
        }
        if (!nodeData.metadata.empty()) {
            m_buffer << " data-";
            for (size_t i = 0; i < nodeData.metadata.size(); ++i) {
                m_buffer << nodeData.metadata[i] << (i + 1 < nodeData.metadata.size() ? "-" : "");
            }
        }
        if (!nodeData.content.empty()) {
            m_buffer << '>';
            m_buffer << nodeData.content;
            m_buffer << "</";
            m_buffer << nodeData.type;
            m_buffer << '>';
        }

        for (const auto* child : m_currentNode->Children()) {
            if (child->Type() == tinyxml2::XML_TEXT) continue;
            traverseInternal();
        }
        return true;
    }

    void clear() {
        m_buffer.str("");
        m_buffer.clear();
        m_currentNode = nullptr;
    }

    std::map<std::string, std::vector<std::string>> parseConfigFile(const std::string& configFile) {
        std::map<std::string, std::vector<std::string>> result;
        std::ifstream file(configFile);
        if (file.is_open()) {
            std::string line;
            while (getline(file, line)) {
                auto pos = line.find('=');
                if (pos != std::string::npos) {
                    std::string key = line.substr(0, pos);
                    std::string value = line.substr(pos + 1);
                    result[key].push_back(value);
                }
            }
        }
        return result;
    }

    size_t m_maxSize;
    std::function<int(const NodeData&)> m_callback;
    bool m_includeWhitespace;
    std::stringstream m_buffer;
    const tinyxml2::XMLNode* m_currentNode;
    std::map<std::string, std::vector<std::string>> m_config;
};
```

This implementation uses a recursive approach to traverse the DOM tree and generates a string based on the provided configuration file. The function handles memory management using Modern C++ libraries and error handling by checking the return value of the user-defined callback function. It also includes caching strategies, such as storing metadata in a map, to improve performance for large HTML documents.']

