namespace RandomEngine {
    class MTGenerator {
        public:
            MTGenerator(unsigned long seed = std::random_device()());
            int generate(int min, int max);
            float generate(float min, float max);
            void setSeed(unsigned long seed);
            static unsigned long getSeed();
            ~MTGenerator();

        private:
            std::mt19937_64 engine;
            std::mutex mtx;
            unsigned long seed_;
    };

    // Configuration management and logging integration are not implemented here.
    // You can use a library like Boost.PropertyTree for configuration management,
    // and a logging framework like spdlog for logging.
}

RandomEngine::MTGenerator::MTGenerator(unsigned long seed) : engine(seed), seed_(seed) {}

int RandomEngine::MTGenerator::generate(int min, int max) {
    std::lock_guard<std::mutex> lock(mtx);
    return engine() % (max - min + 1) + min;
}

float RandomEngine::MTGenerator::generate(float min, float max) {
    std::lock_guard<std::mutex> lock(mtx);
    return static_cast<float>(engine()) * (max - min) + min;
}

void RandomEngine::MTGenerator::setSeed(unsigned long seed) {
    std::lock_guard<std::mutex> lock(mtx);
    engine.seed(seed);
    seed_ = seed;
}

unsigned long RandomEngine::MTGenerator::getSeed() {
    std::lock_guard<std::mutex> lock(mtx);
    return seed_;
}

RandomEngine::MTGenerator::~MTGenerator() {}
```

