        $this->api = $api;
        $this->validate = $validate;
        $this->rateLimiter = $rateLimiter;
    }

    public function handleRequest() {
        $subAction = $_REQUEST['sub_action'];
        $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
        $name = $_REQUEST['name'];
        $email = $_REQUEST['email'];
        $password = $_REQUEST['password'];

        if (!$this->rateLimiter->check()) {
            return json_encode(['message' => 'error', 'details' => 'Rate limit exceeded']);
        }

        switch ($subAction) {
            case 'create':
                if (!$this->validate->emailIsValid($email) || !$this->validate->passwordMeetsComplexityRequirements($password)) {
                    return json_encode(['message' => 'error', 'details' => 'Invalid email or password']);
                }

                if ($this->api->isEmailDomainReputationGood($email)) {
                    $this->Save(null, $name, $email, $password);
                    return json_encode(['message' => 'success']);
                } else {
                    return json_encode(['message' => 'error', 'details' => 'Email domain has a poor reputation']);
                }
                break;
            case 'update':
                if (!$this->validate->isValidId($id) || !$this->validate->isAuthorizedUser($id)) {
                    return json_encode(['message' => 'error', 'details' => 'Invalid user ID or unauthorized']);
                }

                if (in_array($_REQUEST['sub_action'], ['name', 'email', 'password'])) {
                    $this->Save($id, $_REQUEST['name'], $_REQUEST['email'], $_REQUEST['password']);
                    return json_encode(['message' => 'success']);
                } else {
                    return json_encode(['message' => 'error', 'details' => 'Invalid update field']);
                }
                break;
            case 'delete':
                if (!$this->validate->isValidId($id) || !$this->validate->isAuthorizedUser($id)) {
                    return json_encode(['message' => 'error', 'details' => 'Invalid user ID or unauthorized']);
                }

                $this->archiveAccount($id);
                return json_encode(['message' => 'success']);
                break;
            case 'fetch':
                if (!$this->validate->isValidId($id) || !$this->validate->isAuthorizedUser($id)) {
                    return json_encode(['message' => 'error', 'details' => 'Invalid user ID or unauthorized']);
                }

                $user = $this->Get($id);
                return json_encode(['message' => 'success', 'data' => $user]);
        }
    }
}
```

