        var builder = new SqlCommandBuilder(new SqlDataAdapter(commandText, connection));
        var command = builder.GetUpdateCommand();
        command.Parameters.AddRange(parameters.Select((p, i) => command.Parameters[i] = p).ToArray());
        await connection.OpenAsync();
        return await command.ExecuteReaderAsync();
