                return Content(newContent);
        }

        var sanitizedContent = await SanitizeContentAsync(newContent);

        using var httpResponse = await _httpClient.PostAsJsonAsync($"{_sanitizationServiceUrl}/sanitize", new { content = sanitizedContent });
        if (!httpResponse.IsSuccessStatusCode)
            throw new Exception("Failed to sanitize content");

        var sanitizedHtml = await httpResponse.Content.ReadAsStringAsync();

        using var command = new HttpClient() { BaseAddress = new Uri($"{_sanitizationServiceUrl}/update") }.PostAsync(new Uri($"/element/{pageSectionId}/{elementId}", UriKind.Relative), new StringContent(sanitizedHtml, Encoding.UTF8, "application/json"));
        if (!command.Result.IsSuccessStatusCode)
            throw new Exception("Failed to update element");

        _cache[$"{pageSectionId}:{elementId}"] = DateTime.UtcNow;
        LogUpdate(pageSectionId, elementId, newContent);

        return Content(sanitizedHtml);
    }

