    private void LogUpdate(string pageSectionId, string elementId, string newContent)
    {
        using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync();
        var command = new SqlCommand("INSERT INTO Updates (PageSectionId, ElementId, Content, Timestamp) VALUES (@PageSectionId, @ElementId, @Content, @Timestamp)", connection);
        command.Parameters.AddWithValue("@PageSectionId", pageSectionId);
        command.Parameters.AddWithValue("@ElementId", elementId);
        command.Parameters.AddWithValue("@Content", newContent);
        command.Parameters.AddWithValue("@Timestamp", DateTime.UtcNow);
        await command.ExecuteNonQueryAsync();
    }
