    new_node->next = cache[size];
    cache[size] = new_node;
    ++size;

    return new_node;
}

void md5_hash(const char* input, int format, uint8_t* output) {
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, input, strlen(input));
    MD5_Final(output, &ctx);

    if (format == HEX) {
        for (size_t i = 0; i < MD5_DIGEST_LENGTH; ++i) {
