```cpp
#include <iostream>
#include <vector>
#include <map>
#include <random>
#include <thread>
#include <mutex>
#include <future>
#include <json/json.h>

class Record {
public:
    int value;

    Record(int val) : value(val) {}
};

std::mutex mtx;
std::map<int, std::pair<size_t, size_t>> indexMap;
std::vector<long> offsets;
std::vector<int> keys;
std::vector<Record> records;

void fetchData(const Json::Value& config) {
    long offset = config["offset"].asLong();
    int keySize = config["key_size"].asInt();

    if (offset < 0 || keySize <= 0) {
        std::cerr << "Invalid configuration: offset and key size must be positive values." << std::endl;
        return;
    }

    auto fetchOffsets = [offset]() -> std::vector<long> {
        std::vector<long> result(offset, 0);
        return result;
    };

    auto fetchKeys = [keySize]() -> std::vector<int> {
        std::vector<int> result(keySize);
        std::generate(result.begin(), result.end(), []() -> int { return rand() % 100; });
        return result;
    };

    auto fetchRecords = [&]() -> std::vector<Record> {
        std::lock_guard<std::mutex> lock(mtx);
        std::vector<Record> result(keys.size());
        std::generate(result.begin(), result.end(), [&]() -> Record { return Record(rand() % 100); });
        return result;
    };

    auto fetchIndexMap = [&]() -> std::map<int, std::pair<size_t, size_t>> {
        std::lock_guard<std::mutex> lock(mtx);
        for (size_t i = 0; i < keys.size(); ++i) {
            auto it = indexMap.find(keys[i]);
            if (it == indexMap.end()) {
                indexMap[keys[i]] = std::make_pair(offsets.size(), i);
            } else {
                offsets[it->second.first] += keys.size() - it->second.second;
                indexMap[keys[i]] = std::make_pair(offsets[it->second.first], i);
            }
        }
        return indexMap;
    };

    auto fetchDataParallel = [&]() {
        std::vector<std::future<void>> futures;
        futures.push_back(std::async(fetchOffsets));
        futures.push_back(std::async(fetchKeys));
        futures.push_back(std::async(fetchRecords));
        futures.push_back(std::async(fetchIndexMap));

        for (auto& f : futures) {
            f.get();
        }
    };

    int retries = 3;
    while (retries > 0) {
        try {
            fetchDataParallel();
            break;
        } catch (const std::exception& e) {
            --retries;
            std::cerr << "Error fetching data: " << e.what() << ". Retrying..." << std::endl;
        }
    }

    if (retries == 0) {
        std::cerr << "Failed to fetch data after multiple retries." << std::endl;
    }
}

// Python JSON class and registry implementation are omitted due to the platform-specific nature of this code.
```

