        if (!indication) {
            fprintf(stderr, "Failed to allocate memory for indication %d\n", i);
            free(indications);
            return NULL;
        }
        indications[i] = indication;
    }

    return indications;
}

void registerFactory(int id, void* (*factory)(void)) {
    for (int i = 0; i < sizeof(factories) / sizeof(FactoryFunction); ++i) {
        if (!factories[i].id) {
