    $data = array(
        'client_id' => $clientId,
        'client_secret' => $clientSecret,
        'redirect_uri' => $redirectUri,
        'code' => $code,
        'grant_type' => 'authorization_code'
    );

    $options = array(
        'http' => array(
            'header'  => "Content-type: application/x-www-form-urlencoded\r\n",
            'method'  => 'POST',
            'content' => http_build_query($data)
        )
    );

    $context  = stream_context_create($options);
    $result = file_get_contents($accessTokenUrl, false, $context);
    if ($result === FALSE) { // Handle network issues
        return array('error' => 'Network error');
    }

    $response = json_decode($result, true);
    if (isset($response['error'])) { // Handle authentication failures
        return array('error' => $response['error']);
    }

    $_SESSION['access_token'] = $response['access_token'];

    // Retrieve user information using the access token
    $userInfoUrl = "https://www.googleapis.com/oauth2/v3/userinfo";
    $options = array(
        'http' => array(
            'header'  => "Authorization: Bearer " . $_SESSION['access_token'],
        )
    );

    $context  = stream_context_create($options);
    $result = file_get_contents($userInfoUrl, false, $context);
    if ($result === FALSE) { // Handle network issues
        return array('error' => 'Network error');
    }

    $userInfo = json_decode($result, true);
    if (isset($userInfo['error'])) { // Handle authentication failures
        return array('error' => $userInfo['error']);
    }

    return $userInfo;
}
