#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    long *offsets;
    int *keys;
    struct record *records;
    size_t num_offsets;
    size_t num_keys;
    size_t total_size;
} DataStruct;

struct record {
    int value;
};

DataStruct create_data_struct(size_t num_offsets, size_t num_keys) {
    const double max_allocation = 0.8;
    long total_memory = 1024 * 1024 * 8; // 8MB as an example of total memory
    size_t required_memory = sizeof(long) * num_offsets + sizeof(int) * num_keys + sizeof(struct record) * (num_offsets + num_keys);

    if (required_memory > max_allocation * total_memory) {
        fprintf(stderr, "Error: Required memory exceeds 80% of available memory.\n");
        return (DataStruct){NULL};
    }

    DataStruct data = {
        .num_offsets = num_offsets,
        .num_keys = num_keys,
        .total_size = num_offsets + num_keys,
    };

    if (!(data.offsets = malloc(sizeof(long) * num_offsets))) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets.\n");
        return (DataStruct){NULL};
    }

    if (!(data.keys = calloc(num_keys, sizeof(int)))) {
        fprintf(stderr, "Error: Failed to allocate memory for keys.\n");
        free(data.offsets);
        return (DataStruct){NULL};
    }

    if (num_keys < num_offsets / 2) {
        fprintf(stderr, "Error: Number of keys is less than half the number of offsets.\n");
        free(data.keys);
        free(data.offsets);
        return (DataStruct){NULL};
    }

    if (!(data.records = calloc((num_offsets + num_keys), sizeof(struct record)))) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        free(data.keys);
        free(data.offsets);
        return (DataStruct){NULL};
    }

    srand(time(NULL));

    // Initialize offsets with sequential long integers starting from 0
    for (size_t i = 0; i < num_offsets; ++i) {
        data.offsets[i] = i;
    }

    // Generate unique random integers within the [min_key, max_key] range for keys
    for (size_t i = 0; i < num_keys; ++i) {
        int key = rand() % (max_key - min_key + 1) + min_key;
        for (size_t j = 0; j < i; ++j) {
            if (data.keys[j] == key) {
                --i;
                break;
            }
        }
        data.keys[i] = key;
    }

    // Set values of records with random integers within the [min_value, max_value] range
    for (size_t i = 0; i < num_offsets + num_keys; ++i) {
        data.records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return data;
}
