constexpr size_t MAX_RECORDS = 1000;
constexpr size_t LONG_SIZE = sizeof(long);
constexpr size_t INT_SIZE = sizeof(int);
constexpr size_t RECORD_SIZE = sizeof(struct Record);

struct Record {
    int value;
};

class MemoryManager {
public:
    MemoryManager(size_t numRecords) : offsets_(numRecords), keys_(numRecords), records_(numRecords) {}

    void initialize() {
        if (!ensureAllocated()) {
            std::cerr << "Memory allocation failed.\n";
            return;
        }

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 100);

        for (size_t i = 0; i < records_.size(); ++i) {
            records_[i].value = dis(gen);
        }
    }

    void saveToFile(const std::string& filename) {
        std::ofstream file(filename, std::ios::binary | std::ios::trunc);
        if (file.is_open()) {
            file.write((char*)offsets_.data(), offsets_.size() * LONG_SIZE);
            file.write((char*)keys_.data(), keys_.size() * INT_SIZE);
            file.write((char*)records_.data(), records_.size() * RECORD_SIZE);
            file.close();
        } else {
            std::cerr << "Failed to open file for writing.\n";
        }
    }

    void checkIntegrity() const {
        size_t total = 0;
        for (size_t i = 0; i < records_.size(); ++i) {
            total += records_[i].value;
        }
        if (total != std::accumulate(keys_.begin(), keys_.end(), 0)) {
            std::cerr << "Data integrity check failed.\n";
        }
    }

private:
    bool ensureAllocated() {
        if (records_.size() >= MAX_RECORDS) return true;

        auto newRecords = std::vector<Record>(MAX_RECORDS);
        if (!records_.swap(newRecords)) return false;

        long* newOffsets = static_cast<long*>(aligned_alloc(LONG_SIZE, MAX_RECORDS * LONG_SIZE));
        int* newKeys = static_cast<int*>(aligned_alloc(INT_SIZE, MAX_RECORDS * INT_SIZE));
        if (!newOffsets || !newKeys) {
            free(newRecords.data());
            return false;
        }

        std::memcpy(newOffsets, offsets_.data(), offsets_.size() * LONG_SIZE);
        std::memcpy(newKeys, keys_.data(), keys_.size() * INT_SIZE);

        offsets_.resize(MAX_RECORDS);
        keys_.resize(MAX_RECORDS);
        records_.swap(newRecords);
        free(offsets_.data());
        free(keys_.data());
        offsets_.assign(newOffsets, newOffsets + MAX_RECORDS);
        keys_.assign(newKeys, newKeys + MAX_RECORDS);

        return true;
    }

    std::vector<long> offsets_;
    std::vector<int> keys_;
    std::vector<Record> records_;
};

std::atomic<bool> exit(false);
std::mutex mtx;

void worker(MemoryManager& manager, int id) {
    for (size_t i = 0; i < manager.records_.size(); ++i) {
        std::unique_lock<std::mutex> lock(mtx);
        while (!exit && i >= manager.keys_[id]) {
            lock.wait();
        }

        if (exit) break;

        auto record = manager.records_[i];
        std::cout << "Thread " << id << ": Record value: " << record.value << "\n";

        lock.unlock();
        ++manager.keys_[id];
    }
}

int main() {
    MemoryManager manager(10);
    manager.initialize();
    manager.checkIntegrity();

    std::vector<std::thread> workers;
    for (size_t i = 0; i < 4; ++i) {
        workers.emplace_back(worker, std::ref(manager), i);
    }

    std::this_thread::sleep_for(std::chrono::seconds(5));
    exit.store(true);

    for (auto& worker : workers) {
        worker.join();
    }

    manager.saveToFile("output.bin");
    return 0;
}
