    bool should_log;
} Condition;

int log_error_with_conditions(int file, uint32_t condition_mask, Condition* conditions, size_t num_conditions) {
    if (file < 0 || num_conditions == 0) return -1;

    char buffer[4096];
    snprintf(buffer, sizeof(buffer), "Error: ");

    for (size_t i = 0; i < num_conditions; ++i) {
        if ((condition_mask & (1 << conditions[i].code)) && conditions[i].should_log) {
            snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), " [%d] %s", conditions[i].code, conditions[i].description);
