typedef struct Point {
    int x, y;
} Point;

typedef struct Polygon {
    Point* vertices;
    size_t num_vertices;
} Polygon;

Polygon* create_polygon(size_t num_vertices) {
    Polygon* polygon = malloc(sizeof(Polygon));
    if (!polygon) {
        fprintf(stderr, "Memory allocation for Polygon failed.\n");
        return NULL;
    }

    polygon->vertices = calloc(num_vertices, sizeof(Point));
    if (!polygon->vertices) {
        fprintf(stderr, "Memory allocation for vertices failed.\n");
        free(polygon);
        return NULL;
    }

    polygon->num_vertices = num_vertices;
    return polygon;
}

void destroy_polygon(Polygon* polygon) {
    if (polygon) {
        free(polygon->vertices);
        free(polygon);
    }
}

double calculate_area(const Polygon* polygon) {
    double area = 0.0;
    size_t i, j;

    for (i = 0; i < polygon->num_vertices - 1; ++i) {
        area += (polygon->vertices[i].x * polygon->vertices[j++ % polygon->num_vertices].y) -
                (polygon->vertices[j].x * polygon->vertices[i].y);
    }

    return fabs(area / 2.0);
}

int main() {
    Polygon* polygon = create_polygon(5);

    if (polygon) {
        // Initialize vertices here...

        double area = calculate_area(polygon);
        printf("Polygon area: %.2f\n", area);

        destroy_polygon(polygon);
    }

    return 0;
}
```

