    if (!sanitizedContent) {
      logService('Sanitization Failure', `Script at index ${index} contains potentially dangerous code constructs`);
      failedScripts++;
      return;
    }

    const scriptTag = document.createElement('script');
    scriptTag.src = script.src;
    scriptTag.textContent = sanitizedContent;

    Object.keys(metadataAttributes).forEach((key) => {
      scriptTag.setAttribute(key, script[key]);
    });

    scriptContainer.appendChild(scriptTag);

    processedScripts++;

    handleScriptLoad(scriptTag, index);
  });

  if (failedScripts > 0) {
    logService('Total Validation Failures', failedScripts);
  }

  if (processedScripts < scriptArray.length) {
    logService('Total Sanitization Failures', failedScripts - processedScripts);
  }
}

function sanitizeScriptContent(content) {
  // Implement your sanitization logic here
  // For example, you can use libraries like DOMParser to remove potentially dangerous code constructs
  const parser = new DOMParser();
  const doc = parser.parseFromString(content, 'text/html');
  return doc.documentElement.outerHTML;
}

function handleScriptLoad(scriptTag, index) {
  scriptTag.onload = () => {
    processedScripts++;
    logService('Script Loaded', `Script at index ${index} has been loaded successfully`);
  };

  scriptTag.onerror = (event) => {
    failedScripts++;
    const errorMessage = event.target.error ? event.target.error.message : 'Unknown error';
    logService('Script Load Failure', `Script at index ${index} has failed to load: ${errorMessage}`);

    if (processedScripts < scriptArray.length) {
      // Retry logic with reasonable timeouts and failure thresholds
      setTimeout(() => handleScriptLoad(scriptTag, index), 1000);
    }
  };
}
```

This function assumes you have the following dependencies installed: `dompurge`, `axios`, and a logging service with a `logService` function. The configuration (whitelist, logService, metadataAttributes) is expected to be imported from a separate file.

