```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using NodeJS.Client;

namespace JavaScriptLoader.Services
{
    public class ScriptExecutorService
    {
        private readonly ILogger<ScriptExecutorService> _logger;
        private readonly Dictionary<string, string> _scripts = new Dictionary<string, string>();

        public ScriptExecutorService(ILogger<ScriptExecutorService> logger)
        {
            _logger = logger;
        }

        public void AddScript(string key, string scriptPath)
        {
            if (!File.Exists(scriptPath))
                throw new FileNotFoundException($"The script file '{scriptPath}' was not found.");

            _scripts[key] = scriptPath;
        }

        public async Task ExecuteScriptsAsync()
        {
            var context = await NodeJS.CreateContext();

            foreach (var script in _scripts)
            {
                try
                {
                    using var stream = File.OpenRead(script.Value);
                    var source = await stream.ReadToEndAsync();
                    await context.Run(source);
                }
                catch (Exception ex)
                {
                    _logger.LogError($"An error occurred while executing script '{script.Key}': {ex.Message}");
                }
            }
        }
    }
}
```

