[' Here's a high-level outline of how you might structure this module in Kotlin, using Android's Glide library for image loading and caching:

```kotlin
import android.content.Context
import androidx.annotation.VisibleForTesting
import com.bumptech.glide.Glide
import com.bumptech.glide.load.engine.DiskCacheStrategy
import com.bumptech.glide.request.RequestListener
import com.bumptech.glide.request.target.SimpleTarget
import com.bumptech.glide.request.transition.Transition
import java.io.File
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.Executors

class ThemeCache(private val context: Context) {

    private val themeCache = ConcurrentHashMap<String, Bitmap>()
    private val themeBitmapDiskCache = File(context.cacheDir, "theme_bitmaps")
    private val executor = Executors.newFixedThreadPool(4)

    @VisibleForTesting(otherwise = VisibleForTesting.PRIVATE)
    var maxCacheSize: Long = 10 * (1024 * 1024) // 10 MB by default

    fun getThemeBitmap(themeId: String, onSuccess: (Bitmap) -> Unit, onError: (Throwable) -> Unit) {
        if (themeCache.containsKey(themeId)) {
            onSuccess(themeCache[themeId]!!)
            return
        }

        executor.submit {
            val bitmap = Glide.with(context)
                .asBitmap()
                .load("theme/$themeId") // Assuming themes are stored in a "themes" directory
                .diskCacheStrategy(DiskCacheStrategy.AUTOMATIC)
                .listener(object : RequestListener<Bitmap> {
                    override fun onLoadFailed(e: GlideException?, model: Any?, target: SimpleTarget<Bitmap>?, isFirstResource: Boolean): Boolean {
                        onError(e ?: RuntimeException("Failed to load theme bitmap"))
                        return false
                    }

                    override fun onResourceReady(resource: Bitmap?, model: Any?, target: SimpleTarget<Bitmap>?, isFromMemoryCache: Boolean, isFirstResource: Boolean): Boolean {
                        if (!isFromMemoryCache) {
                            themeCache.putIfAbsent(themeId, resource)
                            evictOldestEntry()
                        }
                        onSuccess(resource ?: throw RuntimeException("Failed to load theme bitmap"))
                        return false
                    }
                })
                .submit()
                .get()
        }
    }

    private fun evictOldestEntry() {
        val oldestEntry = themeCache.entries.sortedBy { it.value.age() }.first()
        themeCache.remove(oldestEntry.key)
        oldestEntry.value.recycle()
        if (themeBitmapDiskCache.deleteRecursively()) {
            if (themeBitmapDiskCache.listFiles().isNullOrEmpty()) {
                themeBitmapDiskCache.delete()
            }
        }
        checkCacheSize()
    }

    private fun checkCacheSize() {
        if (themeCache.values.sumBy { it.byteCount } > maxCacheSize) {
            val entriesToEvict = themeCache.entries.sortedByDescending { it.value.age() }
                .take(Math.ceil((maxCacheSize - themeCache.values.sumBy { it.byteCount }) / maxCacheSize * entriesToEvict.size))
            for (entry in entriesToEvict) {
                entry.value.recycle()
                themeCache.remove(entry.key)
            }
        }
    }

    // Logging and additional functionality can be added here
}
```

