void init_network(int sequence, size_t num_components, size_t num_records) {
    delay_t *delays = malloc(num_components * sizeof(delay_t));
    if (!delays) {
        fprintf(stderr, "Failed to allocate memory for delays.\n");
        exit(1);
    }

    record_t *records = malloc(num_records * sizeof(record_t));
    if (!records) {
        free(delays);
        fprintf(stderr, "Failed to allocate memory for records.\n");
        exit(1);
    }

    // Initialize delays and populate records with random values
    for (size_t i = 0; i < num_components; ++i) {
        delay_t current = {i, rand() % 100};
        delays[i] = current;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        records[i].resource_usage = rand() % sequence + 1;
    }
}
```

