[' Here's an implementation using a lock-free skip list for the adjacency lists in each node, which allows for efficient traversal and insertion operations while minimizing contention. The custom graph structure is defined as follows:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Node {
    int data;
    pthread_t thread_id;
    struct SkipListNode* head; // Lock-free skip list head node
} Node;

typedef struct Edge {
    Node* dest;
    int weight;
} Edge;

typedef struct SkipListNode {
    struct SkipListNode* next[2];
    Edge edge;
} SkipListNode;

typedef struct Graph {
    Node** nodes;
    unsigned long long active_connections;
    unsigned int num_nodes, num_edges;
    pthread_mutex_t mutex;
} Graph;

Graph* create_graph(unsigned int* node_count, unsigned int edge_count) {
    if (*node_count <= 0 || edge_count < 1) return NULL;

    Graph* graph = (Graph*)malloc(sizeof(Graph));
    if (!graph) return NULL;

    graph->num_nodes = *node_count;
    graph->num_edges = edge_count;
    graph->active_connections = 0;
    pthread_mutex_init(&graph->mutex, NULL);

    graph->nodes = (Node**)calloc(graph->num_nodes, sizeof(Node*));
    if (!graph->nodes) {
        free(graph);
        return NULL;
    }

    for (unsigned int i = 0; i < graph->num_nodes; ++i) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            free(graph->nodes);
            free(graph);
            return NULL;
        }

        node->data = i;
        node->head = NULL;
        node->thread_id = 0;
        graph->nodes[i] = node;
    }

    return graph;
}
```

The lock-free skip list implementation is omitted for brevity, but you can find a detailed explanation and implementation in the paper "Lock-Free Data Structures: A Guide to Their Design, Implementation, and Use" by Michael Scott and Tim Harris.

To add, remove, or update edges, you can use functions like `add_edge`, `remove_edge`, and `update_edge` that take a graph pointer, source node index, destination node index, edge weight, and perform the operation atomically using lock-free data structure operations.']

