using System.Linq;
using System.Text.Json;
using System.Threading;

public class DynamicRangeGenerator
{
    private readonly float _min;
    private readonly float _max;
    private readonly int _type; // 0 for integer, 1 for float
    private readonly Dictionary<int, List<float>> _weights;

    public DynamicRangeGenerator(float min, float max, int type = 1, Dictionary<int, List<float>> weights = null)
    {
        if (min >= max)
            throw new ArgumentException("Minimum value must be less than maximum value.");

        _min = min;
        _max = max;
        _type = type;
        _weights = weights ?? new Dictionary<int, List<float>>();
    }

    public float NextFloat()
    {
        if (_type != 1)
            throw new InvalidOperationException("This instance is not configured for floating-point values.");

        return new Random().NextFloat(_min, _max);
    }

    public int NextInt()
    {
        if (_type != 0)
            throw new InvalidOperationException("This instance is not configured for integer values.");

        return (int)new Random().NextDouble(_min, _max);
    }

    public Vector2 NextVector2()
    {
        if (_type != 1)
            throw new InvalidOperationException("This instance is not configured for floating-point values.");

        return new Vector2(NextFloat(), NextFloat());
    }

    public Vector3 NextVector3()
    {
        if (_type != 1)
            throw new InvalidOperationException("This instance is not configured for floating-point values.");

        return new Vector3(NextFloat(), NextFloat(), NextFloat());
    }

    public float NextWeightedValue()
    {
        var total = _weights.Sum(w => w.Value.Sum(p => p));
        var rnd = new Random().NextDouble(0, total);

        foreach (var weight in _weights)
        {
            if (rnd < weight.Value.Sum(p => p))
            {
                rnd -= weight.Value.Sum(p => p);
                return weight.Key;
            }
        }

        throw new InvalidOperationException("Invalid probability distribution.");
    }

    public override string ToString() => $"DynamicRangeGenerator: min={_min}, max={_max}, type={_type}";

    public override int GetHashCode() => _min.GetHashCode() ^ _max.GetHashCode() ^ _type;

    public override bool Equals(object obj)
    {
        if (obj is not DynamicRangeGenerator other) return false;

        return other._min == _min && other._max == _max && other._type == _type;
    }

    public static DynamicRangeGenerator FromJson(string json) => JsonSerializer.Deserialize<DynamicRangeGenerator>(json);

    public string ToJson() => JsonSerializer.Serialize(this);
}
