public abstract class DynamicValueGenerator
{
    private DistributionType _distributionType;
    private Random _random;
    private double _minValue;
    private double _maxValue;
    private bool _isInclusive;

    protected DynamicValueGenerator(DistributionType distributionType, double minValue, double maxValue, bool isInclusive)
    {
        _distributionType = distributionType;
        _random = new Random();
        _minValue = minValue;
        _maxValue = maxValue;
        _isInclusive = isInclusive;
    }

    public DistributionType DistributionType => _distributionType;

    public void Reset(DistributionType distributionType, double minValue, double maxValue, bool isInclusive)
    {
        _distributionType = distributionType;
        _minValue = minValue;
        _maxValue = maxValue;
        _isInclusive = isInclusive;
    }

    public override string ToString()
    {
        var builder = new StringBuilder();
        builder.AppendLine($"Distribution Type: {_distributionType}");
        builder.AppendLine($"Min Value: {_minValue}, Max Value: {_maxValue}, Inclusive: {_isInclusive}");
        return builder.ToString();
    }

    public abstract T GenerateValue<T>();

    public List<T> GenerateValues<T>(int count)
    {
        var values = new List<T>();
        for (int i = 0; i < count; i++)
        {
            values.Add(GenerateValue<T>());
        }
        return values;
    }
}

public enum DistributionType
{
    Uniform,
    Normal
}

public abstract class ValueGenerator<T> : DynamicValueGenerator
{
    protected ValueGenerator(DistributionType distributionType, double minValue, double maxValue, bool isInclusive) : base(distributionType, minValue, maxValue, isInclusive) { }

    public override T GenerateValue()
    {
        throw new NotImplementedException();
    }
}

public class IntegerGenerator : ValueGenerator<int>
{
    protected IntegerGenerator(DistributionType distributionType, double minValue, double maxValue, bool isInclusive) : base(distributionType, minValue, maxValue, isInclusive) { }

    public override int GenerateValue()
    {
        if (_isInclusive)
        {
            return (int)(_random.NextDouble() * (_maxValue - _minValue + 1)) + (int)_minValue;
        }
        else
        {
            return (int)(_random.NextDouble() * (_maxValue - _minValue)) + (int)_minValue + 1;
        }
    }
}

public class FloatGenerator : ValueGenerator<float>
{
    protected FloatGenerator(DistributionType distributionType, double minValue, double maxValue, bool isInclusive) : base(distributionType, minValue, maxValue, isInclusive) { }

    public override float GenerateValue()
    {
        if (_isInclusive)
        {
            return (float)(_random.NextDouble() * (_maxValue - _minValue)) + _minValue;
        }
        else
        {
            return (float)(_random.NextDouble() * (_maxValue - _minValue + 1)) + _minValue;
        }
    }
}

public class CustomObjectGenerator : ValueGenerator<object>
{
    private readonly Func<Random, object> _generatorFunction;

    public CustomObjectGenerator(DistributionType distributionType, double minValue, double maxValue, bool isInclusive, Func<Random, object> generatorFunction) : base(distributionType, minValue, maxValue, isInclusive)
    {
        _generatorFunction = generatorFunction;
    }

    public override object GenerateValue()
    {
        return _generatorFunction(_random);
    }
}
```

