} CellData;

typedef struct {
    size_t capacity;
    size_t count;
    CellData* cells;
    pthread_mutex_t lock;
} DynamicArray;
```

2. Memory management:

```c
DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->capacity = initial_capacity;
    array->count = 0;
    array->cells = calloc(initial_capacity, sizeof(CellData));
    if (!array->cells) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void resize_dynamic_array(DynamicArray* array, size_t new_capacity) {
    if (new_capacity <= array->count) return;

    CellData* new_cells = realloc(array->cells, new_capacity * sizeof(CellData));
    if (!new_cells) return;

    array->capacity = new_capacity;
    array->cells = new_cells;
}
```

3. Thread-safe access:

```c
void lock_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);
}

void unlock_dynamic_array(DynamicArray* array) {
    pthread_mutex_unlock(&array->lock);
}
```

4. Cell access and validation:

```c
CellData* get_cell(DynamicArray* array, int cell_id) {
    lock_dynamic_array(array);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->cells[i].cell_id == cell_id) {
            CellData* cell = &array->cells[i];
            unlock_dynamic_array(array);
            return cell;
        }
    }

    unlock_dynamic_array(array);
    return NULL;
}

void add_cell(DynamicArray* array, int cell_id) {
    lock_dynamic_array(array);

    if (array->count == array->capacity) resize_dynamic_array(array, array->capacity * 2);

    CellData* new_cell = &array->cells[array->count];
    new_cell->cell_id = cell_id;
    pthread_mutex_init(&new_cell->lock, NULL);
    array->count++;

    unlock_dynamic_array(array);
}
```

