    pthread_mutex_lock(&cell->lock);

    // Perform atomic operations to update the MIB fields
    memcpy(&cell->mib, &new_mib, sizeof(LTE_PHY_MIB_T));

    pthread_mutex_unlock(&cell->lock);
}
```

