#include <sys/stat.h>
#include <sys/mman.h>
#include <semaphore.h>
#include <sys/types.h>
#include <sys/syscall.h>
#include <string.h>
#include <errno.h>

// Configuration file parsing and validation functions
void parse_config(const char *filename);

// Signal handler function
void signal_handler(int signum);

// Semaphore for managing concurrent processes
sem_t sem;

// Global variables from configuration
int max_processes;
pid_t background_pids[max_processes];
int num_running = 0;
char logfile[256];

// Function to execute command in the background
int exec_command(const char *cmd) {
    if (num_running >= max_processes) return 0;

    // Create a new process and fork
    pid_t pid = fork();
    if (pid < 0) return 0;
    else if (pid > 0) {
        // Parent process: update running count and log the start of the process
        num_running++;
        sem_post(&sem);
        log_event(cmd, "start");
        return 1;
    }

    // Child process: change the working directory to the log file's directory
    chdir(dirname(logfile));

    // Redirect stdout and stderr to the log file
    int fd = open(logfile, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (fd >= 0) {
        dup2(fd, STDOUT_FILENO);
        dup2(fd, STDERR_FILENO);
        close(fd);
    }

    // Execute the command in the background
    if (syscall(SYS_execve, cmd, argv, envp) < 0) return 0;

    // Child process: set up signal handlers and wait for termination signal
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    pause();

    return 1;
}

int main() {
    parse_config("config.ini");
    sem_init(&sem, 0, max_processes);

    // Main program loop
    while (1) {
        pid_t pid = sem_wait(&sem);
        if (pid > 0) continue;

        char cmd[256];
        printf("Enter command: ");
        fgets(cmd, sizeof(cmd), stdin);
        cmd[strcspn(cmd, "\n")] = '\0';

        int success = exec_command(cmd);
        if (success) log_event(cmd, "execute");
    }

    return 0;
}
