import java.util.Random;
import javax.xml.bind.DatatypeConverter;

public class FileManager {
    public static List<NFAPI_CRC_INDICATION_PDU_T> createNfapiPduList(File file) throws Exception {
        List<NFAPI_CRC_INDICATION_PDU_T> pduList = new ArrayList<>();
        Random random = new Random();

        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest;

        try (MessageDigitStream inputStream = new MessageDigitStream(file)) {
            while ((messageDigest = inputStream.read()) != null) {
                md.update(messageDigest);
            }
            messageDigest = md.digest();
            String hexString = DatatypeConverter.printHexBinary(messageDigest).toString();
            pduList.add(new NFAPI_CRC_INDICATION_PDU_T(RX_UE_INFORMATION_TAG.create(), new RNTI(random.nextInt()), CRC_INDICATION_REL8_TAG.create(hexString, random.nextBoolean())));
        }

        return pduList;
    }

    public static void cacheAndProcessFile(String remoteFilePath, String localCacheDirectory) throws Exception {
        File remoteFile = new File(remoteFilePath);
        if (!remoteFile.exists()) {
            System.out.println("Remote file does not exist.");
            return;
        }

        File localFile = new File(localCacheDirectory, remoteFile.getName());
        try {
            FileUtils.copyURLToFile(remoteFile.toURI().toURL(), localFile);
