[' Here's a Java program that addresses the given constraints:

```java
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class DirectoryCopier {
    private static final String PROPERTY_FILE = "config.properties";
    private static final String HASH_KEY = "hash";
    private static final String SCRIPT_ENGINE = "nashorn";

    public static void main(String[] args) {
        if (args.length < 3) {
            System.out.println("Usage: java DirectoryCopier source destination hash [help|version]");
            return;
        }

        String source = args[0];
        String destination = args[1];
        String storedHash = null;
        try (InputStream input = new FileInputStream(PROPERTY_FILE)) {
            Properties properties = new Properties();
            properties.load(input);
            storedHash = properties.getProperty(HASH_KEY);
        } catch (IOException e) {
            System.err.println("Error loading configuration file: " + e.getMessage());
            return;
        }

        String currentHash = calculateDirectoryHash(source);
        if (!storedHash.equals(currentHash)) {
            System.out.println("Stored hash does not match the current directory.");
            return;
        }

        copyDirectory(source, destination);
        System.out.println("Directory copied successfully.");
    }

    private static String calculateDirectoryHash(String path) {
        try {
            MessageDigest messageDigest = MessageDigest.getInstance("MD5");
            Files.walkFileTree(Paths.get(path), new HashCalculator(messageDigest));
            byte[] digest = messageDigest.digest();
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (Exception e) {
            System.err.println("Error calculating directory hash: " + e.getMessage());
        }
        return null;
    }

    private static void copyDirectory(String source, String destination) {
        ScriptEngine engine = new ScriptEngineManager().getEngineByName(SCRIPT_ENGINE);
        try {
            if (System.getProperty("os.name").contains("Windows")) {
                engine.eval("var cmd = new java.lang.ProcessBuilder(\"" + System.getProperty("cmd") + "\", \"/c\", \"xcopy\", \"" + source + "\", \"" + destination + "\", \"/H /Y\");\n" +
                        "cmd.start();");
            } else {
                engine.eval("var cmd = new java.lang.ProcessBuilder(\"cp\", \"-R\", \"" + source + "\", \"" + destination + "\");\n" +
                        "cmd.start();");
            }
        } catch (ScriptException e) {
            System.err.println("Error executing shell command: " + e.getMessage());
        }
    }

    private static class HashCalculator extends SimpleFileVisitor<Path> {
        private final MessageDigest messageDigest;

        public HashCalculator(MessageDigest messageDigest) {
            this.messageDigest = messageDigest;
        }

        @Override
        public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
            try (InputStream input = Files.newInputStream(file)) {
                messageDigest.update(input);
            }
            return FileVisitResult.CONTINUE;
        }
    }
}
```

This program uses a script engine to dynamically generate and execute shell commands based on the operating system. It fetches the hash value from an external configuration file, calculates the directory hash before copying, and handles errors gracefully. The program is also designed to be easily extendable and scalable.

To run this program, you'll need to have Java 8 or later installed, and the script engine "nashorn" should be available in your JRE. You can compile and run it using:

```sh
javac -cp /path/to/your/jre/lib/jsse.jar DirectoryCopier.java
