    {
        // Exponential backoff strategy example
        int delay = 100;
        while (true)
        {
            try
            {
                await ProcessTask(request);
                break;
            }
            catch (Exception e)
            {
                if (delay > 60_000) // Maximum delay of 1 minute
                    break;

                await Task.Delay(delay);
                delay *= 2;
            }
        }
    }

    private string GenerateKey(string pageSectionId, string elementId)
