```csharp
public class UpdateQueue
{
    private readonly BlockingCollection<Task> _tasks;
    private readonly TimeSpan _retryInterval = TimeSpan.FromMilliseconds(100);
    private int _retries = 0;

    public UpdateQueue()
    {
        _tasks = new BlockingCollection<Task>(new ConcurrentQueue<Task>());
    }

    public async Task EnqueueAsync(string htmlContent)
    {
        lock (_tasks)
        {
            if (_retries >= 10) return;

            var task = ProcessUpdateAsync(htmlContent);
            _tasks.Add(task);
            task.ContinueWith(t =>
            {
                if (t.IsFaulted && t.Exception != null)
                {
                    _retries++;
                    Task.Delay(_retryInterval * (_retries + 1)).ContinueWith(delayTask => EnqueueAsync(htmlContent));
                }
            });
        }
    }

    private async Task ProcessUpdateAsync(string htmlContent)
