#include <log4cxx/logger.h>

// External logging framework integration
log4cxx::LoggerPtr logger(log4cxx::Logger::getLogger("my_app"));

struct RX_UE_INFORMATION_TAG {
    uint32_t rrc_cgi;
    uint16_t rnti;
    enum class SRB_STATUS { IDLE, ACTIVE };
    SRB_STATUS srb1_rlc_status;
    // Optional elements like SRS_STATE or PUSCH_POWER_CONTROL can be added here
};

struct NFAPI_L2_RXUEINFO_PDU {
    std::vector<RX_UE_INFORMATION_TAG> rx_ues;
};

std::unique_ptr<NFAPI_L2_RXUEINFO_PDU[]> initialize_pdus(size_t num_pdus, size_t num_rx_ues_per_pdu, const RX_UE_INFORMATION_TAG* optional_elements) {
    std::unique_ptr<NFAPI_L2_RXUEINFO_PDU[]> pdus(new NFAPI_L2_RXUEINFO_PDU[num_pdus]);

    std::mutex mtx;
    std::vector<std::thread> threads;

    const size_t chunk_size = std::min(num_rx_ues_per_pdu, 100); // Adjust this value for optimal parallelism
    for (size_t pdu_idx = 0; pdu_idx < num_pdus; ++pdu_idx) {
        size_t start_idx = pdu_idx * chunk_size;
        size_t end_idx = std::min(num_rx_ues_per_pdu, start_idx + chunk_size);

        threads.emplace_back([this, start_idx, end_idx, &mtx]() mutable {
            for (size_t idx = start_idx; idx < end_idx; ++idx) {
                auto& pdu = pdus[pdu_idx];
                RX_UE_INFORMATION_TAG tag;
                // Initialize required elements here
                tag.rrc_cgi = idx + 1; // Example: unique CGI for each UE
                tag.rnti = idx + 2; // Example: unique RNTI for each UE
                tag.srb1_rlc_status = RX_UE_INFORMATION_TAG::SRB_STATUS::IDLE;

                // Initialize optional elements if provided
                if (optional_elements) {
                    auto* opt_elem = optional_elements + idx;
                    tag.srs_state = opt_elem->srs_state;
                    tag.pusch_power_control = opt_elem->pusch_power_control;
                }

                std::unique_lock<std::mutex> lock(mtx);
                pdu.rx_ues.emplace_back(tag);
                lock.unlock();
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return pdus;
}
```

This code creates a function `initialize_pdus()` that initializes an array of `NFAPI_L2_RXUEINFO_PDU` structures in parallel, using a mutex to ensure thread safety when adding elements to the vectors. The function takes in the number of structures and the number of `RX_UE_INFORMATION_TAG` elements per structure as parameters. It also supports optional elements like `SRS_STATE` or `PUSCH_POWER_CONTROL`.

The code uses a chunking approach for parallel processing, dividing the work into smaller chunks to minimize overhead and improve performance when dealing with large datasets. The external logging framework is integrated using log4cxx.

