struct MemoryStruct {
    char*  mbuffer;
    size_t  msize;
};

static size_t WriteCallback(void* contents, size_t size, size_t nmemb, void* userp)
{
    auto mem = static_cast<MemoryStruct*>(userp);
    mem->msize += size * nmemb;
    auto new_buffer = static_cast<char*>(realloc(mem->mbuffer, mem->msize + 1));
    if (new_buffer) {
        mem->mbuffer = new_buffer;
        memcpy(&(mem->mbuffer[mem->msize]), contents, size * nmemb);
        mem->mbuffer[mem->msize] = '\0';
    }
    return size * nmemb;
}

size_t checkUuidValidity(const std::string& sessionToken) {
    // Custom UUID validation logic here
