bool checkTimestampValidity(time_t expirationTime) {
    // Check if the expiration time is in the future
    auto currentTime = std::time(nullptr);
    return currentTime < expirationTime;
}

bool checkJsonValidity(const nlohmann::json& json) {
    // Custom JSON validation logic here
    // Ensure that the JSON object includes essential fields: user_id, session_token, expiration_time, and optionally, a refresh_token
    if (!json.contains("user_id") || !json.contains("session_token") || !json.contains("expiration_time")) {
