    if (!checkTimestampValidity(expirationTime)) {
        return false;
    }

    // If refresh_token is present, check its validity here
    if (hasRefreshToken) {
        // Custom refresh_token validation logic here
    }

    return true;
}

bool hasUniqueId(const std::string& id) {
    // Custom unique identifier validation logic here
    // For simplicity, this example assumes that the user_id is a unique string
    static std::unordered_set<std::string> ids;
    if (ids.find(id) != ids.end()) {
        return false;
    }
    ids.insert(id);
    return true;
}

nlohmann::json fetchSessionData() {
    CURL* curl = curl_easy_init();
    if (curl) {
        MemoryStruct chunk;
        curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/session"); // Replace with the actual API URL
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &chunk);

        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << '\n';
        } else {
            auto jsonData = nlohmann::json::parse(chunk.mbuffer);
            if (checkJsonValidity(jsonData)) {
                return jsonData;
            } else {
                std::cerr << "JSON data is invalid.\n";
            }
        }

        free(chunk.mbuffer);
        curl_easy_cleanup(curl);
    }

    return nlohmann::json(); // Return an empty JSON object if there's an error
}
```

This code fetches session data from a third-party API, parses the JSON response, and validates it. It also handles network errors and ensures efficient memory management. The function `fetchSessionData()` returns a valid JSON object containing user_id, session_token, expiration_time, and optionally refresh_token if they are present and valid.']

