using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class MessageProcessor
{
    private TripleDESCryptoServiceProvider _cryptoProvider;
    private byte[] _key;
    private byte[] _iv;
    private readonly ILoggingService _loggingService;

    public MessageProcessor(ILoggingService loggingService, byte[] key = null)
    {
        _loggingService = loggingService;
        if (key != null && key.Length >= 8)
            InitializeKey(key);
    }

    private void InitializeKey(byte[] key)
    {
        _key = new byte[24];
        Array.Copy(key, 0, _key, 0, 8); // First 8 bytes for the key
        _iv = new byte[8];                 // Remaining 8 bytes for IV
        _cryptoProvider = new TripleDESCryptoServiceProvider();
    }

    public async Task<string> EncryptMessage(string message)
    {
        if (string.IsNullOrEmpty(message)) throw new ArgumentException("Message cannot be empty.");

        var bytesToEncrypt = Encoding.UTF8.GetBytes(message);
        if (bytesToEncrypt.Length > int.MaxValue - _key.Length)
            throw new ArgumentOutOfRangeException("Message is too large.");

        using (var ms = new MemoryStream())
        {
            using (var cs = new CryptoStream(ms, _cryptoProvider.CreateEncryptor(_key, _iv), CryptoStreamMode.Write))
            {
                cs.Write(bytesToEncrypt, 0, bytesToEncrypt.Length);
                cs.FlushFinalBlock();
            }

            return Convert.ToBase64String(ms.ToArray());
        }
    }

    public async Task<string> DecryptMessage(string encryptedMessage)
    {
        if (string.IsNullOrEmpty(encryptedMessage)) throw new ArgumentException("Encrypted message cannot be empty.");

        var bytesToDecrypt = Convert.FromBase64String(encryptedMessage);
        using (var ms = new MemoryStream(bytesToDecrypt))
        {
            using (var cs = new CryptoStream(ms, _cryptoProvider.CreateDecryptor(_key, _iv), CryptoStreamMode.Read))
            {
                var decryptedBytes = new byte[ms.Length];
                await cs.ReadAsync(decryptedBytes, 0, decryptedBytes.Length);
                return Encoding.UTF8.GetString(decryptedBytes);
            }
        }
    }

    public void RotateKey(byte[] newKey)
    {
        if (newKey == null || newKey.Length != 24) throw new ArgumentException("Invalid key length.");
        InitializeKey(newKey);
    }

    public Statistics GetStatistics()
    {
        // Implement the logic to gather statistics on successful and failed decryptions, as well as total messages processed.
        // Return an instance of a `Statistics` class that encapsulates this information.
    }
}
```

