        if (iv == null || iv.Length <= 0) throw new ArgumentException("Initialization vector cannot be null or empty.");

        var decryptedBytes = _algorithms[algorithm](key, iv, decodedBytes);
        return Encoding.UTF8.GetString(decryptedBytes);
