            int checksumLength = buffer.getInt();
            int classIndex = buffer.getInt();
            byte[] classBytes = new byte[classIndex];
            for (int i = 0; i < classIndex; i++) {
                classBytes[i] = buffer.get();
            }
            Class<?> clazz = Class.forName(new String(classBytes));
            if (!KNOWN_CLASSES.contains(clazz)) {
                LOGGER.warning("Unknown class: " + clazz.getName());
            }
            Constructor<?> constructor = clazz.getDeclaredConstructor();
            constructor.setAccessible(true);
            Object object = constructor.newInstance();

            // Deserialize the object's properties using a custom schema
            // This is a placeholder and should be replaced with actual deserialization logic
            if (clazz == String.class) {
                int length = buffer.getInt();
                byte[] stringBytes = new byte[length];
