                    stringBytes[i] = buffer.get();
                }
                String str = new String(stringBytes);
                constructor.getDeclaredMethod("setValue", String.class).invoke(object, str);
            } else if (clazz == Integer.class) {
                int value = buffer.getInt();
                constructor.getDeclaredMethod("setValue", int.class).invoke(object, value);
            } else if (clazz == BigDecimal.class) {
                // Deserialize BigDecimal using a custom schema
                // ...
            }

            // Calculate the checksum and compare it with the embedded one
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] calculatedChecksum = md.digest(data);
            if (!Arrays.equals(calculatedChecksum, Arrays.copyOfRange(data, data.length - checksumLength, data.length))) {
                throw new RuntimeException("Checksum mismatch");
            }

            return (T) object;
        } catch (Exception e) {
            LOGGER.severe("Error during deserialization: " + e.getMessage());
            throw new RuntimeException(e);
        }
    }
}
