  appenders: {
    console: { type: 'console' },
    file: { type: 'file', filename: 'commands.log' }
  },
  categories: {
    default: { appenders: ['console', 'file'], level: 'info' }
  }
});

const logger = log4js.getLogger();

function executeCommands(commands, customPath) {
  let currentPath = process.env.PATH;
  commands.split(';').forEach((command) => {
    const commandWithPath = `PATH=${currentPath}:${customPath}; ${command}`;

    exec(commandWithPath, (error, stdout, stderr) => {
      if (error) {
        logger.error(`Command failed: ${command}`, error);
        console.error(`Command failed: ${command}\nError: ${error}`);
      } else {
        logger.info(`Executed command: ${command}`);
        console.log(stdout);
      }
    });
  });
}
```

