#include <atomic>
#include <cassert>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    bool CRCFLAG;
};

constexpr size_t MAX_STRUCTURES = 1024;
std::atomic<size_t> structuresCount{0};
std::vector<NFAPI_CRC_INDICATION_PDU_T> structureList;
std::mutex listMutex;

size_t generateStructure(NFAPI_CRC_INDICATION_PDU_T& structure) {
    std::lock_guard<std::mutex> lock(listMutex);

    if (structuresCount >= MAX_STRUCTURES) {
        return 1; // Error: Max structures reached
    }

    structure.RX_UE_INFORMATION_TAG = ++structuresCount;
    structure.RNTI = 0;
    std::generate(structure.CRC_INDICATION_REL8_TAG, structure.CRC_INDICATION_REL8_TAG + sizeof(structure.CRNTI),
                   []() -> uint8_t { return rand() & 0xFF; });
    structure.CRCFLAG = rand() % 2 == 0;

    size_t currentRNTI = structure.RNTI;
    size_t i = 1;
    for (; i < structureList.size(); ++i) {
        if (structureList[i].RNTI == currentRNTI && structureList[i].RX_UE_INFORMATION_TAG != structure.RX_UE_INFORMATION_TAG) {
            break;
        }
    }

    if (i < structureList.size()) {
        ++i;
        while (i < structureList.size() && structureList[i].RNTI == currentRNTI) {
            ++i;
        }
        structure.RNTI = i;
    } else {
        structureList.push_back(structure);
    }

    return 0; // Success
}
```

