[' Due to the complexity of the task, I will provide a high-level design and an outline for the C function implementation. For a complete solution, you would need to integrate this with your existing logging framework, health-check service, and other system components.

```c
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/socket.h>
#include <unistd.h>
#include <arpa/inet.h>

// Define maximum number of concurrent connections
#define MAX_CONNECTIONS 10000

// Connection structure with health status and logging interface
typedef struct {
    int socket;
    bool is_healthy;
    pthread_mutex_t lock;
} Connection;

// Logging function for connection events
void log_connection(Connection* conn, const char* event);

// Function to check the health of a connection using an external service
bool check_connection_health(Connection* conn);

// Function to handle a single client session in a separate thread
void* handle_client(void* arg);

// Connection pool management function
Connection* manage_connections() {
    Connection* connections = (Connection*)malloc(MAX_CONNECTIONS * sizeof(Connection));

    // Initialize all connections as unhealthy and lock them
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        connections[i].socket = -1;
        connections[i].is_healthy = false;
        pthread_mutex_init(&connections[i].lock, NULL);
    }

    // Maintain a free connection list for efficient connection allocation
    int free_indices[MAX_CONNECTIONS];
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        free_indices[i] = i;
    }

    return connections, free_indices;
}

// Function to get a healthy connection from the pool or create a new one if necessary
Connection* get_connection(Connection* connections, int* free_indices) {
    // Search for an available and healthy connection in the free list
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        int index = free_indices[i];
        if (connections[index].socket == -1 || !connections[index].is_healthy) continue;

        // Move the found connection to the head of the free list and return it
        for (int j = i + 1; j < MAX_CONNECTIONS; ++j) {
            free_indices[j - 1] = free_indices[j];
        }
        free_indices[MAX_CONNECTIONS - 1] = index;
        return &connections[index];
    }

    // If no healthy connection is available, create a new one and add it to the pool
    int new_socket = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    Connection* new_connection = &connections[free_indices[0]];
    new_connection->socket = new_socket;
    new_connection->is_healthy = check_connection_health(new_connection);

    // Move the newly created connection to the head of the free list
    for (int i = 1; i < MAX_CONNECTIONS; ++i) {
        free_indices[i - 1] = free_indices[i];
    }
    free_indices[MAX_CONNECTIONS - 1] = 0;

    return new_connection;
}

// Main function to manage the connection pool and handle incoming client requests
int main() {
    Connection* connections, *free_indices;
    connections = manage_connections();

    // Set up the server socket and bind it to a specific address and port
    int server_socket = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr));

    // Start listening for incoming client connections
    listen(server_socket, MAX_CONNECTIONS);

    while (true) {
        // Accept a new client connection and handle it in a separate thread
        Connection* conn = get_connection(connections, free_indices);
        socklen_t addr_len = sizeof(sockaddr_in);
        int client_socket = accept(server_socket, (struct sockaddr*)&conn->addr, &addr_len);
        pthread_t thread_id;
        pthread_create(&thread_id, NULL, handle_client, conn);
    }

    // Clean up resources when the program exits
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        Connection* conn = &connections[i];
        close(conn->socket);
        pthread_mutex_destroy(&conn->lock);
    }
    free(connections);

    return 0;
}
```

This code provides a basic structure for managing connections in a high-traffic web server environment. It includes functions to manage the connection pool, handle client sessions in separate threads, and check the health of connections using an external service. However, it does not include the logging function or the implementation of the `handle_client` function, which would require integrating with your existing logging framework and health-check service. Additionally, you may need to optimize the connection management algorithm for performance and scalability based on your specific system requirements.']

