typedef struct {
    char name[32];
    unsigned int rnti;
    unsigned int crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

struct service_node {
    const char *name;
    pthread_mutex_t lock;
    struct service_node *next;
    NFAPI_CRC_INDICATION_PDU_T data;
};

void log_info(const char *message) {
    // Implement your logging function here.
}

void create_service_node(struct service_node **head, const char *name) {
    struct service_node *new_node = (struct service_node *)malloc(sizeof(struct service_node));
    new_node->name = strdup(name);
    pthread_mutex_init(&new_node->lock, NULL);
    new_node->next = *head;
    *head = new_node;
}

NFAPI_CRC_INDICATION_PDU_T *get_service_data(struct service_node *node) {
    pthread_mutex_lock(&node->lock);
    NFAPI_CRC_INDICATION_PDU_T *data = &node->data;
    pthread_mutex_unlock(&node->lock);
    return data;
}

void parse_xml(const char *filename, struct service_node **head) {
    xmlDocPtr doc = xmlReadFile(filename, NULL, 0);
    if (!doc) {
        log_info("Error: Unable to read XML file.");
        return;
    }

    xmlNodeSetPtr nodeset = xmlDocGetRootElement(doc);
    for (xmlNode *node = nodeset->nodes; node; node = node->next) {
        if (xmlStrcmp(node->name, (const xmlChar *)"service")) continue;

        create_service_node(head, (const char *)xmlNodeGetContent(node));
    }

    xmlFreeDoc(doc);
}

void populate_data(struct service_node *head) {
    for (struct service_node *current = head; current; current = current->next) {
        NFAPI_CRC_INDICATION_PDU_T *data = get_service_data(current);
        data->rnti = rand();
        data->crc_flag = rand() % 2;
    }
}

void handle_error(const char *message) {
    log_info("Error: %s", message);
}
