        return NULL;
    }

    for (int i = 0; i < num_connections; ++i) {
        ue_states[i].UEID = -1; // Initialize UEID to an invalid value
        ue_states[i].RRC_STATE = -1; // Initialize RRC_STATE to an invalid value
        ue_states[i].SRB_CONFIG = -1; // Initialize SRB_CONFIG to an invalid value
        ue_states[i].num_SIBs = num_SIBs_per_connection;

        if (ue_states[i].num_SIBs > 0) {
            ue_states[i].SIB_array = (SIB*)calloc(ue_states[i].num_SIBs, sib_size);
            if (!ue_states[i].SIB_array) {
                perror("Memory allocation for SIBs failed");
                free(ue_states);
                return NULL;
            }
        } else {
            ue_states[i].SIB_array = NULL;
        }
    }

    return ue_states;
}

void resetUEStates(UEState* ue_states, int num_connections) {
    for (int i = 0; i < num_connections; ++i) {
