void parse_and_cache_services(const char *filename, GHashTable *table) {
    pthread_key_t key;
    int error = pthread_key_create(&key, NULL);
    if (error) {
        fprintf(stderr, "Failed to create thread-specific key: %s\n", strerror(error));
        return;
    }

    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; ++i) {
        error = pthread_create(&threads[i], NULL, parse_and_cache_service, filename);
        if (error) {
            fprintf(stderr, "Failed to create thread: %s\n", strerror(error));
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_key_delete(key);
}
```

