void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = malloc(size + alignment - 1);
    if (ptr != NULL) {
        memset((char*)ptr + alignment - 1, 0, alignment - 1);
        return (void*)(((uintptr_t)ptr + alignment - 1) & ~(alignment - 1));
    }
    return NULL;
}

MAC_CONTEXT* manageMACContextArray(unsigned int capacity, size_t SRB_size, size_t SRB_buffer_alignment, size_t buffer_size) {
    MAC_CONTEXT* context = (MAC_CONTEXT*)aligned_alloc(sizeof(MAC_CONTEXT), capacity * sizeof(MAC_SRB));
    if (!context) {
        perror("Failed to allocate memory for MAC_CONTEXT");
        return NULL;
    }

    context->capacity = capacity;
    context->size = 0;

    for (unsigned int i = 0; i < capacity; ++i) {
        context->srbArray[i].buffer = aligned_alloc(SRB_buffer_alignment, buffer_size);
        if (!context->srbArray[i].buffer) {
            perror("Failed to allocate aligned memory for SRB_BUFFER");
            free(context);
            return NULL;
        }
    }

    // Initialize SRB_CONFIG and set up other structures as needed...

