    if (!keys) {
        log_error("Failed to allocate memory for keys.");
        return NULL;
    }

    bool keys_used[max_key - min_key + 1] = {false};

    for (int i = 0; i < num_keys; ++i) {
        int key;
        do {
            key = rand() % (max_key - min_key + 1) + min_key;
        } while (keys_used[key]);

        keys_used[key] = true;
        keys[i] = key;
    }

    return keys;
}

Record* generate_records(int num_offsets, int num_keys) {
    Record *records = (Record *)allocate((size_t)((num_offsets + num_keys) * sizeof(Record)));
    if (!records) {
