        return NULL;
    }

    for (int i = 0; i < num_offsets; ++i) {
        records[i].value = i;
    }

    for (int i = num_offsets, *key_ptr = generate_unique_keys(num_keys, 1, INT_MAX); i < num_offsets + num_keys; ++i) {
