DynamicList* create_list(size_t initial_capacity) {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_list(DynamicList* list) {
    if (!list) return;

    for (size_t i = 0; i < list->capacity && list->size > 0; ++i) {
        free(list->data[i]);
        --list->size;
    }

    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    if (list->size == list->capacity) {
