        if (!list->data) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
    }

    pthread_mutex_lock(&list->lock);
    list->data[list->size] = element;
    ++list->size;
    pthread_mutex_unlock(&list->lock);
}

void remove_element(DynamicList* list, uint32_t rnti) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i]->rnti == rnti) {
            pthread_mutex_lock(&list->lock);
            free(list->data[i]);
            memmove(list->data + i, list->data + i + 1, (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            --list->size;
