// Global variables for error handling and thread synchronization
atomic_bool global_error = ATOMIC_VAR_INIT(false);
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char *message) {
    pthread_mutex_lock(&log_mutex);
    printf("[ERROR] %s\n", message);
    pthread_mutex_unlock(&log_mutex);
}

void create_pdu(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t index, uint16_t rnti_min, uint16_t rnti_max, size_t max_pdus) {
    if (index >= max_pdus || pdus == NULL) {
        return;
    }

    if (rnti_min > rnti_max || rnti_min <= 0 || rnti_max > 65535) {
        log_error("Invalid RNTI range.");
        global_error = true;
        return;
    }

    pdus[index].rx_ue_information_tag = index + 1;
    pdus[index].rnti = rand() % (rnti_max - rnti_min + 1) + rnti_min;
    pdus[index].crc_indication_rel8_tag = rand() % 256;
    pdus[index].crcflag = rand() % 2 == 0;
}

void* createCrcIndicationPduArray(void *arg) {
    size_t max_pdus = *(size_t*) arg;
    uint16_t rnti_min = 1000;
    uint16_t rnti_max = 2000;

    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*) malloc(max_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        log_error("Memory allocation failed.");
        global_error = true;
        return NULL;
    }

    for (size_t i = 0; i < max_pdus; ++i) {
        create_pdu(pdus, i, rnti_min, rnti_max, max_pdus);
    }

    // Simulate asynchronous execution using a shell command
    system("sleep 2 && echo 'PDUs created successfully.' > output.txt");

    return pdus;
}

NFAPI_CRC_INDICATION_PDU_T* createCrcIndicationPduArrayThreadSafe(size_t max_pdus, uint16_t rnti_min, uint16_t rnti_max) {
    pthread_t thread;
    void *result = NULL;

    if (pthread_create(&thread, NULL, createCrcIndicationPduArray, &max_pdus)) {
        log_error("Thread creation failed.");
        global_error = true;
        return NULL;
    }

    pthread_detach(thread);

    while (global_error) {
        // Wait for the thread to finish execution and handle any errors
