[' Here's a Java implementation using Apache Commons Compression, Jackson for serialization, and Slf4j for logging. This example demonstrates loading a state object from either ZIP or TAR files, handling exceptions, closing resources, validating checksums, supporting concurrent access, optimizing memory usage, providing detailed logs, and adapting to changes in file structure or format.

```java
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipArchiveInputStream;
import org.apache.commons.io.IOUtils;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

public class StateLoader {
    private static final Logger LOGGER = LoggerFactory.getLogger(StateLoader.class);
    private static final ObjectMapper MAPPER = new ObjectMapper();
    private static final ConcurrentHashMap<String, ReentrantLock> LOCKS = new ConcurrentHashMap<>();

    public <T> T loadState(Path file, Class<T> clazz) throws IOException {
        try (InputStream inputStream = Files.newInputStream(file)) {
            if (Files.isZipFile(file)) {
                return loadFromZip(inputStream, clazz);
            } else if (Files.isRegularFile(file) && file.toString().endsWith(".tar")) {
                return loadFromTar(inputStream, clazz);
            } else {
                throw new IllegalArgumentException("Unsupported file format: " + file.getFileName());
            }
        } catch (Exception e) {
            LOGGER.error("Error loading state from file {}", file, e);
            throw e;
        } finally {
            IOUtils.closeQuietly(file);
        }
    }

    private <T> T loadFromZip(InputStream inputStream, Class<T> clazz) throws IOException {
        try (ZipArchiveInputStream zipInputStream = new ZipArchiveInputStream(inputStream)) {
            ArchiveEntry entry = zipInputStream.getNextEntry();
            if (entry == null || !entry.getName().endsWith(clazz.getSimpleName() + ".checksum")) {
                throw new IOException("Invalid ZIP file structure");
            }

            ReentrantLock lock = LOCKS.computeIfAbsent(entry.getName(), k -> new ReentrantLock());
            lock.lock();

            try {
                byte[] stateData = IOUtils.toByteArray(zipInputStream);
                String checksum = IOUtils.toString(zipInputStream, entry.getCompressedSize());
                byte[] loadedChecksum = MAPPER.readValue(new ByteArrayInputStream(IOUtils.toByteArray(Files.newInputStream(Path.of(entry.getName().replaceAll("\\.checksum", ""))))), byte[].class);

                if (!Arrays.equals(loadedChecksum, MessageDigest.getInstance("SHA-256").digest(checksum.getBytes()))) {
                    LOGGER.error("Integrity check failed for file {}", entry.getName());
                }

                return MAPPER.readValue(new ByteArrayInputStream(stateData), clazz);
            } finally {
                lock.unlock();
            }
        } catch (Exception e) {
            LOGGER.error("Error loading state from ZIP file", e);
            throw e;
        }
    }

    private <T> T loadFromTar(InputStream inputStream, Class<T> clazz) throws IOException {
        try (TarArchiveInputStream tarInputStream = new TarArchiveInputStream(inputStream)) {
            ArchiveEntry entry = tarInputStream.getNextTarEntry();
            if (entry == null || !entry.getName().endsWith(clazz.getSimpleName() + ".checksum")) {
                throw new IOException("Invalid TAR file structure");
            }

            ReentrantLock lock = LOCKS.computeIfAbsent(entry.getName(), k -> new ReentrantLock());
            lock.lock();

            try {
                byte[] stateData = IOUtils.toByteArray(tarInputStream);
                String checksum = IOUtils.toString(tarInputStream, entry.getSize());
                byte[] loadedChecksum = MAPPER.readValue(new ByteArrayInputStream(IOUtils.toByteArray(Files.newInputStream(Path.of(entry.getName().replaceAll("\\.checksum", ""))))), byte[].class);

                if (!Arrays.equals(loadedChecksum, MessageDigest.getInstance("SHA-256").digest(checksum.getBytes()))) {
                    LOGGER.error("Integrity check failed for file {}", entry.getName());
                }

                return MAPPER.readValue(new ByteArrayInputStream(stateData), clazz);
            } finally {
                lock.unlock();
            }
        } catch (Exception e) {
            LOGGER.error("Error loading state from TAR file", e);
            throw e;
        }
    }
}
```

This implementation uses a concurrent hash map to manage locks for thread safety, and it logs detailed information about the loading process using Slf4j. The method can handle multiple concurrent requests efficiently without excessive resource consumption. It also adapts to changes in file structure or format by checking the file extension before processing.']

