        if (data[index].get() == nullptr) {
            throw std::runtime_error("Failed to initialize NFAPI_UL_CCCH_MSG_T");
        }
        data[index]->UE_ID = UE_ID;
        data[index]->SFI = SFI;
        data[index]->UL_CCCH_MESSAGE_TYPE = UL_CCCH_MESSAGE_TYPE;
        lock.unlock();
    }

    void addRRCMessage(size_t index, const RRC_MESSAGE& rrc_message) {
        unique_lock<mutex> lock(mtx);
        data[index]->rrc_messages.push_back(rrc_message);
        lock.unlock();
        cv.notify_one();
    }

    void externalDataUpdate(const NFAPI_UL_CCCH_MSG_T& new_data) {
        unique_lock<mutex> lock(mtx);
        auto it = std::find_if(data.begin(), data.end(), [new_data](const auto& element) {
