class CRCList {
public:
    CRCList(size_t maxSize) : _maxSize(maxSize), _list(_buffer.data()), _head(_list.begin()), _tail(_list.end()) {}

    void push(const NFAPI_CRC_INDICATION_PDU_T& data) {
        auto newNode = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(data);
        newNode->crcFlag = rand() % 2; // Randomly set CRC flag

        boost::lockfree::slist_node_base* current = _head.load();
        while (true) {
            boost::lockfree::slist_node_base* next = current->next().load();
            if (!next || next == _tail.load()) {
                newNode->next.store(current);
                if (_list.end() != _head.compare_exchange_weak(current, newNode.get())) {
                    continue;
                }
                break;
            }
            current = next;
        }

        validate();
    }

    void validate() {
        auto it = _head.load();
        size_t count = 0;
        while (it != _tail.load()) {
            if (!isReliable(it->crcIndication)) {
                it->~NFAPI_CRC_INDICATION_PDU_T();
                boost::lockfree::slist_node_base* next = it->next().load();
                _buffer.erase(it);
                delete it;
                it = next;
            } else {
                ++count;
                if (count >= _maxSize) {
                    it = _tail.load();
                    while (it != _head.load()) {
                        it->~NFAPI_CRC_INDICATION_PDU_T();
                        boost::lockfree::slist_node_base* next = it->next().load();
                        _buffer.erase(it);
                        delete it;
                        it = next;
                    }
                }
                it = it->next().load();
            }
        }
    }

private:
    std::function<bool(const CRC_INDICATION_REL8_TAG&)> _filterFunc;

    size_t _maxSize;
    boost::lockfree::slist<NFAPI_CRC_INDICATION_PDU_T> _list;
    boost::lockfree::slist_base_hook<NFAPI_CRC_INDICATION_PDU_T> _buffer;
    boost::lockfree::slist_node_base* _head;
    boost::lockfree::slist_node_base* _tail;

    void setFilterFunc(std::function<bool(const CRC_INDICATION_REL8_TAG&)> filter) {
        _filterFunc = std::move(filter);
    }

    bool isReliable(const CRC_INDICATION_REL8_TAG& crcIndication) {
        if (_filterFunc) {
            return _filterFunc(crcIndication);
        }
        // Default to always accepting indications for simplicity
        return true;
    }
};
