typedef struct FSM {
    int num_states;
    int** transitions;
} FSM;

typedef struct State {
    int state_id;
    struct State* next;
} State;

State* extend_state_list(int* states, int num_states, FSM* fsa, int last_state, int max_size) {
    if (last_state < 0 || last_state >= num_states) {
        return NULL;
    }

    State* current = &states[last_state];
    State* new_list = NULL;
    State* last_new = NULL;
    int new_size = max_size;
    State** new_array = malloc(sizeof(State*) * (max_size + 1));
    if (!new_array) {
        return NULL;
    }

    while (current && new_size > 0) {
        if (fsa->transitions[current->state_id] && current->state_id != fsa->num_states) {
            State* new_state = malloc(sizeof(State));
            if (!new_state) {
                free(new_array);
                return NULL;
            }

            new_state->state_id = fsa->transitions[current->state_id][0];
            new_state->next = NULL;

            if (!new_list) {
                new_list = new_state;
                last_new = new_list;
            } else {
                last_new->next = new_state;
                last_new = new_state;
            }

            --new_size;
        }

        current = current->next;
    }

    free(states);
    states = new_array;
    states[num_states] = NULL;

    if (new_list) {
        states[last_state] = new_list;
    }

    return new_list;
}
