#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <boost/random.hpp>
#include <boost/random/uniform_int.hpp>
#include <cstdlib>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
};

std::mutex mtx;
std::vector<NFAPI_CRC_INDICATION_PDU_T> ue_instances;
boost::random::uniform_int_distribution<> rnti_dist(0, 65535);

void createUEInstance(size_t index) {
    NFAPI_CRC_INDICATION_PDU_T ue;
    ue.RX_UE_INFORMATION_TAG = index + 1;
    ue.RNTI = rnti_dist(std::random_device{}());
    if (ue.RNTI > 65535) {
        std::cout << "Error: Invalid RNTI value: " << ue.RNTI << "\n";
        return;
    }
    ue.CRC_INDICATION_REL8_TAG = rand() % 2;

    // Lock the mutex to ensure thread safety during data insertion
    std::unique_lock<std::mutex> lock(mtx);
    ue_instances.push_back(ue);
}

void logUECreation(size_t index) {
    std::cout << "Creating UE instance: " << index + 1 << "\n";
}

void validateUEInstances() {
    // Lock the mutex to ensure thread safety during data validation
    std::unique_lock<std::mutex> lock(mtx);

    for (const auto& ue : ue_instances) {
        if (ue.RNTI > 65535) {
            std::cout << "Warning: Invalid RNTI value: " << ue.RNTI << "\n";
        }
    }
}

void populateUEs(size_t N) {
    std::vector<std::thread> threads;

    for (size_t i = 0; i < N; ++i) {
        threads.emplace_back(createUEInstance, i);
        threads.emplace_back(logUECreation, i);
    }

    // Wait for all threads to finish execution
    for (auto& thread : threads) {
        thread.join();
    }

    validateUEInstances();
}

int main() {
    size_t N = 10; // Number of User Equipment instances
    populateUEs(N);

    return 0;
}
```

