using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private readonly ConcurrentDictionary<Type, Tuple<double, double>> _ranges = new ConcurrentDictionary<Type, Tuple<double, double>>();
    private readonly object _lock = new object();
    private double _min;
    private double _max;

    public DynamicValueGenerator()
    {
        FetchRanges().Wait();
    }

    private async Task FetchRanges()
    {
        try
        {
            var ranges = await FetchFromExternalService();
            SetRanges(ranges);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error fetching ranges from external service: {ex.Message}");
            SetDefaultRanges();
        }
    }

    private void SetRanges(Dictionary<Type, Tuple<double, double>> ranges)
    {
        lock (_lock)
        {
            _ranges = new ConcurrentDictionary<Type, Tuple<double, double>>(ranges);
            SetDefaultsIfMissing(ranges.Keys);
        }
    }

    private void SetDefaultRanges()
    {
        lock (_lock)
        {
            _ranges[typeof(int)] = (0, 100);
            _ranges[typeof(float)] = (0f, 100f);
        }
    }

    private void SetDefaultsIfMissing(IEnumerable<Type> types)
    {
        var missingTypes = types.Except(_ranges.Keys).ToList();
        if (missingTypes.Any())
        {
            SetDefaultRanges();
        }
    }

    private Dictionary<Type, Tuple<double, double>> FetchFromExternalService()
    {
        // Implement the logic to fetch ranges from an external service here.
        throw new NotImplementedException();
    }

    public T GenerateValue<T>(bool inclusive) where T : struct
    {
        if (!_ranges.TryGetValue(typeof(T), out var range))
            throw new ArgumentException($"Unsupported type: {typeof(T).Name}");

        lock (_lock)
        {
            var min = inclusive ? range.Item1 : range.Item1 + 1;
            var max = inclusive ? range.Item2 : range.Item2 - 1;
            return GenerateValue<T>(min, max);
        }
    }

    private T GenerateValue<T>(double min, double max) where T : struct
    {
        Random random = new Random(ThreadStaticRandom.Current.GetHashCode());
        if (typeof(T) == typeof(int))
            return (T)(object)random.Next((int)min, (int)max);
        else if (typeof(T) == typeof(float))
            return (T)(object)random.NextDouble() * (float)(max - min) + (float)min;
        else
            throw new NotSupportedException($"Unsupported type: {typeof(T).Name}");
    }

    public override string ToString()
    {
        var ranges = _ranges.Select(x => $"{x.Key.Name}: ({x.Value.Item1}, {x.Value.Item2})").ToList();
        return string.Join(", ", ranges);
    }

    public void AdjustRange<T>(double newMin, double newMax) where T : struct
    {
        if (!_ranges.TryGetValue(typeof(T), out var range))
            throw new ArgumentException($"Unsupported type: {typeof(T).Name}");

        lock (_lock)
        {
            _ranges[typeof(T)] = (newMin, newMax);
        }
    }
}
```

