        {"help", no_argument, 0, 'h'},
        {"version", no_argument, 0, 'v'},
        {"output", required_argument, 0, 'o'},
        {0, 0, 0, 0}
    };

    Interface *interfaces = NULL;
    size_t interfaces_count = 0;

    while (1) {
        int option_index = 0;
        int c = getopt_long(argc, argv, "hvo:", long_options, &option_index);

