            break;

        switch (c) {
            case 'h':
                help = 1;
                break;
            case 'v':
                verbose++;
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                fprintf(stderr, "Invalid option\n");
                print_usage();
                exit(EXIT_FAILURE);
        }
    }

    if (optind < argc) {
        input_file = fopen(argv[optind], "r");
        if (!input_file) {
            perror("Error opening file");
            exit(EXIT_FAILURE);
        }
    }

    read_and_parse(input_file, &interfaces, &interfaces_count);

    if (help) {
