    new_node->next = NULL;
    return new_node;
}

void append(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void remove_by_index(List* list, int index) {
    if (index < 0 || index >= list->size) return;
    pthread_mutex_lock(&list->lock);
    Node** current = &list->head;
    for (int i = 0; i < index; ++i) {
        current = &((*current)->next);
    }
    if (*current != NULL) {
        Node* temp = *current;
        *current = (*current)->next;
        free(temp);
        list->size--;
    }
    pthread_mutex_unlock(&list->lock);
}

void update_by_index(List* list, int index, NFAPI_CRC_INDICATION_PDU_T data) {
    if (index < 0 || index >= list->size) return;
    pthread_mutex_lock(&list->lock);
    Node** current = &list->head;
    for (int i = 0; i < index; ++i) {
        current = &((*current)->next);
    }
    if (*current != NULL) {
        (*current)->data = data;
    }
    pthread_mutex_unlock(&list->lock);
}

