using System;
using UnityEngine;
using System.Collections.Generic;
using System.Threading;
using System.Net.Http;
using System.Text;
using Newtonsoft.Json;

public class OAuthRandomValueGenerator
{
    private readonly HttpClient _httpClient;
    private readonly string _baseUrl;
    private readonly string _clientId;
    private readonly string _clientSecret;
    private readonly TimeSpan _expirationThreshold;
    private readonly Dictionary<string, Session> _sessions = new Dictionary<string, Session>();
    private readonly object _lock = new object();

    public OAuthRandomValueGenerator(string baseUrl, string clientId, string clientSecret, TimeSpan expirationThreshold)
    {
        _baseUrl = baseUrl;
        _clientId = clientId;
        _clientSecret = clientSecret;
        _expirationThreshold = expirationThreshold;
        _httpClient = new HttpClient();
    }

    public void StartSession(string sessionId, int minValue, int maxValue)
    {
        lock (_lock)
        {
            if (!_sessions.ContainsKey(sessionId))
            {
                _sessions[sessionId] = new Session { MinValue = minValue, MaxValue = maxValue };
            }
        }
    }

    public float GenerateRandomFloat(string sessionId, bool inclusiveMin, bool inclusiveMax)
    {
        var session = GetSession(sessionId);
        return UnityEngine.Random.Range(inclusiveMin ? session.MinValue : session.MinValue + 1f, inclusiveMax ? session.MaxValue + 1f : session.MaxValue);
    }

    public int GenerateRandomInt(string sessionId, bool inclusiveMin, bool inclusiveMax)
    {
        var session = GetSession(sessionId);
        return (int)(inclusiveMin ? session.MinValue : session.MinValue + 1)
            .To(inclusiveMax ? session.MaxValue + 1 : session.MaxValue)
            .Random();
    }

    private Session GetSession(string sessionId)
    {
        lock (_lock)
        {
            if (_sessions.TryGetValue(sessionId, out var session))
                return session;
        }

        throw new KeyNotFoundException($"Session with ID '{sessionId}' not found.");
    }

    private async void RefreshAccessToken(string sessionId)
    {
        var session = GetSession(sessionId);

        if (session.IsAuthenticated && DateTime.UtcNow > session.AccessTokenExpirationTime + _expirationThreshold)
        {
            var authResponse = await _httpClient.PostAsync($"{_baseUrl}/oauth/token", new FormUrlEncodedContent(new[]
            {
                new KeyValuePair<string, string>("grant_type", "client_credentials"),
                new KeyValuePair<string, string>("client_id", _clientId),
                new KeyValuePair<string, string>("client_secret", _clientSecret)
            }));

            authResponse.EnsureSuccessStatusCode();
            var json = await authResponse.Content.ReadAsStringAsync();
            var tokenResponse = JsonConvert.DeserializeObject<TokenResponse>(json);

            lock (_lock)
            {
                session.AccessToken = tokenResponse.AccessToken;
                session.AccessTokenExpirationTime = DateTime.UtcNow + TimeSpan.FromSeconds(tokenResponse.ExpiresIn);
            }
        }
    }

    private struct TokenResponse
    {
        public string AccessToken { get; set; }
        public int ExpiresIn { get; set; }
    }

    private static int To(this int value, int to) => value <= to ? value : to + 1;

    private static Random Random() => new Random();

    public override string ToString()
    {
        var builder = new StringBuilder();
        lock (_lock)
        {
            foreach (var session in _sessions.Values)
            {
                builder.AppendLine($"Session ID: {session.SessionId}");
                builder.AppendLine($"Range: {session.MinValue} - {session.MaxValue}");
                builder.AppendLine($"Authentication Status: {(session.IsAuthenticated ? "Authenticated" : "Not Authenticated")}");
                builder.AppendLine();
            }
        }
        return builder.ToString();
    }
}
```']

