[' Here's a C# implementation of the `DynamicValueGenerator` class that meets the given requirements:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private float _min;
    private float _max;
    private readonly List<string> _rangeUpdates = new List<string>();

    public event Action<string> RangeUpdated;

    public string CurrentRange => $"{_min} - {_max}";

    public bool IsRangeValid => _min <= _max;

    public DynamicValueGenerator()
    {
        _min = float.MinValue;
        _max = float.MaxValue;
    }

    public void SetRange(float min, float max)
    {
        if (min > max)
        {
            var message = $"Invalid range: Min={min}, Max={max}";
            LogWarning(message);
            return;
        }

        lock (_rangeUpdates)
        {
            _rangeUpdates.Add($"{_min}-{_max} -> {min}-{max}");
        }

        _min = min;
        _max = max;

        RangeUpdated?.Invoke(CurrentRange);
    }

    public float GetRandomFloat()
    {
        if (!IsRangeValid) return float.NaN;

        var r = new Random();
        return _min + (r.NextFloat() * (_max - _min));
    }

    public int GetRandomInt()
    {
        if (!IsRangeValid) throw new ArgumentException("Invalid range");

        var r = new Random();
        return (int)(_min + (r.NextDouble() * (_max - _min)));
    }

    private void LogWarning(string message)
    {
        Console.WriteLine($"[WARNING] {message}");
    }
}
```

