const fs = require('fs');
const stream = require('stream');
const axios = require('axios');
const _ = require('lodash');
const { promisify } = require('util');

// Set concurrency limit and other configuration options here
const CONCURRENCY_LIMIT = 4;
const API_URL = 'https://your-api.com/validate';
const CREDENTIALS = process.env.API_KEY; // Securely store your API key as an environment variable

// Create a readable stream for each file in the specified directory
function createFileStream(filePath) {
  return new Promise((resolve, reject) => {
    const stream = fs.createReadStream(filePath);
    stream.on('error', reject);
    resolve(stream);
  });
}

// Process a single file and validate its content using the external API
async function processFile(fileStream, callback) {
  let data = [];

  // Create a writable stream to store processed data chunks
  const writeStream = new stream.Writable({
    write(chunk, encoding, callback) {
      data.push(JSON.parse(chunk));
      callback();
    },
    finalCallback() {
      callback(null, JSON.stringify(data));
    }
  });

  // Pipe the file stream to the writable stream for processing
  fileStream.pipe(writeStream);

  try {
    const processedData = await new Promise((resolve) => writeStream.on('finish', resolve));
    const validatedData = await validateData(processedData, CREDENTIALS);
    callback(null, validatedData);
  } catch (error) {
    callback(error);
  }
}

// Wrap axios call in a promise and handle exponential backoff for transient failures
async function validateData(data, apiKey) {
  let attempts = 0;
  const maxAttempts = 5;

  while (attempts < maxAttempts) {
    try {
      const response = await axios.post(API_URL, data, { headers: { Authorization: `Bearer ${apiKey}` } });
      return response.data;
    } catch (error) {
      attempts++;
      console.error(`Validation attempt ${attempts} failed with error: ${error.message}`);
      await new Promise((resolve) => setTimeout(resolve, Math.min(2 ** attempts * 1000, 32000))); // Exponential backoff
    }
  }

  throw new Error(`Validation failed after ${maxAttempts} attempts`);
}

// Read files asynchronously and process them in parallel with a concurrency limit
async function readAndProcessFiles(directoryPath) {
  const files = await promisify(fs.readdir)(directoryPath);
  const tasks = files.map((file) => () => processFile(createFileStream(`${directoryPath}/${file}`), (error, validatedData) => {
    if (error) {
      console.error(`Error processing file ${file}: ${error.message}`);
    } else {
      console.log(`Processed and validated file ${file}`);
    }
  }));

  await Promise.all(tasks.slice(0, CONCURRENCY_LIMIT).map((task) => task()));

  while (tasks.length > 0) {
    const newTasks = [];
    for (let i = 0; i < CONCURRENCY_LIMIT && tasks.length > 0; i++) {
      newTasks.push(tasks.shift());
    }
    await Promise.all(newTasks.map((task) => task()));
  }

  // Aggregate the validated data as a JSON object and return it
  const aggregatedResult = _.reduce([], (result, validatedData) => {
    result = _.merge(result, validatedData);
    return result;
  }, {});

  console.log(`Aggregated result:\n${JSON.stringify(aggregatedResult)}`);
}

// Call the function to process files in a specified directory
readAndProcessFiles('./my-directory');
