aes256gcm_context* aes256gcm_init(const char *passphrase, size_t passphrase_len) {
    const EVP_CIPHER *cipher = EVP_aes_256_gcm();
    aes256gcm_context *ctx = malloc(sizeof(aes256gcm_context));

    if (!ctx) {
        return NULL;
    }

