    int der_len = PBKDF2_HMAC((int)passphrase_len, passphrase, &salt, 100000, SHA256_DIGEST_LENGTH * 8, key, sizeof(key));
    if (der_len <= 0) {
        free(ctx);
        return NULL;
    }

    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE);

    EVP_CIPHER_CTX_init(ctx->ctx);
    EVP_EncryptInit_ex(ctx->ctx, cipher, NULL, key, iv);

    ctx->key = ctx->ctx->ksl;
    memcpy(ctx->iv, iv, AES_BLOCK_SIZE);

    return ctx;
}

void aes256gcm_encrypt(aes256gcm_context *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    EVP_EncryptUpdate(ctx->ctx, ciphertext, NULL, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx->ctx, &ciphertext[plaintext_len], NULL);
}

void aes256gcm_destroy(aes256gcm_context *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
