#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
    struct node *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *prev;
    struct node *next;
} node_t;

static node_t* head = NULL;
static node_t* tail = NULL;
static size_t list_size = 0;
static size_t max_list_size = MAX_LIST_SIZE;
static pthread_spinlock_t lock = PTHREAD_SPINLOCK_INITIALIZER;

void* malloc_custom(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL && list_size < max_list_size) {
        ptr = realloc(head, sizeof(node_t) * ++list_size);
        if (!ptr) {
            free(head);
            return NULL;
        }
        head->data = *(NFAPI_CRC_INDICATION_PDU_T*)calloc(1, size);
        head->next = tail;
        tail = head;
    }
    return ptr;
}

bool add_node(const NFAPI_CRC_INDICATION_PDU_T* node) {
    pthread_spin_lock(&lock);
    node_t* current = head;
    while (current != NULL && current->data.rnti != node->rnti) {
        current = current->next;
    }
    if (current == NULL || current->data.rnti != node->rnti) {
        node_t* new_node = (node_t*)malloc_custom(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_node != NULL) {
            memcpy(&new_node->data, node, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            new_node->next = current;
            if (current == NULL) {
                tail = new_node;
            }
            list_size++;
        }
    }
    pthread_spin_unlock(&lock);
    return list_size > 0;
}

void log_duplicates() {
    pthread_spin_lock(&lock);
    node_t* current = head;
    size_t duplicates = 0;
    while (current != NULL) {
        if (current->next != NULL && current->data.rnti == current->next->data.rnti) {
            duplicates++;
        }
        current = current->next;
    }
    pthread_spin_unlock(&lock);
    printf("Number of skipped entries due to duplicates: %zu\n", duplicates);
}
```

This implementation uses a custom allocator that minimizes memory fragmentation by expanding the list when necessary. It also employs a spinlock for synchronization, ensuring thread-safety and preventing data corruption during concurrent access. The function `add_node()` validates RNTI uniqueness and logs issues if duplicates are found.

To optimize performance, consider profiling the code under high load conditions to identify bottlenecks and propose optimizations. Additionally, you may want to explore lock-free data structures or other synchronization primitives for improved concurrency in more demanding scenarios.']

