    int total_structures_{0};
    int successful_requests_{0};
    int proxy_sessions_{0};
    int internal_errors_{0};
    std::vector<RequestID> requests_;
};

class SandeshClient {
public:
    SandeshClient(ba::io_context& io, Logger& logger, size_t concurrency_limit)
        : io_(io), logger_(logger), concurrency_limit_(concurrency_limit) {}

    void start(const std::vector<std::string>& endpoints) {
