```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>
#include <time.h>

typedef struct FileNode {
    struct FileNode *parent;
    int size;
    int mode;
    int type; // 0 for file, 1 for directory
    struct FileNode **children;
    pthread_mutex_t lock;
} FileNode;

FileNode* create_node(int parent_id, int type, int mode) {
    FileNode *new_node = mmap(NULL, sizeof(FileNode), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_node == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    new_node->parent = parent_id ? (FileNode*)parent_id : NULL;
    new_node->size = rand() % MAX_SIZE;
    new_node->mode = mode;
    new_node->type = type;
    new_node->children = NULL;
    pthread_mutex_init(&new_node->lock, NULL);

    return new_node;
}

void populate(FileNode *root, int depth) {
    if (depth > MAX_DEPTH || rand() % 100 > POPULATION_CHANCE)
        return;

    FileNode **children = realloc(root->children, sizeof(FileNode*) * (depth + 1));
    if (!children) {
        perror("realloc failed");
        exit(EXIT_FAILURE);
    }
    root->children = children;

    for (int i = 0; i < depth; ++i) {
        root->children[i] = create_node(root, rand() % 2, rand() % 2);
    }
}

void set_modes(FileNode *node) {
    if (!node)
        return;

    pthread_mutex_lock(&node->lock);

    node->mode = node->type ? 1 : 0;
    for (int i = 0; node->children[i]; ++i) {
        set_modes(node->children[i]);
    }

    pthread_mutex_unlock(&node->lock);
}

int total_nodes = 0;

void count_nodes(FileNode *node) {
    if (!node)
        return;

    pthread_mutex_lock(&node->lock);

    total_nodes++;
    for (int i = 0; node->children[i]; ++i) {
        count_nodes(node->children[i]);
    }

    pthread_mutex_unlock(&node->lock);
}

void log_anomalies(FileNode *root) {
    if (!root || !root->parent)
        printf("Missing parent node for root\n");

    pthread_mutex_lock(&root->lock);

    if (root->parent && root->parent->children[root - root->parent] != root)
        printf("Inconsistent data: Parent's child list does not contain this node\n");

    for (int i = 0; root->children[i]; ++i) {
        log_anomalies(root->children[i]);
    }

    pthread_mutex_unlock(&root->lock);
}
```

