std::mutex mtx;

class LTEManager {
public:
    LTEManager(size_t numUEs) : ueContexts_(numUEs), pagingMessages_(numUEs) {
        for (size_t i = 0; i < numUEs; ++i) {
            ueContexts_[i].setId(i);
            ueContexts_[i].setCellIdentity(rand() % 500 + 1); // Random cell identity within valid range
            // Initialize other UE context parameters as needed
        }

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(1, 60); // Paging period between 1 and 60 seconds

        for (auto& pagingMessage : pagingMessages_) {
            pagingMessage.setPagingPeriod(dis(gen));
            pagingMessage.setPagingIdentity(rand()); // Random paging identity
        }
    }

    void log(const std::string& message) {
        std::lock_guard<std::mutex> lock(mtx);
        std::cout << "[" << std::this_thread::get_id() << "] " << message << std::endl;
    }

    void resize(size_t newSize) {
        if (newSize <= ueContexts_.size()) return; // No need to resize if the size is already smaller or equal to the requested size

        auto oldUEContexts = std::move(ueContexts_);
        auto oldPagingMessages = std::move(pagingMessages_);

        ueContexts_.resize(newSize);
        pagingMessages_.resize(newSize);

        for (size_t i = oldUEContexts.size(); i < newSize; ++i) {
            ueContexts_[i].setId(i);
            // Initialize other UE context parameters as needed
        }

        std::copy(oldUEContexts.begin(), oldUEContexts.end(), ueContexts_.begin() + oldUEContexts.size());
        std::copy(oldPagingMessages.begin(), oldPagingMessages.end(), pagingMessages_.begin() + oldPagingMessages.size());

        log("Resized to " + std::to_string(newSize));
    }

private:
    std::vector<UEContext> ueContexts_;
    std::vector<PagingMessageT> pagingMessages_;
};
