struct Packet {
    uint32_t sourceIP;
    uint32_t destinationIP;
    uint16_t protocolType;
    std::size_t payloadLength;
    std::uint64_t timestamp;
};

class PacketArray {
private:
    std::vector<Packet> packets_;
    std::mutex mutex_;
    std::size_t capacity_;

public:
    PacketArray(std::size_t initialCapacity) : capacity_(initialCapacity) {
        packets_.reserve(capacity_);
    }

    void addPacket(const Packet& packet) {
        std::unique_lock<std::mutex> lock(mutex_);
        packets_.emplace_back(packet);
    }

    void updatePacket(std::size_t index, const Packet& newPacket) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (index >= packets_.size()) {
            throw std::out_of_range("Index out of range");
        }
        packets_[index] = newPacket;
    }

    Packet getPacket(std::size_t index) const {
        std::unique_lock<std::mutex> lock(mutex_);
        if (index >= packets_.size()) {
            throw std::out_of_range("Index out of range");
        }
        return packets_[index];
    }

    void resizeIfNeeded(std::size_t newCapacity) {
        if (newCapacity > capacity_) {
            capacity_ = newCapacity;
            packets_.resize(capacity_);
        }
    }
};
