#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mman.h>

typedef struct {
    NFAPI_L2_RX_PDU_T pdu;
    uint32_t ue_id;
    uint64_t retransmission_counter;
} RRC_PDU_MANAGER_ENTRY_T;

typedef struct {
    size_t capacity;
    size_t count;
    RRC_PDU_MANAGER_ENTRY_T* entries;
    pthread_mutex_t lock;
} RRC_PDU_MANAGER_T;

RRC_PDU_MANAGER_T* rrc_pdu_manager_create(size_t capacity) {
    if (capacity > 50000) {
        fprintf(stderr, "Initial capacity should not exceed 50,000\n");
        exit(EXIT_FAILURE);
    }

    RRC_PDU_MANAGER_T* manager = mmap(NULL, sizeof(RRC_PDU_MANAGER_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (manager == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = capacity;
    manager->count = 0;
    manager->entries = calloc(capacity, sizeof(RRC_PDU_MANAGER_ENTRY_T));
    if (!manager->entries) {
        perror("calloc failed");
        exit(EXIT_FAILURE);
    }

    return manager;
}

void rrc_pdu_manager_destroy(RRC_PDU_MANAGER_T* manager) {
    if (munmap(manager, sizeof(RRC_PDU_MANAGER_T)) == -1) {
        perror("munmap failed");
    }
}

bool rrc_pdu_manager_add_pdu(RRC_PDU_MANAGER_T* manager, const NFAPI_L2_RX_PDU_T* pdu, uint32_t ue_id) {
    if (manager->count >= manager->capacity) {
        RRC_PDU_MANAGER_ENTRY_T* new_entries = realloc(manager->entries, sizeof(RRC_PDU_MANAGER_ENTRY_T) * (manager->capacity * 2));
        if (!new_entries) {
            perror("realloc failed");
            return false;
        }
        manager->capacity *= 2;
        manager->entries = new_entries;
    }

    pthread_mutex_lock(&manager->lock);
    RRC_PDU_MANAGER_ENTRY_T* entry = &manager->entries[manager->count];
    entry->pdu = *pdu;
    entry->ue_id = ue_id;
    entry->retransmission_counter = 0;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);

    return true;
}

void rrc_pdu_manager_increment_retransmission(RRC_PDU_MANAGER_T* manager, uint32_t ue_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i].ue_id == ue_id) {
            manager->entries[i].retransmission_counter++;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void rrc_pdu_manager_log(RRC_PDU_MANAGER_T* manager) {
    printf("Manager state:\n");
    for (size_t i = 0; i < manager->count; ++i) {
        const RRC_PDU_MANAGER_ENTRY_T* entry = &manager->entries[i];
        printf("UE ID: %u, PDU: %p, Retransmissions: %llu\n", entry->ue_id, &entry->pdu, entry->retransmission_counter);
    }
}
