    dynamicArray[arraySize].subnetMask = strcpy(malloc(strlen(subnetMask) + 1), subnetMask);
    dynamicArray[arraySize].gatewayAddress = strcpy(malloc(strlen(gatewayAddress) + 1), gatewayAddress);
    pthread_mutex_init(&dynamicArray[arraySize].lock, NULL);
