void* createNode(NFAPI_CRC_INDICATION_PDU_T* parent, int index) {
    NFAPI_CRC_INDICATION_PDU_T* node = new NFAPI_CRC_INDICATION_PDU_T();
    if (!node) {
        std::cerr << "Memory allocation failure" << std::endl;
        return nullptr;
    }

    node->parent = parent;
    node->size = rand() % (TOTAL_SIZE_LIMIT / MAX_NODES);
    node->mode = (node->size > 0) ? 1 : 0;

    if (node->mode == 1 && parent) {
        mtx.lock();
        parent->children.push_back(node);
        mtx.unlock();
    }

    mtx.lock();
    nodes[index] = node;
    mtx.unlock();

    totalNodes++;

    if (node->mode == 1) {
        rootChildren.push_back(node);
    }

    if (node->size > 0 && node->mode == 0) {
        anomalies.push_back("File with size greater than zero and mode set to 0");
    }

    if (!node->parent && node->mode != 1) {
        anomalies.push_back("Root node is not a directory");
    }

    for (int i = 0; i < node->size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* child = createNode(node, totalNodes + i);
        if (!child) return nullptr;
    }

    return node;
}

void populateFileSystem() {
    mtx.lock();
    NFAPI_CRC_INDICATION_PDU_T* root = new NFAPI_CRC_INDICATION_PDU_T();
    if (!root) {
        std::cerr << "Memory allocation failure" << std::endl;
        mtx.unlock();
        return;
    }

    root->mode = 1;
    rootChildren[0] = root;
    mtx.unlock();

    for (int i = 0; i < MAX_NODES; ++i) {
        pthread_t thread;
        if (pthread_create(&thread, nullptr, createNode, rootChildren[0])) {
            std::cerr << "Thread creation failure" << std::endl;
        }
    }

    for (int i = 0; i < MAX_NODES; ++i) {
        pthread_join(thread, nullptr);
    }
}

void reportAnomalies() {
