```cpp
#include <vector>
#include <mutex>
#include <memory>

struct RRC_MESSAGE { /* Define your RRC_MESSAGE structure here */ };

struct NFAPI_UL_CCCH_MSG_T {
    uint32_t UE_ID;
    uint8_t SFI;
    uint8_t UL_CCCH_MESSAGE_TYPE;
    std::vector<RRC_MESSAGE> rrc_messages;
    std::mutex mutex;
};

class NFAPI_UL_CCCH_MSG_POOL {
private:
    std::vector<std::unique_ptr<NFAPI_UL_CCCH_MSG_T>> messages;
    std::mutex pool_mutex;
    size_t next_id = 0;

public:
    NFAPI_UL_CCCH_MSG_POOL(size_t initial_capacity) {
        messages.reserve(initial_capacity);
    }

    std::unique_ptr<NFAPI_UL_CCCH_MSG_T> acquire() {
        std::lock_guard<std::mutex> lock(pool_mutex);
        if (messages.empty()) {
            messages.emplace_back(new NFAPI_UL_CCCH_MSG_T());
            messages.back()->UE_ID = next_id++;
        }
        auto msg = std::move(messages.back());
        messages.pop_back();
        return msg;
    }

    void release(std::unique_ptr<NFAPI_UL_CCCH_MSG_T> msg) {
        std::lock_guard<std::mutex> lock(pool_mutex);
        msg->rrc_messages.clear(); // Clear messages to prevent leaks
        messages.push_back(std::move(msg));
    }

    void cleanup() {
        std::lock_guard<std::mutex> lock(pool_mutex);
        for (auto& msg : messages) {
            if (msg->rrc_messages.empty()) { // Only free messages with no RRC messages
                delete msg.release();
            }
        }
        messages.clear();
    }
};
```

This code creates a pool of `NFAPI_UL_CCCH_MSG_T` structures, each with its own mutex for thread safety during concurrent access. The `acquire()` function retrieves an unused structure from the pool and initializes it with a unique UE_ID. The `release()` function returns a structure back to the pool, clearing its RRC messages to prevent leaks. The `cleanup()` function periodically frees structures that are no longer in use.

