class DynamicList {
public:
    DynamicList(size_t maxSize) : m_list(), m_mutex(), m_maxSize(maxSize), m_garbageCollectionTimer(ioService) {
        m_garbageCollectionTimer.expires_from_now(boost::posix_time::seconds(1)); // adjust time as needed
        m_garbageCollectionTimer.async_wait([this](const boost::system::error_code& ec) {
            if (!ec) {
                clearOldEntries();
                m_garbageCollectionTimer.expires_from_now(boost::posix_time::seconds(1));
                m_garbageCollectionTimer.async_wait(std::bind(&DynamicList::garbageCollectionHandler, this, std::placeholders::_1));
            }
        });
    }

    void addEntry(const NFAPI_CRC_INDICATION_PDU& entry) {
        std::lock_guard<std::mutex> lock(m_mutex);
        if (m_list.size() >= m_maxSize) {
            clearOldEntries();
        }
        m_list.emplace_back(entry);
    }

private:
    void clearOldEntries() {
        std::list<NFAPI_CRC_INDICATION_PDU>::iterator it = m_list.begin();
        while (it != m_list.end() && m_list.size() > m_maxSize) {
            it = m_list.erase(it);
        }
    }

    void garbageCollectionHandler(const boost::system::error_code& ec) {
        if (!ec) {
            clearOldEntries();
            m_garbageCollectionTimer.expires_from_now(boost::posix_time::seconds(1));
            m_garbageCollectionTimer.async_wait(std::bind(&DynamicList::garbageCollectionHandler, this, std::placeholders::_1));
        }
    }

    std::list<NFAPI_CRC_INDICATION_PDU> m_list;
    std::mutex m_mutex;
    const size_t m_maxSize;
    boost::asio::io_service ioService;
    boost::asio::deadline_timer m_garbageCollectionTimer;
};
```

