void init_themes(uint32_t default_theme) {
    themes = malloc(sizeof(THEME_T));
    if (!themes) {
        // Handle allocation failure
        return;
    }

    themes[0].theme_id = default_theme;
    themes[0].bitmap_data = NULL;
}

void add_theme(uint32_t theme_id, const char* png_path) {
    FILE* file = fopen(png_path, "rb");
    if (!file) {
        // Handle file open failure
        return;
    }

    size_t file_size = 0;
    fseek(file, 0, SEEK_END);
    file_size = ftell(file);
    rewind(file);

    void* bitmap_data = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fileno(file), 0);
    if (bitmap_data == MAP_FAILED) {
        // Handle mapping failure
        fclose(file);
        return;
    }

    THEME_T* new_theme = malloc(sizeof(THEME_T));
    if (!new_theme) {
        // Handle allocation failure
        munmap(bitmap_data, file_size);
        fclose(file);
        return;
    }

    new_theme->theme_id = theme_id;
    new_theme->bitmap_data = bitmap_data;

    pthread_mutex_lock(&theme_lock);
    if (theme_count < MAX_THEMES) {
        themes[theme_count++] = new_theme;
    } else {
        // Handle memory exhaustion
        free(new_theme);
        munmap(bitmap_data, file_size);
        fclose(file);
    }
    pthread_mutex_unlock(&theme_lock);

    fclose(file);
}
