function renderFooterScripts(scripts) {
    const scriptElement = document.createElement('script');
    let scriptContainer;

    // Find an optimal insertion point in the HTML document
    if (document.head) {
        scriptContainer = document.head;
    } else if (document.body && document.body.lastChild) {
        scriptContainer = document.body.lastChild;
    } else {
