                entries[count++] = current;
            }
            current = current->next;
        }
    }

    // Sort the measurements in descending order by RSRP_MEASUREMENT
    qsort(entries, count, sizeof(Entry*), (int (*)(const void*, const void*))compare);
}

int compare(const void* a, const void* b) {
    return ((LTE_PHY_RX_RSRP_REPORT_PDU_T*)a)->params.RSRP_MEASUREMENT <
