    struct in_addr dest_ip;
    char payload[256]; // Adjust the size according to your needs
} Packet;

#define PACKET_ARRAY_INITIAL_SIZE 1024
#define PAYLOAD_MAX_LENGTH 256

int packet_array_size = PACKET_ARRAY_INITIAL_SIZE;
Packet* packets = NULL;

void resize_packet_array() {
    Packet** new_packets = (Packet**)realloc(packets, sizeof(Packet*) * (packet_array_size * 2));
    if (!new_packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    packets = new_packets;
    for (int i = packet_array_size; i < packet_array_size * 2; ++i) {
        packets[i] = NULL;
    }
    packet_array_size *= 2;
}

void validate_ip(const char* ip_str) {
    struct in_addr addr;
    if (inet_pton(AF_INET, ip_str, &addr) <= 0) {
        fprintf(stderr, "Invalid IP address format: %s\n", ip_str);
        exit(EXIT_FAILURE);
    }
}

void validate_payload(const char* payload) {
    if (strlen(payload) > PAYLOAD_MAX_LENGTH) {
        fprintf(stderr, "Payload data exceeds the maximum length of %d bytes\n", PAYLOAD_MAX_LENGTH);
        exit(EXIT_FAILURE);
    }
}

void add_packet(uint32_t id, time_t timestamp, const char* src_ip_str, const char* dest_ip_str, const char* payload) {
    if (packet_array_size == 0) {
        packets = (Packet*)malloc(sizeof(Packet));
        packets[0] = (Packet){id, timestamp, src_ip_str ? inet_addr(src_ip_str) : INADDR_ANY, dest_ip_str ? inet_addr(dest_ip_str) : INADDR_ANY, payload};
        packet_array_size++;
        return;
    }

    if (packet_array_size == packet_array_size * 2) {
        resize_packet_array();
    }

    Packet* packet = &packets[packet_array_size - 1];
    validate_ip(src_ip_str);
    validate_ip(dest_ip_str);
    validate_payload(payload);

    memcpy(&packet->src_ip, src_ip_str ? (void*)&inet_addr(src_ip_str) : &INADDR_ANY, sizeof(struct in_addr));
    memcpy(&packet->dest_ip, dest_ip_str ? (void*)&inet_addr(dest_ip_str) : &INADDR_ANY, sizeof(struct in_addr));
    strcpy(packet->payload, payload);
    packet->id = id;
    packet->timestamp = timestamp;
    packet_array_size++;
}
```

