    if (!map) return NULL;

    map->size = size;
    map->count = 0;
    map->nodes = calloc(size, sizeof(hash_node_t*));
    if (!map->nodes) {
        free(map);
        return NULL;
    }

    pthread_mutex_init(&map->lock, NULL);

    return map;
}

unsigned int hash(unsigned int key, unsigned int size) {
