    if (!node) {
        pthread_mutex_unlock(&map->lock);
        return;
    }

    node->data = pdu;
    node->next = map->nodes[index];
    map->nodes[index] = node;
    map->count++;

    pthread_mutex_unlock(&map->lock);
}

bool find(hash_map_t* map, RNTI rnti, NFAPI_CRC_INDICATION_PDU_T* result) {
    unsigned int index = hash(rnti, map->size);
    pthread_mutex_lock(&map->lock);

    hash_node_t* current = map->nodes[index];
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            *result = current->data;
            pthread_mutex_unlock(&map->lock);
            return true;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&map->lock);
    return false;
}

void log(const char* message) {
