}

void clear(hash_map_t* map) {
    pthread_mutex_lock(&map->lock);
    for (unsigned int i = 0; i < map->size; ++i) {
        hash_node_t* current = map->nodes[i];
        while (current != NULL) {
            hash_node_t* next = current->next;
            free(current);
            current = next;
        }
    }
    map->count = 0;
    pthread_mutex_unlock(&map->lock);
}

void fetch_rnti_assignments(hash_map_t* cache, unsigned int max_age) {
    // Implement external data source fetching here

    time_t now = time(NULL);
    for (unsigned int i = 0; i < cache->size; ++i) {
        hash_node_t* current = cache->nodes[i];
