    session->capacity = capacity;
    session->count = 0;
    session->data = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (session->data == NULL) {
        perror("calloc failed");
        munmap(session, sizeof(Session));
        exit(EXIT_FAILURE);
