use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::env;
use std::sync::Arc;
use tokio::sync::RwLock;
use reqwest::Client;
use config::{Config, ConfigError};

type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;

#[derive(Serialize, Deserialize, Debug)]
struct TokenResponse {
    access_token: String,
    expires_in: u64,
    token_type: String,
    refresh_token: Option<String>,
}

struct Configurations {
    api_url: String,
    log_level: String,
}

impl TokenValidator {
    async fn new(config: &Configurations) -> Self {
        let client = Client::new();
        Self {
            cache: Arc::new(RwLock::new(HashMap::new())),
            config,
            client,
        }
    }

    async fn is_valid(&self, token: &TokenResponse) -> Result<bool> {
        if token.token_type != "Bearer" {
            return Err("Invalid token type".into());
        }

        if token.expires_in <= 0 {
            return Err("Expires in should be a positive integer".into());
        }

        match self.cache.read().await.get(&token.access_token) {
            Some(_) => Ok(true),
            None => {
                let validate_url = format!("{}/validate/{}", self.config.api_url, token.access_token);
                let response = self.client.get(&validate_url).send().await?;
                let status = response.status();
                if status.is_success() {
                    let json: serde_json::Value = response.json().await?;
                    match json["status"].as_str() {
                        Some("valid") => {
                            self.cache.write().await.insert(token.access_token.clone(), token);
                            Ok(true)
                        }
                        _ => Err(format!("Invalid token: {}", json["message"].as_str().unwrap())),
                    }
                } else {
                    Err(format!("Failed to validate token: status code {} {}", status.as_u16(), validate_url))
                }
            }
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let config = Config::default().merge(Config::builder().add_source(env::current_dir(), Glob::new("config/*")).build())?;
    let configurations = Configurations {
        api_url: config.get_string("api_url")?,
        log_level: config.get_string("log_level")?,
    };

    let validator = TokenValidator::new(&configurations)?;
    let token_json = // Read JSON string from input here

    match serde_json::from_str::<TokenResponse>(&token_json) {
        Ok(token) => {
            if let Err(e) = validator.is_valid(&token).await {
                println!("{}", e);
            } else {
                println!("Token is valid");
            }
        }
        Err(e) => println!("Error parsing token JSON: {}", e),
    }

    Ok(())
}
```

