};

typedef void (*PacketCallback)(struct Packet*, const char* elementType, const char* attributes[]);

void processPackets(DOMElement root, int maxStringLength, PacketCallback callback) {
    std::vector<struct Packet> buffer;
    std::stack<DOMElement> stack;
    stack.push(root);

    while (!stack.empty()) {
        DOMElement current = stack.top();
        stack.pop();

        if (current->type == ELEMENT_TYPE) {
            // Check for potential null pointers and edge cases
            if (current->content && current->attributes) {
                struct Packet packet;
                char* content = current->content;
                int contentLength = strlen(content);

                // Validate IP address formats and payload length constraint
                if (validateIP(current->attributes["source"], packet.sourceIP, MAX_IP_LENGTH) &&
                    validateIP(current->attributes["destination"], packet.destinationIP, MAX_IP_LENGTH) &&
                    contentLength <= MAX_PAYLOAD_LENGTH) {
                    // Copy the content into the packet payload
                    strncpy(packet.payload, content, contentLength);
                    packet.payload[contentLength] = '\0';

                    // Call the user-defined callback function
                    callback(&packet, current->type, current->attributes);

                    // Add the packet to the buffer and manage memory usage
                    buffer.push_back(packet);
                }
            }
        }

        // Handle nested elements gracefully without causing stack overflow
        for (DOMElement child : current->children) {
            stack.push(child);
        }
    }

    // Return the final buffer if the traversal completes successfully
    return &buffer[0];
}

