```cpp
#include <iostream>
#include <vector>
#include <memory>
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <sys/mman.h>
#include <cerrno>
#include <stdexcept>
#include <atomic>
#include <mutex>

struct DataStreamContext {
    std::unique_ptr<char[]> buffer;
    size_t bufferSize;
    AES_KEY key;
    unsigned char iv[AES_BLOCK_SIZE];
    std::mutex mutex;
    std::atomic<bool> isEncrypted{false};
};

std::vector<std::unique_ptr<DataStreamContext>> init_communication_channel(size_t max_memory, size_t num_streams, const unsigned char* iv, const unsigned char* key, bool encrypt) {
    std::vector<std::unique_ptr<DataStreamContext>> data_stream_contexts;

    for (size_t i = 0; i < num_streams; ++i) {
        size_t bufferSize = std::min(max_memory / num_streams, 1 << 20); // 1 MB per stream as a starting point
        data_stream_contexts.emplace_back(new DataStreamContext{
            .buffer = std::make_unique<char[]>(bufferSize),
            .bufferSize = bufferSize,
            .iv = iv,
            .key = AES_KEY{},
        });

        if (encrypt) {
            AES_set_encrypt_key(key, 256, data_stream_contexts.back()->iv, &data_stream_contexts.back()->key);
            data_stream_contexts.back()->isEncrypted = true;
        }
    }

    return data_stream_contexts;
}
```

