struct NFAPI_MESSAGE_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    std::unique_ptr<uint8_t[], decltype(&free)> crcData; // Use unique_ptr with a custom deleter for CRC_INDICATION_REL8_TAG data
    bool crcFlag;

    NFAPI_MESSAGE_T() : crcFlag(false) {}
};

class MessageList {
private:
    std::vector<std::unique_ptr<NFAPI_MESSAGE_T>> messages;
    std::mutex mutex;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, UINT32_MAX);

public:
    void addMessage() {
        if (messages.size() >= 10000) return; // Limit to 10,000 messages

        auto msg = std::make_unique<NFAPI_MESSAGE_T>();
        msg->rnti = dis(gen);
        msg->crcData.reset(static_cast<uint8_t*>(malloc(CRC_INDICATION_REL8_TAG_SIZE))); // Allocate buffer for CRC data
        if (!msg->crcData) throw std::bad_alloc();
        msg->crcFlag = rand() % 2; // Randomly generate CRC flag

        std::unique_lock<std::mutex> lock(mutex);
        messages.emplace_back(std::move(msg));
    }

    NFAPI_MESSAGE_T* getMessageByRnti(uint32_t rnti) {
        std::unique_lock<std::mutex> lock(mutex);
        for (auto& msg : messages) {
            if (msg->rnti == rnti) {
                return &*msg;
            }
        }
        return nullptr;
    }

    void updateCRCData(NFAPI_MESSAGE_T* msg, const uint8_t* data, size_t len) {
        std::unique_lock<std::mutex> lock(mutex);
        if (!msg->crcData || !data) throw std::invalid_argument("Invalid arguments");

        msg->crcData.reset(static_cast<uint8_t*>(realloc(msg->crcData.get(), len))); // Reallocate buffer for new CRC data
        if (!msg->crcData) throw std::bad_alloc();
        std::copy_n(data, len, msg->crcData.get());
    }
