// Pool-based memory allocation for large integers
typedef struct {
    void* pool;
    size_t allocated, capacity;
} large_int_pool;

void init_large_int_pool(large_int_pool* pool, size_t initial_capacity) {
    pool->allocated = 0;
    pool->capacity = initial_capacity;
    pool->pool = malloc(initial_capacity * sizeof(long long));
}

void* large_int_alloc(large_int_pool* pool) {
    if (pool->allocated >= pool->capacity) {
        pool->capacity *= 2;
        pool->pool = realloc(pool->pool, pool->capacity * sizeof(long long));
    }
    void* result = pool->pool + pool->allocated++;
    return result;
}

void large_int_free(large_int_pool* pool, void* ptr) {
    pool->allocated--;
