namespace po = boost::program_options;
namespace fs = std::filesystem;

std::mutex mtx;
double totalLines = 0, linesMatched = 0, avgTimePerLine = 0;
unsigned int countThreshold = 1000000, searchStringIndex = -1;
std::ofstream outputFile;
bool displayManpage = false;

struct Resource {
    virtual ~Resource() {}
    virtual void load() = 0;
};

class ConfigFile : public Resource {
public:
    explicit ConfigFile(const std::string& path) : file(path, std::ios::in) {}

    void load() override {
        std::string line;
        while (std::getline(file, line)) {
            processLine(line);
        }
    }

private:
    std::istream& file;

    void processLine(const std::string& line) {
        mtx.lock();
        totalLines++;
        if (searchStringIndex != -1 && line.find(configStrings[searchStringIndex]) == std::string::npos)
            return;
        auto start = std::chrono::high_resolution_clock::now();
        // Process the line here, e.g., load external resources or perform calculations
        auto end = std::chrono::high_resolution_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();
        avgTimePerLine += duration;
        mtx.unlock();
    }

    std::vector<std::string> configStrings;
};

class ExternalResource : public Resource {
public:
    explicit ExternalResource(const std::string& path) : filePath(path) {}

    void load() override {
        try {
            if (fs::exists(filePath)) {
                // Load the resource here, e.g., read from a file or network
                // ...
            } else {
                std::cerr << "Error: Could not find external resource at path: " << filePath << '\n';
            }
        } catch (const fs::filesystem_error& e) {
            std::cerr << "Error: " << e.what() << '\n';
        }
    }

private:
    std::string filePath;
};

void parseCommandLine(int argc, char* argv[]) {
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help", "Display this help message")
        ("c", po::value<unsigned int>()->default_value(countThreshold), "Set a custom count threshold for processing")
        ("s", po::value<std::vector<std::string>>()->multitoken(), "Filter lines containing specific search strings")
        ("o", po::value<std::string>(), "Redirect the output to a specified file")
        ("manpage", "Display detailed usage instructions");

    po::positional_options_description p;
    p.add("config-file", -1);

    po::variables_map vm;
    po::store(po::command_line_parser{argc, argv}.options(desc).positional(p).run(), vm);
    po::notify(vm);

    if (vm.count("help")) {
        std::cout << desc << '\n';
        displayManpage = true;
    } else if (vm.count("manpage")) {
        std::cout << desc << '\n';
        displayManpage = true;
    } else {
        configFiles.push_back(ConfigFile(p["config-file"].as<std::string>()));
        for (const auto& str : vm["s"].as<std::vector<std::string>>()) {
            configStrings.emplace_back(str);
        }
        if (!vm["o"].empty()) {
            outputFile.open(vm["o"].as<std::string>());
        }
    }
}

int main(int argc, char* argv[]) {
    parseCommandLine(argc, argv);

    if (displayManpage) {
        std::cout << desc << '\n';
        return 0;
    }

    for (auto& config : configFiles) {
        config.load();
    }

    if (outputFile.is_open()) {
        outputFile << totalLines << " lines processed\n";
        outputFile << linesMatched << " lines matching search criteria\n";
        outputFile << avgTimePerLine / totalLines << " microseconds per line on average\n";
        outputFile.close();
    } else {
        std::cout << totalLines << " lines processed\n";
        std::cout << linesMatched << " lines matching search criteria\n";
        std::cout << avgTimePerLine / totalLines << " microseconds per line on average\n";
    }

    return 0;
}
```

