    if (!manager) {
        log("Error: Failed to allocate memory for RxueInfoPduManager.");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->num_users = 0;
    manager->pdus = mmap(NULL, MAX_USERS * sizeof(NFAPI_L2_RXUEINFO_PDU*), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (manager->pdus == MAP_FAILED) {
        log("Error: Failed to allocate memory for pdus.");
        free(manager);
        return NULL;
    }

    return manager;
}

void add_ue(RxueInfoPduManager* manager, RX_UE_INFORMATION_TAG tag) {
    pthread_mutex_lock(&manager->lock);

    if (manager->num_users >= MAX_USERS) {
        log("Error: Maximum number of users reached.");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    NFAPI_L2_RXUEINFO_PDU* pdu = manager->pdus[manager->num_users];
    if (!pdu) {
        pdu = malloc(sizeof(NFAPI_L2_RXUEINFO_PDU));
        if (!pdu) {
            log("Error: Failed to allocate memory for PDU.");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pdu->rx_ues = malloc(sizeof(RX_UE_INFORMATION_TAG));
    if (!pdu->rx_ues) {
        log("Error: Failed to allocate memory for rx_ues.");
        free(pdu);
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    pdu->rx_ues[0] = tag;
    manager->pdus[manager->num_users++] = pdu;

    pthread_mutex_unlock(&manager->lock);
}

void shutdown(RxueInfoPduManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->num_users; ++i) {
        NFAPI_L2_RXUEINFO_PDU* pdu = manager->pdus[i];
        if (pdu) {
            free(pdu->rx_ues);
            free(pdu);
        }
    }

    munmap(manager->pdus, MAX_USERS * sizeof(NFAPI_L2_RXUEINFO_PDU*));
    free(manager);

    pthread_mutex_unlock(&manager->lock);
}
