```c
#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int cell_id;
    int ue_id;
    PHY_RRC_Measurements measurements;
    CELL_INFO cell_info;
    pthread_mutex_t lock;
} LTE_UE_measurement;

struct array_manager {
    size_t capacity;
    size_t size;
    LTE_UE_measurement** data;
    pthread_mutex_t lock;
};

void init_array_manager(struct array_manager* manager, size_t initial_capacity) {
    manager->capacity = initial_capacity;
    manager->size = 0;
    manager->data = calloc(initial_capacity, sizeof(LTE_UE_measurement*));
    if (!manager->data) {
        fprintf(stderr, "Failed to allocate memory for array\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&manager->lock, NULL);
}

void resize_array_manager(struct array_manager* manager, size_t new_capacity) {
    LTE_UE_measurement** temp = realloc(manager->data, new_capacity * sizeof(LTE_UE_measurement*));
    if (!temp) {
        fprintf(stderr, "Failed to resize array\n");
        exit(EXIT_FAILURE);
    }
    manager->data = temp;
    manager->capacity = new_capacity;
}

void destroy_array_manager(struct array_manager* manager) {
    free(manager->data);
    pthread_mutex_destroy(&manager->lock);
}

LTE_UE_measurement* find_or_create(struct array_manager* manager, int cell_id, int ue_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->data[i]->cell_id == cell_id && manager->data[i]->ue_id == ue_id) {
            pthread_mutex_unlock(&manager->lock);
            return manager->data[i];
        }
    }

    if (manager->size >= manager->capacity) {
        resize_array_manager(manager, manager->capacity * 2);
    }

    LTE_UE_measurement* new_entry = malloc(sizeof(LTE_UE_measurement));
    if (!new_entry) {
        fprintf(stderr, "Failed to allocate memory for new entry\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&new_entry->lock, NULL);
    new_entry->cell_id = cell_id;
    new_entry->ue_id = ue_id;
    manager->data[manager->size++] = new_entry;

    pthread_mutex_unlock(&manager->lock);
    return new_entry;
}

void process_measurement(LTE_UE_measurement* measurement, PHY_RRC_Measurements new_measurements) {
    pthread_mutex_lock(&measurement->lock);
    measurement->measurements = new_measurements;
    pthread_mutex_unlock(&measurement->lock);
}
```

