} DynamicArray;

DynamicArray create_dynamic_array(size_t capacity) {
    DynamicArray array = {NULL, 0, 0};
    array.data = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array.data) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    array.capacity = capacity;
    pthread_mutex_init(&array.lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
}
