#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t ue_id;
    uint8_t sfi;
    uint8_t ul_ccch_message_type;
    RRC_MESSAGE* rrc_messages;
    size_t rrc_messages_len;
    pthread_mutex_t lock;
} NFAPI_UL_CCCH_MSG;

typedef struct {
    uint32_t id;
    NFAPI_UL_CCCH_MSG* msg;
} HASH_ENTRY;

#define TABLE_SIZE 10007 // prime number for better distribution

HASH_ENTRY* hash_table = NULL;
pthread_mutex_t hash_table_lock = PTHREAD_MUTEX_INITIALIZER;

void init_hash_table() {
    if (hash_table) free(hash_table);
    hash_table = malloc(TABLE_SIZE * sizeof(HASH_ENTRY));
}

NFAPI_UL_CCCH_MSG* create_msg(uint32_t ue_id, uint8_t sfi, uint8_t ul_ccch_message_type) {
    NFAPI_UL_CCCH_MSG* msg = malloc(sizeof(NFAPI_UL_CCCH_MSG));
    msg->ue_id = ue_id;
    msg->sfi = sfi;
    msg->ul_ccch_message_type = ul_ccch_message_type;
    msg->rrc_messages = NULL;
    msg->rrc_messages_len = 0;
    pthread_mutex_init(&msg->lock, NULL);
    return msg;
}

void add_rrc_message(NFAPI_UL_CCCH_MSG* msg, RRC_MESSAGE* rrc_message) {
    size_t new_len = msg->rrc_messages_len + 1;
    msg->rrc_messages = realloc(msg->rrc_messages, new_len * sizeof(RRC_MESSAGE));
    memcpy(&msg->rrc_messages[msg->rrc_messages_len], rrc_message, sizeof(RRC_MESSAGE));
    msg->rrc_messages_len = new_len;
}

void validate_and_add_rrc_message(RRC_MESSAGE* rrc_message) {
    // Validate RRC_MESSAGE here based on your rules
    if (valid_rrc_message(rrc_message)) {
        add_rrc_message(find_msg(rrc_message->ue_id), rrc_message);
    }
}

NFAPI_UL_CCCH_MSG* find_msg(uint32_t ue_id) {
    pthread_mutex_lock(&hash_table_lock);
    size_t hash = ue_id % TABLE_SIZE;
    for (size_t i = 0; i < TABLE_SIZE; ++i) {
        if (i == hash) {
            if (!hash_table[hash].id) {
                hash_table[hash].id = ue_id;
                hash_table[hash].msg = create_msg(ue_id, /* SFI and UL_CCCH_MESSAGE_TYPE */ , /* default values or read from configuration */ );
                break;
            } else if (hash_table[hash].id == ue_id) {
                return hash_table[hash].msg;
            }
        }
        if (i + 1 == TABLE_SIZE) i = 0; // wrap around to the beginning of the table
    }
    pthread_mutex_unlock(&hash_table_lock);
    return NULL;
}

void process_message(RRC_MESSAGE* rrc_message) {
    NFAPI_UL_CCCH_MSG* msg = find_msg(rrc_message->ue_id);
    if (msg) {
        validate_and_add_rrc_message(rrc_message);
        event_dispatch(EVENT_NEW_MESSAGE, rrc_message->ue_id, rrc_message->timestamp);
    }
}

void init() {
    init_hash_table();
    // Initialize other components here (event loop, data source, etc.)
}
