#include <iostream>
#include <vector>
#include <list>
#include <cstdlib>
#include <ctime>
#include <new>

struct Record {
    int key;
    int value;
};

class Random {
public:
    Random(int min, int max) : min_(min), max_(max) {}

    int next() {
        return min_ + rand() % (max_ - min_ + 1);
    }

private:
    int min_, max_;
};

class HashTable {
public:
    HashTable(size_t size, size_t offsetSize, size_t recordSize)
        : table_(std::vector<Record*>(size)), keys_(std::vector<int>(offsetSize)), offsets_(std::vector<long>(offsetSize)) {}

    void resize(size_t newSize) {
        auto oldTable = std::move(table_);
        table_.resize(newSize);
        keys_.resize(newSize);
        offsets_.resize(newSize);
        for (auto& record : oldTable) {
            if (record != nullptr) {
                insert(record->key, *record);
                delete record;
            }
        }
    }

    Record* find(int key) {
        size_t index = hash(key);
        for (size_t i = index; i < table_.size(); ++i) {
            if (table_[i] == nullptr || table_[i]->key != key) continue;
            return table_[i];
        }
        return nullptr;
    }

    void insert(int key, Record record) {
        size_t index = hash(key);
        for (size_t i = index; i < table_.size(); ++i) {
            if (table_[i] == nullptr || table_[i]->key != key) {
                offsets_[index]++;
                if (offsets_[index] > table_.size()) resize(table_.size() * 2);
                table_[index + offsets_[index]] = new Record(record);
                keys_[index] = index + offsets_[index];
                return;
            }
        }
    }

    void remove(int key) {
        size_t index = hash(key);
        for (size_t i = index; i < table_.size(); ++i) {
            if (table_[i] == nullptr || table_[i]->key != key) continue;
            keys_[index] = keys_[index + offsets_[index]];
            delete table_[i];
            table_[i] = nullptr;
            --offsets_[index];
            break;
        }
    }

private:
    size_t hash(int key) const {
        return key % table_.size();
    }

    std::vector<Record*> table_;
    std::vector<int> keys_;
    std::vector<long> offsets_;
};

void allocateAndInitializeMemory(HashTable& hashTable, size_t offsetSize, size_t recordSize, size_t limit) {
    auto memoryUsage = offsetSize * sizeof(long) + recordSize * hashTable.table_.capacity() * sizeof(Record);
    if (memoryUsage > limit) throw std::runtime_error("Memory usage exceeds the specified limit.");

    Random random(0, INT_MAX);
    for (size_t i = 0; i < offsetSize; ++i) {
        offsets_[i] = -1;
    }
    for (auto& record : hashTable.table_) {
        new (record) Record();
    }

    for (size_t i = 0; i < offsetSize; ++i) {
        if (offsets_[i] != -1) continue;
        auto key = random.next();
        hashTable.insert(key, {key, random.next()});
    }
}

void freeMemory(HashTable& hashTable) {
    for (auto& record : hashTable.table_) {
        if (record != nullptr) delete record;
    }
}
