    node->mode = (parent->mode == 1) ? 0 : 1;
    node->parent = parent;
    node->children = calloc(node->size, sizeof(Node*));
    if (!node->children) {
        free(node);
        return NULL;
    }

    pthread_mutex_init(&node->lock, NULL);

    return node;
}

void populate_file_system() {
    root = create_node(0, NULL);
    if (!root) {
        printf("Failed to allocate memory for root node.\n");
        return;
    }

    pthread_t threads[NUM_THREADS];
    for (int i = 1; i < MAX_NODES && i <= NUM_THREADS; ++i) {
        pthread_create(&threads[i - 1], NULL, create_child, (void*)i);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void* create_child(void* arg) {
    int index = *(int*)arg;
    Node* parent = root;
    for (int i = 0; i < index && parent->children[i]; ++i) {
        parent = parent->children[i];
    }

    if (!parent->children[index]) {
        parent->children[index] = create_node(index, parent);
        if (parent->children[index]) {
            pthread_mutex_lock(&parent->lock);
            ++parent->size;
            pthread_mutex_unlock(&parent->lock);
        }
    }

    pthread_exit(NULL);
}

