    int clientSocket, serverSocket;
    char *sessionData;
    size_t dataLen;
} NetworkSession;

static sem_t sessionsMutex; // Mutex for accessing the session array
static NetworkSession *sessions;
static int maxSessions = 10000;
static int numSessions = 0;

void logError(const char *message) {
    FILE *logFile = fopen("server.log", "a");
    if (logFile != NULL) {
        fprintf(logFile, "%s\n", message);
        fclose(logFile);
    }
}

void* handleSession(void* arg) {
    NetworkSession *session = (NetworkSession*)arg;

    // Handle session logic here

    free(session->sessionData);
    free(session);
    return NULL;
}

int initSessions() {
    int i;
    sem_init(&sessionsMutex, 0, 1);

    size_t sessionSize = sizeof(NetworkSession) + MAX_SESSION_DATA_LENGTH; // Adjust MAX_SESSION_DATA_LENGTH according to your needs
    sessions = (NetworkSession*)calloc(maxSessions, sessionSize);
    if (!sessions) {
        logError("Failed to allocate memory for sessions");
        return -1;
    }

    return 0;
}

int addSession(NetworkSession *session) {
    sem_wait(&sessionsMutex);

    if (numSessions >= maxSessions) {
        logError("Maximum number of sessions reached");
        sem_post(&sessionsMutex);
        return -1;
    }

    memcpy(sessions + numSessions, session, sizeof(NetworkSession));
    numSessions++;
    sem_post(&sessionsMutex);

    pthread_t threadId;
    if (pthread_create(&threadId, NULL, handleSession, session) != 0) {
        logError("Failed to create session handling thread");
        return -1;
    }

    return 0;
}

void cleanup() {
    NetworkSession *session;
    sem_wait(&sessionsMutex);

    for (int i = 0; i < numSessions; ++i) {
        session = sessions + i;
        pthread_detach(session->clientSocket); // Detach the thread to avoid memory leak when the program terminates
    }

    free(sessions);
    sem_destroy(&sessionsMutex);
}
