    unsigned char flag;
    char *buffer;
} data_entry;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    data_entry *entries;
} collection;

void *generate_timestamp(void *arg) {
    char *buffer = malloc(20);
    struct tm *tm = localtime(&time(NULL));
    strftime(buffer, 20, "%Y-%m-%d %H:%M:%S", tm);
    buffer[19] = '\0';
    return buffer;
}

void init_collection(collection *coll) {
    coll->capacity = 10;
    coll->size = 0;
    coll->entries = malloc(coll->capacity * sizeof(data_entry));
    pthread_mutex_init(&coll->lock, NULL);
}

void destroy_collection(collection *coll) {
    for (size_t i = 0; i < coll->size; ++i) {
        free(coll->entries[i].buffer);
    }
    free(coll->entries);
    pthread_mutex_destroy(&coll->lock);
}

void add_entry(collection *coll, double value, unsigned char flag, char *timestamp) {
    if (coll->size == coll->capacity) {
        coll->capacity *= 2;
        data_entry *new_entries = realloc(coll->entries, coll->capacity * sizeof(data_entry));
        if (!new_entries) {
            fprintf(stderr, "Failed to allocate memory\n");
            exit(EXIT_FAILURE);
        }
        coll->entries = new_entries;
    }
    data_entry *entry = &coll->entries[coll->size];
    entry->value = value;
    entry->flag = flag;
    entry->buffer = timestamp;
    ++coll->size;
}

data_entry* get_entry(collection *coll, size_t index) {
    pthread_mutex_lock(&coll->lock);
    data_entry *entry = &coll->entries[index];
    pthread_mutex_unlock(&coll->lock);
    return entry;
}
```

