function createSessionTokenAndStoreUser($userId, $expiryTime, $sessionType, $userPassword) {
    // Validate inputs
    if (!is_numeric($userId) || strlen($userId) > 255) {
        throw new Exception("Invalid or excessively long userId provided.");
    }

    if (!is_int($expiryTime) || $expiryTime <= time()) {
        throw new Exception("Invalid expiryTime provided. Must be a future timestamp.");
    }

    if (!in_array($sessionType, ['file', 'database', 'redis'], true)) {
        throw new Exception("Unsupported sessionType provided. Supported types: file, database, redis.");
    }

    // Generate cryptographically secure session token
    $tokenLength = 32; // Adjust as needed for your specific use case
    $charSet = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    $token = '';
    $maxAttempts = 100;
    while ($maxAttempts > 0 && strlen($token) < $tokenLength) {
        $token .= $charSet[random_int(0, strlen($charSet) - 1)];
        $maxAttempts--;
    }

    // Hash the provided userPassword using password_hash function
    $hashedPassword = password_hash($userPassword, PASSWORD_ARGON2I);

    // Store session token and hashed password in persistent storage system
    $storage = match ($sessionType) {
        'file' => new SessionStorageFile(),
        'database' => new SessionStorageDatabase(),
        'redis' => new SessionStorageRedis(),
    };

    try {
        $storage->storeSessionData($userId, $token, $hashedPassword, $expiryTime);
    } catch (Exception $e) {
        throw new Exception("Error storing session data: " . $e->getMessage());
    }
}
```

