};

class DynamicList {
public:
    DynamicList(boost::asio::io_service& io_service)
        : list_(std::list<NFAPI_CRC_INDICATION_PDU_T>()),
          queue_(boost::lockfree::spsc_queue<NFAPI_CRC_INDICATION_PDU_T*>(1024)),
          log_(boost::log::get_trivial_logger("dynamic_list")) {
        // Initialize each structure with default values or random data as needed
    }

    void add(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        if (auto ptr = queue_.enqueue(new NFAPI_CRC_INDICATION_PDU_T(pdu)); ptr != nullptr) {
            io_service.post([ptr]() {
                lock_.lock();
                list_.splice(list_.end(), *ptr);
                lock_.unlock();
                delete ptr;
                log_success("Add operation successful");
            });
        } else {
            log_error("Memory allocation failure during add operation");
        }
    }

    bool remove(uint32_t rnti) {
        lock_.lock();
        auto it = std::find_if(list_.begin(), list_.end(), [rnti](const auto& pdu) { return pdu.rnti == rnti; });
        if (it != list_.end()) {
            list_.erase(it);
