            return true;
        }
        log_error("Validation failure during remove operation: RNTI not found");
        return false;
    }

    const NFAPI_CRC_INDICATION_PDU_T* find(uint32_t rnti) const {
        lock_.lock();
        auto it = std::find_if(list_.begin(), list_.end(), [rnti](const auto& pdu) { return pdu.rnti == rnti; });
        lock_.unlock();
        return it != list_.end() ? &*it : nullptr;
    }

private:
    std::list<NFAPI_CRC_INDICATION_PDU_T> list_;
    boost::lockfree::spsc_queue<NFAPI_CRC_INDICATION_PDU_T*> queue_;
    boost::mutex lock_;

    BOOST_LOG_TRIVIAL(trace) void log_success(const std::string& message) {
        BOOST_LOG_TRIVIAL(info) << "[" << std::this_thread::get_id() << "] " << message;
    }

