void cleanup() {
    std::list<NFAPI_CRC_INDICATION_PDU_T> newList;
    auto now = std::chrono::steady_clock::now();
    std::for_each(list.begin(), list.end(), [&](auto& elem) {
        if (elem.timestamp + std::chrono::seconds(60) > now) {
            newList.push_back(elem);
        }
    });
    std::swap(newList, list);
}

void push_element(const NFAPI_CRC_INDICATION_PDU_T& elem) {
    mtx.lock();
    if (list.size() < MAX_STRUCTURES) {
        elem.timestamp = std::chrono::steady_clock::now();
        list.push_back(elem);
    }
    mtx.unlock();
}

void pop_element() {
    mtx.lock();
    if (!list.empty()) {
        auto it = list.begin();
        list.pop_front();
        mtx.unlock();
        return *it;
    }
    mtx.unlock();
}

void run(int numThreads) {
