    bool update(int id, const NR_Uplink_Transport_Channel& new_channel) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::find_if(channels.begin(), channels.end(), [id](const auto& channel) { return channel.id == id; });
        if (it != channels.end()) {
