public class NetworkConfigUpdater {

    public void updateNetworkConfiguration(String configFile, List<String> command) throws IOException {
        deleteFile(configFile);
        ProcessBuilder pb = new ProcessBuilder(command);
        Process process = pb.start();

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        String line;
        List<String> output = new ArrayList<>();
        List<String> errorOutput = new ArrayList<>();

        while ((line = reader.readLine()) != null) {
            output.add(line);
        }

        while ((line = errorReader.readLine()) != null) {
            errorOutput.add(line);
        }

        // Log the outputs for debugging purposes
        System.out.println("Standard Output:");
        for (String s : output) {
            System.out.println(s);
        }

        System.out.println("Standard Error:");
        for (String s : errorOutput) {
            System.out.println(s);
        }
    }

    private void deleteFile(String filePath) throws IOException {
        if (Files.exists(new File(filePath).toPath())) {
            Files.deleteIfExists(new File(filePath).toPath());
        }
    }
}
