    uint8_t CRCFLAG;
    NFAPI_CRC_INDICATION_PDU_T* pdu; // Pointer to the list of CRC Indication PDUs
} UEState;

UEState* initUEStatesWithSIBConfig(uint16_t numSIBs, uint16_t SIBSize) {
    if (numSIBs > 16 || numSIBs == 0) {
        fprintf(stderr, "Invalid number of System Information Blocks. Supported range: 1-16\n");
        return NULL;
    }

    UEState* ueStates = (UEState*)malloc(sizeof(UEState) * numSIBs);
    if (!ueStates) {
        fprintf(stderr, "Memory allocation failure. Cannot initialize UE states.\n");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (uint16_t i = 0; i < numSIBs; ++i) {
        ueStates[i].UEID = i + 1;
        ueStates[i].RRC_STATE = 0;
        ueStates[i].SRB_CONFIG = 0;
        ueStates[i].RX_UE_INFORMATION_TAG = rand() % 256;
        ueStates[i].RNTI = rand() % 65536;
        ueStates[i].CRC_INDICATION_REL8_TAG = rand() % 65536;
        ueStates[i].CRCFLAG = rand() % 2;

        // Allocate memory for NFAPI_CRC_INDICATION_PDU_T structures
        ueStates[i].pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(SIBSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!ueStates[i].pdu) {
            fprintf(stderr, "Memory allocation failure for UE %d. Cannot initialize SIBs.\n", i + 1);
            free(ueStates);
            return NULL;
        }

        // Initialize each NFAPI_CRC_INDICATION_PDU_T structure with the required fields
        for (uint16_t j = 0; j < SIBSize; ++j) {
            ueStates[i].pdu[j].RX_UE_INFORMATION_TAG = ueStates[i].RX_UE_INFORMATION_TAG;
            ueStates[i].pdu[j].RNTI = ueStates[i].RNTI;
            ueStates[i].pdu[j].CRC_INDICATION_REL8_TAG.tag = ueStates[i].CRC_INDICATION_REL8_TAG;
            ueStates[i].pdu[j].CRC_INDICATION_REL8_TAG.crcFlag = ueStates[i].CRCFLAG;
        }
    }

    return ueStates;
}

