} NFDataSession;

NFDataSession* setupNFDataSession(int max_sessions) {
    if (max_sessions <= 0 || max_sessions > 32) {
        fprintf(stderr, "Invalid number of sessions\n");
        return NULL;
    }

    NFDataSession* sessions = malloc(sizeof(NFDataSession) * max_sessions);
    if (!sessions) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < max_sessions; ++i) {
        sessions[i].id = -1;
        sessions[i].type = INVALID_PDUSESSION_TYPE;
        sessions[i].uid = INVALID_UE_ID;
        sessions[i].sm_context = NULL;
        sessions[i].sm_data = NULL;
        sessions[i].resource_setup_request = NULL;
        pthread_mutex_init(&sessions[i].lock, NULL);
    }

    return sessions;
}

void teardownNFDataSession(NFDataSession* sessions, int max_sessions) {
    for (int i = 0; i < max_sessions; ++i) {
        if (sessions[i].sm_context) free(sessions[i].sm_context);
        if (sessions[i].sm_data) free(sessions[i].sm_data);
        if (sessions[i].resource_setup_request) free(sessions[i].resource_setup_request);
        pthread_mutex_destroy(&sessions[i].lock);
    }

