#include <iostream>
#include <forward_list>
#include <string>
#include <random>
#include <vector>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crcTag;
    bool crcFlag;
};

class DynamicArray {
public:
    DynamicArray(size_t numElements = 0, int seed = std::random_device{}());
    ~DynamicArray();
    void push_front(const NFAPI_CRC_INDICATION_PDU_T& pdu);
    void insertAfter(const std::string& searchKey, const NFAPI_CRC_INDICATION_PDU_T& pdu);
    void printList();
private:
    std::forward_list<NFAPI_CRC_INDICATION_PDU_T> list;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> buffer;
    std::random_device rd;
    std::mt19937 gen;

    void ensureCapacity(size_t numElements);
};

DynamicArray::DynamicArray(size_t numElements, int seed) : rd(seed), gen(rd()) {
    ensureCapacity(numElements);
}

DynamicArray::~DynamicArray() {
    list.clear();
    buffer.clear();
}

void DynamicArray::ensureCapacity(size_t numElements) {
    while (list.size() + buffer.size() < numElements) {
        buffer.emplace_back();
        gen >> std::uniform_int_distribution<int>(0, INT_MAX)(buffer.back().rnti);
        buffer.back().crcTag = static_cast<CRC_INDICATION_REL8_TAG>(gen() % CRC_INDICATION_REL8_TAG::MAX_VALUE);
        buffer.back().crcFlag = gen % 2 == 0;
    }
}

void DynamicArray::push_front(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
    list.emplace_front(pdu);
    ensureCapacity(list.size());
}

void DynamicArray::insertAfter(const std::string& searchKey, const NFAPI_CRC_INDICATION_PDU_T& pdu) {
    auto it = list.begin();
    if (it == list.end() || it->tag != searchKey) {
        for (; it != list.end(); ++it) {}
        list.emplace_after(it, pdu);
    } else {
        list.insert_after(it, pdu);
    }
    ensureCapacity(list.size());
}

void DynamicArray::printList() {
    for (const auto& pdu : list) {
        std::cout << "Tag: " << pdu.tag << ", RNTI: " << pdu.rnti << ", CRC Tag: " << pdu.crcTag << ", CRC Flag: " << pdu.crcFlag << '\n';
    }
}
