typedef struct {
    NFAPI_MSG_TYPE type;
    uint8_t *payload;
    int ref_count;
} NFAPI_MESSAGE_T;

static NFAPI_MESSAGE_T* buffer_pool = NULL;
static size_t buffer_pool_size = 0;
static size_t total_messages_created = 0;

void init_buffer_pool(size_t size) {
    if (buffer_pool_size > 0) free(buffer_pool);
    buffer_pool = malloc(size * sizeof(NFAPI_MESSAGE_T));
    buffer_pool_size = size;
}

void generate_payload(NFAPI_MESSAGE_T* msg, size_t payload_size) {
    if (!msg || !payload_size) return;

    msg->payload = malloc(payload_size);
    if (!msg->payload) {
        fprintf(stderr, "Error allocating memory for payload\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (size_t i = 0; i < payload_size; ++i) msg->payload[i] = rand() & 0xFF;
}

NFAPI_MESSAGE_T* initNfapiMessages(size_t num_messages, size_t message_type, size_t payload_size) {
    if (num_messages > buffer_pool_size) num_messages = buffer_pool_size;

    NFAPI_MESSAGE_T* messages = &buffer_pool[total_messages_created];
    for (size_t i = 0; i < num_messages; ++i) {
        messages[i].type = message_type;
        generate_payload(&messages[i], payload_size);
        messages[i].ref_count = 1;
        total_messages_created += 1;
        messages += 1;
    }

    return messages;
}

void freeNfapiMessage(NFAPI_MESSAGE_T* msg) {
    if (!msg || !msg->payload) return;

    free(msg->payload);
    msg->ref_count = 0;
}
