using List = boost::container::dynamic_vector<NFAPI_CRC_INDICATION_PDU_T>;
using SList = boost::lockfree::slist<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>>;

class DynamicList {
public:
    explicit DynamicList(size_t maxSize, std::string logFile)
        : list_(maxSize), head_(nullptr), tail_(nullptr), logFile_(logFile) {}

    void push_back(NFAPI_CRC_INDICATION_PDU_T&& data) {
        if (list_.size() >= maxSize) {
            prune();
        }

        auto newNode = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(std::move(data));
        if (!head_) {
            head_ = tail_ = newNode.get();
        } else {
            tail_->next_.construct(newNode.get());
            tail_ = tail_->next_.load();
        }
        list_.push_back(std::move(newNode));
    }

    void prune() {
        if (head_) {
            auto temp = head_;
            head_ = head_->next_.load();
            temp->~NFAPI_CRC_INDICATION_PDU_T();
            list_.pop_back();
        }
    }

    void log(const std::string& message) {
        if (!logFile_.empty()) {
            boost::filesystem::path path{logFile_};
            std::ofstream file;
            try {
                file.open(path, std::ios_base::app);
                file << message << std::endl;
            } catch (const std::exception& e) {
                BOOST_LOG_TRIVIAL(error) << "Failed to log: " << e.what();
            }
        }
    }

private:
