#include <cassert>

const int MAX_CONNECTIONS = 5000;
const int MAX_STRING_LENGTH = 100;
const char* PRINTABLE_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()-_=+{}[]|;:,.<>?/ ";

struct Connection {
    int id;
    std::string ip;
    int serverPort;
    int connectionID;
    int byteOffset = 0;
    std::tm timestamp;
    std::string lastMessage;
};

class DynamicList {
public:
    enum class StatusCode { SUCCESS, LIST_FULL, INVALID_ID, MEMORY_ERROR };

    void addConnection(const Connection& connection);
    bool updateConnection(int index, const Connection& connection);
    bool removeConnection(int index);
    int getNumActiveConnections() const;
    double getAvgOperationTime();
    StatusCode lastOperationResult() const { return lastOperationResult_; }

private:
    std::vector<Connection> connections_;
    std::mutex mutex_;
    int numActiveConnections_ = 0;
    double totalOperationTime_ = 0.0;
    StatusCode lastOperationResult_ = StatusCode::SUCCESS;

    void generateRandomString(std::string& str) {
        for (auto& c : str) {
            c = PRINTABLE_CHARS[rand() % strlen(PRINTABLE_CHARS)];
        }
        assert(str.length() <= MAX_STRING_LENGTH);
    }

    void setTimestamp(Connection& connection) {
        auto now = std::chrono::system_clock::now();
        connection.timestamp = *std::localtime(&now.time_since_epoch().count());
    }
};

void DynamicList::addConnection(const Connection& connection) {
    std::unique_lock<std::mutex> lock(mutex_);

    if (numActiveConnections_ >= MAX_CONNECTIONS) {
        lastOperationResult_ = StatusCode::LIST_FULL;
        return;
    }

    connection.id = numActiveConnections_;
    setTimestamp(connection);
    generateRandomString(connection.lastMessage);
    connections_.push_back(connection);
    ++numActiveConnections_;

    auto start = std::chrono::high_resolution_clock::now();
    // Simulate some delay to demonstrate operation time calculation
    std::this_thread::sleep_for(std::chrono::milliseconds(50));
    auto end = std::chrono::high_resolution_clock::now();
    totalOperationTime_ += std::chrono::duration<double>(end - start).count();
}

bool DynamicList::updateConnection(int index, const Connection& connection) {
    std::unique_lock<std::mutex> lock(mutex_);

    if (index < 0 || index >= numActiveConnections_) {
        lastOperationResult_ = StatusCode::INVALID_ID;
        return false;
    }

    setTimestamp(connection);
    connections_[index] = connection;

    auto start = std::chrono::high_resolution_clock::now();
    // Simulate some delay to demonstrate operation time calculation
    std::this_thread::sleep_for(std::chrono::milliseconds(50));
    auto end = std::chrono::high_resolution_clock::now();
    totalOperationTime_ += std::chrono::duration<double>(end - start).count();

    lastOperationResult_ = StatusCode::SUCCESS;
    return true;
}

bool DynamicList::removeConnection(int index) {
    std::unique_lock<std::mutex> lock(mutex_);

    if (index < 0 || index >= numActiveConnections_) {
        lastOperationResult_ = StatusCode::INVALID_ID;
        return false;
    }

    --numActiveConnections_;
    Connection removedConnection = std::move(connections_[index]);
    connections_.erase(connections_.begin() + index);

    auto start = std::chrono::high_resolution_clock::now();
    // Simulate some delay to demonstrate operation time calculation
    std::this_thread::sleep_for(std::chrono::milliseconds(50));
    auto end = std::chrono::high_resolution_clock::now();
    totalOperationTime_ += std::chrono::duration<double>(end - start).count();

    lastOperationResult_ = StatusCode::SUCCESS;
    return true;
}

int DynamicList::getNumActiveConnections() const {
    std::unique_lock<std::mutex> lock(mutex_);
    return numActiveConnections_;
}

double DynamicList::getAvgOperationTime() {
    return totalOperationTime_ / numActiveConnections_;
}
