#include <chrono>
#include <thread>

struct NAS_MESSAGE {
    // Implement NAS PDU and other necessary members here
};

struct S1AP_CTXT {
    // Implement S1AP context and other necessary members here
};

struct LTE_UPLINK_NAS_TRANSPORT_T {
    NAS_MESSAGE msg;
    S1AP_CTXT ctx;
};

class MessageQueue {
public:
    struct Config {
        size_t maxEntries = 10000;
        std::unordered_map<int, size_t> priorityLimits;
    };

    explicit MessageQueue(const Config& config) : m_config(config) {}

    void initialize() {
        m_queue.resize(m_config.maxEntries);
        for (auto& entry : m_queue) {
            entry = std::make_unique<LTE_UPLINK_NAS_TRANSPORT_T>();
        }
    }

    void enqueue(const LTE_UPLINK_NAS_TRANSPORT_T& msg, int priority) {
        if (priority >= 0 && priority < m_config.priorityLimits.size() &&
            m_queue[m_next].get() != nullptr &&
            m_config.priorityLimits[priority] > m_occupied[priority]) {
            m_queue[m_next]->reset(std::make_unique<LTE_UPLINK_NAS_TRANSPORT_T>(msg));
            ++m_occupied[priority];
            ++m_next;
            if (m_next == m_queue.size()) {
                m_next = 0;
            }
        } else {
            throw std::runtime_error("Failed to enqueue message: Invalid priority or queue overflow");
        }
    }

    void dequeue(int priority) {
        if (m_occupied[priority] > 0) {
            --m_occupied[priority];
            m_next = (m_next + (m_occupied[priority] - 1)) % m_queue.size();
        } else {
            throw std::runtime_error("Failed to dequeue message: Empty priority queue");
        }
    }

    void logHealth() const {
        std::cout << "Current occupancy:\n";
        for (const auto& [priority, count] : m_occupied) {
            std::cout << "Priority " << priority << ": " << count << "\n";
        }
    }

private:
    Config m_config;
    std::vector<std::unique_ptr<LTE_UPLINK_NAS_TRANSPORT_T>> m_queue;
    size_t m_next = 0;
    std::array<size_t, m_config.priorityLimits.size()> m_occupied{};
};
```

