```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    uint32_t enb_id;
    ENB_CELL_INFO_T* cell_info;
} LTE_ENB_STATEIE_T;

typedef struct {
    size_t capacity;
    size_t size;
    LTE_ENB_STATEIE_T* data;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->capacity = initial_capacity;
    array->size = 0;
    array->data = (LTE_ENB_STATEIE_T*)calloc(initial_capacity, sizeof(LTE_ENB_STATEIE_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array && array->data) {
        for (size_t i = 0; i < array->size; ++i) {
            free(array->data[i].cell_info);
        }
        free(array->data);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

LTE_ENB_STATEIE_T* get_enb_by_id(DynamicArray* array, uint32_t enb_id) {
    if (array->size == 0) return NULL;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].enb_id == enb_id) {
            pthread_mutex_unlock(&array->lock);
            return &array->data[i];
        }
    }

    pthread_mutex_unlock(&array->lock);
    return NULL;
}

bool add_enb(DynamicArray* array, uint32_t enb_id, ENB_CELL_INFO_T* cell_info) {
    if (array->size == array->capacity) {
        array->capacity *= 2;
        LTE_ENB_STATEIE_T* new_data = (LTE_ENB_STATEIE_T*)realloc(array->data, array->capacity * sizeof(LTE_ENB_STATEIE_T));
        if (!new_data) return false;
        array->data = new_data;
    }

    LTE_ENB_STATEIE_T* enb = &array->data[array->size];
    enb->enb_id = enb_id;
    enb->cell_info = malloc(sizeof(ENB_CELL_INFO_T));
    if (!enb->cell_info) return false;

    memcpy(enb->cell_info, cell_info, sizeof(ENB_CELL_INFO_T));
    ++array->size;

    return true;
}

void iterate_enbs(DynamicArray* array, void (*callback)(LTE_ENB_STATEIE_T* enb)) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        callback(&array->data[i]);
    }

    pthread_mutex_unlock(&array->lock);
}
```

