class MemoryPool {
public:
    void* allocate(size_t size) {
        if (freeList.empty()) {
            char* newBlock = static_cast<char*>(malloc(blockSize * numBlocks));
            if (!newBlock) return nullptr;

            for (size_t i = 0; i < numBlocks - 1; ++i) {
                freeList.push_back(newBlock + i * size);
            }
            freeList.push_front(newBlock);
        }

        void* result = freeList.back();
        freeList.pop_back();
        return result;
    }

    void deallocate(void* ptr) {
        freeList.push_back(ptr);
    }

private:
    std::vector<char> freeList;
    const size_t blockSize = sizeof(LTE_RRC_CME_STRUCT);
    const size_t numBlocks = 10000;
};

class EventManager {
public:
    void addEvent(const LTE_RRC_CME_STRUCT& event) {
        auto it = events.find(event.id);
        if (it != events.end()) return; // Duplicate event, do nothing

        auto newEvent = static_cast<LTE_RRC_CME_STRUCT*>(memoryPool.allocate(sizeof(LTE_RRC_CME_STRUCT)));
        std::copy(std::begin(event), std::end(event), newEvent);
        events[newEvent->id] = newEvent;
    }

    void updateEvent(uint32_t id, const LTE_RRC_CME_STRUCT& event) {
        auto it = events.find(id);
        if (it == events.end()) return; // Event not found, do nothing

        std::copy(std::begin(event), std::end(event), it->second);
    }

    void removeEvent(uint32_t id) {
        auto it = events.find(id);
        if (it == events.end()) return; // Event not found, do nothing

        memoryPool.deallocate(it->second);
        events.erase(it);
