    TX_RX_CONFIGURE_REQUEST config;
    struct LTE_PHY_TX_MESSAGE *next;
} LTE_PHY_TX_MESSAGE;

static LTE_PHY_TX_MESSAGE* head = NULL;
static size_t capacity = 0;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void validate(const TX_RX_CONFIGURE_REQUEST *config) {
    if (config->bandwidth < MIN_BANDWIDTH || config->bandwidth > MAX_BANDWIDTH) {
        fprintf(stderr, "Invalid bandwidth: %u\n", config->bandwidth);
        return;
    }

    if (config->subcarrier_spacing < MIN_SUB_CARRIER_SPACING || config->subcarrier_spacing > MAX_SUB_CARRIER_SPACING) {
        fprintf(stderr, "Invalid subcarrier spacing: %u\n", config->subcarrier_spacing);
        return;
    }

    if (config->transmission_power < MIN_TRANSMISSION_POWER || config->transmission_power > MAX_TRANSMISSION_POWER) {
        fprintf(stderr, "Invalid transmission power: %d\n", config->transmission_power);
        return;
    }
}

void resize(size_t new_capacity) {
    LTE_PHY_TX_MESSAGE *current = head;
    capacity = new_capacity;

    while (head != NULL && capacity > 0) {
        head = head->next;
        free(current);
        current = head;
        capacity--;
    }
}

void add_message(const TX_RX_CONFIGURE_REQUEST *config) {
    pthread_mutex_lock(&lock);

    if (capacity == 0) {
        resize(INITIAL_CAPACITY);
    }

    LTE_PHY_TX_MESSAGE* new_message = malloc(sizeof(LTE_PHY_TX_MESSAGE));
    if (!new_message) {
        fprintf(stderr, "Out of memory\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    validate(config);
    new_message->config = *config;
    new_message->next = head;
    head = new_message;

    pthread_mutex_unlock(&lock);
}
