public class DatabaseHelper
{
    private readonly ILogger<DatabaseHelper> _logger;
    public DatabaseHelper(ILogger<DatabaseHelper> logger)
    {
        _logger = logger;
    }

    public async Task<IDataReader> ExecuteQueryAsync(List<NFAPI_CRC_INDICATION_PDU_T> pdus, SqlConnection connection, string commandText, int timeout)
    {
        using var command = new SqlCommand(commandText, connection);
        command.Parameters.AddRange(pdus.Select(p => new SqlParameter("@" + nameof(p.rx_ue_information_tag), p.rx_ue_information_tag)).ToArray());
        command.Parameters.AddRange(pdus.Select(p => new SqlParameter("@" + nameof(p.rnti), p.rnti)).ToArray());
        command.Parameters.AddRange(pdus.Select(p => new SqlParameter("@" + nameof(p.crc_indication_rel8_tag[0]), p.crc_indication_rel8_tag[0])).ToArray());
        command.Parameters.AddRange(pdus.Select(p => new SqlParameter("@" + nameof(p.crc_indication_rel8_tag[1]), p.crc_indication_rel8_tag[1])).ToArray());
        command.Parameters.AddRange(pdus.Select(p => new SqlParameter("@" + nameof(p.crc_indication_rel8_tag[2]), p.crc_indication_rel8_tag[2])).ToArray());
        command.Parameters.AddRange(pdus.Select(p => new SqlParameter("@" + nameof(p.crc_indication_rel8_tag[3]), p.crc_indication_rel8_tag[3])).ToArray());

        using var reader = await command.ExecuteReaderAsync();

        if (reader.HasRows && !command.Connection.State.Equals(ConnectionState.Open))
            await command.Connection.OpenAsync();

        if (!reader.HasRows && command.Connection.State.Equals(ConnectionState.Open))
            await command.Connection.CloseAsync();

        return reader;
