    USER_ACTIVITY,
    SYSTEM_STATUS,
    NETWORK_ERROR,
    // Add more event types here
};

class NetworkEventQueue {
public:
    void enqueue(const NetworkEvent& event) {
        queue.push(event);
    }

    bool try_dequeue(NetworkEvent& event) {
        if (queue.try_pop(event)) {
            return true;
        }
        return false;
    }

private:
    boost::lockfree::smp_queue<NetworkEvent> queue;
};

class NetworkEventVisitor {
public:
    virtual void visitUserActivity(const NetworkEvent& event) = 0;
    virtual void visitSystemStatus(const NetworkEvent& event) = 0;
    virtual void visitNetworkError(const NetworkEvent& event) = 0;
};

class NetworkEventProcessor {
public:
    void processEvents(NetworkEventQueue& queue, NetworkEventVisitor& visitor) {
        while (true) {
            NetworkEvent event;
            if (queue.try_dequeue(event)) {
                switch (event.EventType) {
                    case EventType::USER_ACTIVITY:
                        visitor.visitUserActivity(event);
                        break;
                    case EventType::SYSTEM_STATUS:
                        visitor.visitSystemStatus(event);
                        break;
                    case EventType::NETWORK_ERROR:
                        visitor.visitNetworkError(event);
                        break;
                    // Add more event types here
                }
            } else {
                break;
            }
        }
    }
};

void initializeDynamicArray(std::vector<NetworkEvent>& events, size_t size) {
    events.resize(size);
    std::generate(events.begin(), events.end(), []() -> NetworkEvent {
        return { std::chrono::steady_clock::now(), EventType::USER_ACTIVITY };
    });
}
