const axios = require('axios');
const cheerio = require('cheerio');
const _ = require('lodash');

async function extractVerses(text, apiKey) {
  const regex = /(\w+ [0-9]+[:][0-9]+)/g;
  let matches = text.match(regex);

  if (!matches) return {};

  const verses = {};
  for (let match of matches) {
    const verseRef = match.toLowerCase().replace(/[^\w ]+/g, ''); // Remove punctuation and special characters
    const [book, chapter, verse] = verseRef.split(' ');

    if (!verses[verseRef]) verses[verseRef] = 0;
    verses[verseRef]++;

    try {
      const response = await axios.get(`https://api.bibleinfo.com/v1/passage/${book}/${chapter}/${verse}`, {
        headers: { 'x-api-key': apiKey }
      });
      if (response.data && response.data.verses) verses[verseRef] += response.data.verses.length;
    } catch (error) {
      console.error(`Error fetching verse ${verseRef}:`, error);
    }
  }

  return verses;
}

function processText(text, apiKey) {
  if (typeof text !== 'string') throw new Error('Input must be a string');

  let cleanText = text;
  if (/\<[^>]*\>/g.test(text)) { // If HTML or Markdown
    const $ = cheerio.load(text);
    cleanText = $.text();
  }

  return extractVerses(cleanText, apiKey);
}
