#include <cstdlib>

struct ENB_ENBIE_T {
    int enb_id;
    std::unique_ptr<ENB_CELL_INFO_T> cell_info;
};

class LteEnbManager {
private:
    std::vector<ENB_ENBIE_T> enbs;
    std::mutex mtx;
    std::map<int, ENB_CELL_INFO_T*> cellInfoCache;

public:
    LteEnbManager() {}

    ~LteEnbManager() {
        for (auto& enb : enbs) {
            delete enb.cell_info.get();
        }
    }

    ENB_ENBIE_T* getOrCreateEnb(int enbId, const ENB_CELL_INFO_T& cellInfo) {
        std::lock_guard<std::mutex> lock(mtx);

        auto it = std::find_if(enbs.begin(), enbs.end(), [enbId](const ENB_ENBIE_T& enb) { return enb.enb_id == enbId; });
        if (it != enbs.end()) {
            // Reuse existing cell info if found
            it->cell_info.reset(new ENB_CELL_INFO_T(*it->cell_info));
            it->cell_info->setPci(cellInfo.getPci());
            it->cell_info->setSrsConfig(cellInfo.getSrsConfig());
            return &*it;
        }

        // Create new ENB if not found
        auto newEnb = std::make_unique<ENB_ENBIE_T>();
        newEnb->enb_id = enbId;
        newEnb->cell_info.reset(new ENB_CELL_INFO_T(cellInfo));
        newEnb->cell_info->setPci(cellInfo.getPci());
        newEnb->cell_info->setSrsConfig(cellInfo.getSrsConfig());
        enbs.push_back(std::move(newEnb));

        return &enbs.back();
    }

    ENB_CELL_INFO_T* getCellInfoFromCache(int enbId, int pci) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = cellInfoCache.find(std::make_pair(enbId, pci));
        if (it != cellInfoCache.end()) {
            return it->second;
        }
        return nullptr;
    }

    void logResourceUsage() {
        std::cout << "ENB count: " << enbs.size() << ", Memory usage: " << enbs.memory_usage() << std::endl;
    }
};
```

