#include <vector>
#include <unordered_map>
#include <memory>
#include <iostream>
#include <stdexcept>
#include <random>
#include <future>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

class StreamAPI {
public:
    virtual std::vector<uint32_t> fetchTags(size_t count) = 0;
    virtual ~StreamAPI() {}
};

class DataContainer {
private:
    std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> data;
    std::unordered_map<uint32_t, size_t> tagToIndex;
    StreamAPI* streamAPI;
    size_t capacity = 10000;

public:
    DataContainer(StreamAPI* api) : streamAPI(api) {}

    NFAPI_CRC_INDICATION_PDU_T& operator[](size_t index) {
        if (index >= data.size()) {
            resize(index + 1);
        }
        return *data[index];
    }

    size_t size() const { return data.size(); }

    void clear() {
        data.clear();
        tagToIndex.clear();
    }

    void resize(size_t newSize) {
        if (newSize > capacity) {
            capacity *= 2;
            reallocate(capacity);
        }
        while (data.size() < newSize) {
            auto tag = fetchTag();
            auto pdu = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>();
            pdu->RX_UE_INFORMATION_TAG = tag;
            pdu->RNTI = ++tagToIndex[tag];
            pdu->CRC_INDICATION_REL8_TAG = rand();
            pdu->CRCFLAG = rand() % 2 == 0;
            data.push_back(std::move(pdu));
        }
    }

    size_t fetchTag() {
        auto tag = streamAPI->fetchTags(1).front();
        if (tagToIndex.find(tag) != tagToIndex.end()) {
            throw std::runtime_error("Duplicate RX_UE_INFORMATION_TAG found");
        }
        tagToIndex[tag] = 0;
        return tag;
    }

    void reallocate(size_t newCapacity) {
        auto oldData = std::move(data);
        data.reserve(newCapacity);
        for (auto& element : oldData) {
            data.push_back(std::move(element));
        }
    }
};
```

