    bool CRCFLAG;
};

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
};

class Registry {
public:
    void registerFactory(uint32_t id, std::function<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>()> factory) {
        factories_[id] = std::move(factory);
    }

    std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> create(uint32_t id) {
        auto it = factories_.find(id);
        if (it == factories_.end())
            throw std::runtime_error("Invalid factory ID");
        return it->second();
    }

private:
    std::map<uint32_t, std::function<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>()> factories_;
};

Registry registry;

void allocateNFapiCrcIndications(std::vector<NFAPI_CRC_INDICATION_PDU_T>& indications, size_t count) {
    if (indications.size() >= count)
        return;

    indications.resize(count);

    std::mt19937 gen(std::random_device{}());
    std::uniform_int_distribution<> dist(0, UINT32_MAX);

    for (size_t i = indications.size(); i > 0; --i) {
        auto& indication = indications[i - 1];
        indication.rx_ue_information_tag.value = dist(gen);
        if (std::find_if(indications.begin(), indications.end(),
                         [&](const NFAPI_CRC_INDICATION_PDU_T& other) {
                             return indication.rx_ue_information_tag.value == other.rx_ue_information_tag.value;
                         }) != indications.end()) {
            --i;
            continue;
        }
        indication.rnti.value = dist(gen);
        indication.crc_indication_rel8_tag.CRCFLAG = dist(gen) % 2 == 0;
    }
}

void printIndication(const NFAPI_CRC_INDICATION_PDU_T& indication, const Registry& registry) {
    auto pdu = registry.create(indication.rnti.value);
    *pdu = indication;
    nlohmann::json json = nlohmann::json::object();
    json["rx_ue_information_tag"] = indication.rx_ue_information_tag.value;
    json["rnti"] = indication.rnti.value;
    json["crc_indication_rel8_tag"]["CRCFLAG"] = indication.crc_indication_rel8_tag.CRCFLAG;
    std::cout << json.dump() << std::endl;
}
