typedef struct TrafficFlow {
    in_addr_t flowID;
    struct in_addr sourceIP;
    struct in_addr destinationIP;
    char *payload;
} TrafficFlow;

void die(const char *msg) {
    perror(msg);
    exit(1);
}

TrafficFlow* initTrafficFlows(int numFlows) {
    TrafficFlow *trafficFlows = malloc(numFlows * sizeof(TrafficFlow));
    if (!trafficFlows) die("Memory allocation failure");

    for (int i = 0; i < numFlows; ++i) {
        trafficFlows[i].flowID = i + 1;
        gettheip(&trafficFlows[i].sourceIP);
        gettheip(&trafficFlows[i].destinationIP);
        trafficFlows[i].payload = malloc(rand() % 901 + 100);
        if (!trafficFlows[i].payload) die("Memory allocation failure");
        memset(trafficFlows[i].payload, rand() & 255, strlen(trafficFlows[i].payload));
    }

    return trafficFlows;
}

void gettheip(struct in_addr *ip) {
    struct hostent *he;
    if (!(he = gethostbyname("localhost"))) die("gethostbyname() failed");
    memcpy(ip, he->h_addr_list[0], sizeof(struct in_addr));
}
