#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <pthread.h>

typedef struct {
    char mac[6];
    char ip[INET_ADDRSTRLEN];
    char netmask[INET_ADDRSTRLEN];
    char gateway[INET_ADDRSTRLEN];
    char* services; // array of service names
} NetworkInterfaceConfigurationEntry;

typedef struct {
    pthread_mutex_t lock;
    NetworkInterfaceConfigurationEntry* entries;
    size_t capacity;
    size_t size;
} NetworkInterfaceConfigManager;

NetworkInterfaceConfigManager* init_network_interface_config_manager(size_t initial_capacity) {
    NetworkInterfaceConfigManager* manager = malloc(sizeof(NetworkInterfaceConfigManager));
    pthread_mutex_init(&manager->lock, NULL);
    manager->entries = calloc(initial_capacity, sizeof(NetworkInterfaceConfigurationEntry));
    manager->capacity = initial_capacity;
    manager->size = 0;
    return manager;
}

void add_network_interface_configuration(NetworkInterfaceConfigManager* manager, const char* mac, const char* ip, const char* netmask, const char* gateway, const char** services) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        manager->capacity *= 2;
        manager->entries = realloc(manager->entries, manager->capacity * sizeof(NetworkInterfaceConfigurationEntry));
    }

    NetworkInterfaceConfigurationEntry* entry = &manager->entries[manager->size];
    memcpy(entry->mac, mac, 6);
    inet_pton(AF_INET, ip, &entry->ip);
    inet_pton(AF_INET, netmask, &entry->netmask);
    inet_pton(AF_INET, gateway, &entry->gateway);
    entry->services = *services;
    manager->size++;
    pthread_mutex_unlock(&manager->lock);
}

