class FramePool {
public:
    FramePool(size_t numFrames, size_t bufferSize)
        : m_numFrames(numFrames), m_bufferSize(bufferSize), m_data(nullptr) {}

    ~FramePool() { clear(); }

    void allocate() {
        if (m_data) return;
        m_data.reset(new NFAPI_RX_FRAME_PDU_T[m_numFrames]);
        std::fill_n(m_data.get(), m_numFrames, NFAPI_RX_FRAME_PDU_T{});
    }

    void deallocate() { clear(); m_data.reset(); }

    void clear() {
        if (!m_data) return;
        std::for_each(m_data.get(), m_data.get() + m_numFrames, [](NFAPI_RX_FRAME_PDU_T& frame) { frame.~NFAPI_RX_FRAME_PDU_T(); });
        m_data.reset();
    }

    void serialize(const std::string& filename) const {
        std::ofstream file(filename, std::ios::binary | std::ios::out);
        boost::archive::text_oarchive oa(file);
        oa & BOOST_SERIALIZATION_NVP("frames", m_data);
    }

    void deserialize(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary | std::ios::in);
        boost::archive::text_iarchive ia(file);
        ia & BOOST_SERIALIZATION_NVP("frames", m_data);
    }

    NFAPI_RX_FRAME_PDU_T* get() {
        if (!m_data) allocate();
        auto it = std::find_if(m_data.begin(), m_data.end(), [](const NFAPI_RX_FRAME_PDU_T& frame) { return !frame; });
        if (it == m_data.end()) {
