            it->set_allocator(std::allocator<char>{});
        }
        new (it) NFAPI_RX_FRAME_PDU_T();
        return &*it;
    }

private:
    size_t m_numFrames;
    size_t m_bufferSize;
    std::vector<NFAPI_RX_FRAME_PDU_T, std::allocator_traits<std::allocator<NFAPI_RX_FRAME_PDU_T>>::rebind<char>::other> m_data;
};
