int num_nodes = 0;

void add_node(NFAPI_CRC_INDICATION_PDU_T data, RNTI rnti, CRC_INDICATION_REL8_TAG tag) {
    if (num_nodes >= MAX_NODES) return;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data.rx_ue_information_tag = data.rx_ue_information_tag;
    new_node->data.rnti = rnti;
    new_node->data.crc_indication_rel8_tag = tag;
    new_node->data.crcflag = rand() % 256;
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    if (*tail) {
        (*tail)->next = new_node;
        *tail = &new_node->next;
    } else {
        *tail = new_node;
    }

    num_nodes++;
}

void remove_old_nodes() {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        if (difftime(time(NULL), current->timestamp) > 5 * 60) {
            free(current);
            current = next;
            num_nodes--;
            if (!next) *tail = NULL;
        } else {
            current = next;
        }
    }
}
