```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    struct _NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _CircularBuffer {
    NFAPI_CRUC_INDICATION_PDU_T* buffer;
    size_t capacity;
    size_t head;
    size_t tail;
    pthread_mutex_t lock;
} CircularBuffer;

void init_circular_buffer(CircularBuffer* cb, size_t capacity) {
    cb->capacity = capacity;
    cb->head = 0;
    cb->tail = 0;
    cb->buffer = (NFAPI_CRUC_INDICATION_PDU_T*)malloc(cb->capacity * sizeof(NFAPI_CRUC_INDICATION_PDU_T));
    if (!cb->buffer) {
        fprintf(stderr, "Failed to allocate buffer\n");
        exit(EXIT_FAILURE);
    }
    cb->buffer[0].next = &cb->buffer[1];
    cb->buffer[cb->capacity - 1].next = &cb->buffer[0];
    pthread_mutex_init(&cb->lock, NULL);
}

void destroy_circular_buffer(CircularBuffer* cb) {
    free(cb->buffer);
    pthread_mutex_destroy(&cb->lock);
}

NFAPI_CRUC_INDICATION_PDU_T* get_next(CircularBuffer* cb, size_t index) {
    return cb->buffer[(cb->head + index) % cb->capacity];
}

void add_pdu(CircularBuffer* cb, RX_UE_INFORMATION_TAG tag, unsigned int rnti, CRC_INDICATION_REL8_TAG crc_indication) {
    pthread_mutex_lock(&cb->lock);
    NFAPI_CRUC_INDICATION_PDU_T* current = get_next(cb, cb->tail);
    while (current->rnti != 0) {
        current = get_next(cb, ++cb->tail % cb->capacity);
    }
    current->rnti = rnti;
    current->tag = tag;
    current->crc_indication = crc_indication;
    current->next = get_next(cb, ++cb->tail % cb->capacity);
    pthread_mutex_unlock(&cb->lock);
}

void log_allocation_failure() {
    time_t now;
    char buffer[80];
    time(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "[%s] Allocation failure\n", buffer);
}

NFAPI_CRUC_INDICATION_PDU_T* allocate_pdu() {
    NFAPI_CRUC_INDICATION_PDU_T* pdu = (NFAPI_CRUC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRUC_INDICATION_PDU_T));
    if (!pdu) {
        log_allocation_failure();
        return NULL;
    }
    return pdu;
}

void free_pdu(NFAPI_CRUC_INDICATION_PDU_T* pdu) {
    free(pdu);
}
