};

class PduList {
public:
    PduList(size_t maxPdus) : buffer_(maxPdus), head_(0), tail_(0), maxPdus_(maxPdus), allocator_(), freeList_() {}

    void addPdu(const NFAPI_CRC_INDICATION_PDU_T& pdu, uint16_t rnti) {
        if (rnti < 1 || rnti > 65535) {
            logError("Invalid RNTI: " + std::to_string(rnti));
            throw std::invalid_argument("Invalid RNTI");
        }

        for (size_t i = 0; i < buffer_.size(); ++i) {
            if (buffer_[i].rnti == rnti) {
                logError("RNTI already exists: " + std::to_string(rnti));
                throw std::runtime_error("RNTI already exists");
            }
        }

        auto pduIt = std::find_if(buffer_.begin(), buffer_.end(), [rnti](const NFAPI_CRC_INDICATION_PDU_T& p) { return p.rnti == 0; });
        if (pduIt != buffer_.end()) {
            *pduIt = pdu;
            pduIt->rnti = rnti;
            ++tail_;
            if (tail_ >= maxPdus_) tail_ = 0;
            return;
        }

        // Allocate a new PDU from the free list or create a new one if necessary.
        if (!freeList_.empty()) {
            auto pduIt = freeList_.pop_front();
            *pduIt = pdu;
            pduIt->rnti = rnti;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* newPdu = allocator_.allocate(1);
            new (newPdu) NFAPI_CRC_INDICATION_PDU_T(pdu);
            newPdu->rnti = rnti;
            buffer_[head_] = *newPdu;
            ++head_;
            if (head_ >= maxPdus_) head_ = 0;
        }
        ++numPdus_;
    }

    void logError(const std::string& message) {
        std::ofstream logFile("error.log", std::ios_base::app);
        logFile << "[" << std::chrono::system_clock::now().time_since_epoch().count() << "] " << message << "\n";
    }

private:
    boost::circular_buffer<NFAPI_CRC_INDICATION_PDU_T> buffer_;
    boost::atomic<size_t> head_, tail_, maxPdus_;
    std::allocator<NFAPI_CRC_INDICATION_PDU_T> allocator_;
    boost::lockfree::slist<NFAPI_CRC_INDICATION_PDU_T*> freeList_;
    size_t numPdus_ = 0;
};
```

