class MemoryPool {
public:
    MemoryPool(size_t blockSize, size_t numBlocks) : _numAllocated(0), _freeList(), _blockSize(blockSize), _numBlocks(numBlocks) {
        _memory.resize(_numBlocks * _blockSize);
        for (size_t i = 0; i < _numBlocks; ++i) {
            _freeList.push_back({static_cast<char*>(_memory.data() + i * _blockSize), static_cast<char*>(_memory.data() + (_i + 1) * _blockSize)});
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* allocate() {
        std::lock_guard<std::mutex> lock(_mutex);
        if (_freeList.empty()) {
            throw std::runtime_error("Memory pool is empty");
        }

        auto it = _freeList.begin();
        _numAllocated++;
        return new (it->first) NFAPI_CRC_INDICATION_PDU_T;
    }

    void free(NFAPI_CRC_INDICATION_PDU_T* pdu) {
        std::lock_guard<std::mutex> lock(_mutex);
        pdu->~NFAPI_CRC_INDICATION_PDU_T();
        auto it = std::find(_freeList.begin(), _freeList.end(), *it);
        if (it == _freeList.end()) {
            _freeList.push_back({static_cast<char*>(const_cast<void*>(pdu)), nullptr});
        }
        _numAllocated--;
    }

private:
    std::vector<std::pair<char*, char*>> _freeList;
    std::vector<char> _memory;
    size_t _blockSize;
    size_t _numBlocks;
    std::mutex _mutex;
    std::atomic<size_t> _numAllocated;
};

