        NFAPI_CRC_INDICATION_PDU_T* pdu = pool.allocate();
        list.push_back(pdu);
    }
    auto end = std::chrono::high_resolution_clock::now();
    log(std::string("Created ") + std::to_string(numElements) + " elements in " + std::to_string(std::chrono::duration<double>(end - start).count()) + " ms", 2);

