    uint32_t crc_indication_rel8_tag;
    uint32_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

struct MemoryPool {
    size_t capacity;
    size_t allocated;
    Node* head;
    sem_t lock;
};

void init_memory_pool(struct MemoryPool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->allocated = 0;
    pool->head = NULL;
    sem_init(&pool->lock, 0, 1);
}

Node* acquire_node(struct MemoryPool* pool) {
    sem_wait(&pool->lock);
    Node* node = pool->head;
    if (node != NULL) {
        pool->head = node->next;
        pool->allocated--;
    } else {
        if (pool->allocated < pool->capacity) {
            pool->allocated++;
            node = malloc(sizeof(Node));
            if (!node) {
                fprintf(stderr, "Out of memory\n");
                exit(EXIT_FAILURE);
            }
        } else {
            node = expand_pool(pool);
        }
    }
    sem_post(&pool->lock);
    return node;
}

void release_node(struct MemoryPool* pool, Node* node) {
    sem_wait(&pool->lock);
    node->next = pool->head;
    pool->head = node;
    pool->allocated++;
    sem_post(&pool->lock);
}

void log(const char* message, int severity) {
    // Implement logging with customizable severity levels and export functionality.
}

void create_list(struct MemoryPool* pool, size_t count, NFAPI_CRC_INDICATION_PDU_T* test_data) {
    clock_t start = clock();
    for (size_t i = 0; i < count; i++) {
        Node* node = acquire_node(pool);
        if (!test_data) {
            node->data.rx_ue_information_tag = rand();
            node->data.rnti = rand();
            node->data.crc_indication_rel8_tag = rand();
            node->data.crcflag = rand() % 2;
        } else {
            node->data = test_data[i];
        }
    }
    clock_t end = clock();
    log(asctime(localtime(&end)) - 1, LOG_INFO);
    log(asprintf("Created %zu structures in %.6f ms", count, (double)(end - start) / CLOCKS_PER_SEC), LOG_INFO);
}
```

