#include <iostream>
#include <cstdlib>
#include <cstring>

const size_t MAX_PACKET_SIZE = 1024;
const size_t INITIAL_BUFFER_SIZE = 10000;

class UDPPacket {
public:
    UDPPacket(size_t sequenceNumber, char* payload, size_t payloadSize) :
        sequenceNumber_(sequenceNumber), payload_(payload), payloadSize_(payloadSize) {}

    size_t getSequenceNumber() const { return sequenceNumber_; }
    char* getPayload() const { return payload_; }
    size_t getPayloadSize() const { return payloadSize_; }

private:
    size_t sequenceNumber_;
    char* payload_;
    size_t payloadSize_;
};

std::mutex packetsMutex;
std::vector<std::unique_ptr<UDPPacket>> packets;

void addPacket(size_t sequenceNumber, char* payload, size_t payloadSize) {
    std::lock_guard<std::mutex> lock(packetsMutex);

    if (packets.size() == packets.capacity()) {
        packets.resize(packets.capacity() * 2);
    }

    auto packet = std::make_unique<UDPPacket>(sequenceNumber, payload, payloadSize);
    packets.push_back(std::move(packet));
}

UDPPacket* findPacketBySequenceNumber(size_t sequenceNumber) {
    std::lock_guard<std::mutex> lock(packetsMutex);

    for (auto& packet : packets) {
        if (packet->getSequenceNumber() == sequenceNumber) {
            return packet.get();
        }
    }

    return nullptr;
}
```

This example provides a basic implementation of a thread-safe dynamic list of UDP packets. The `addPacket` function adds new packets to the list, ensuring that it doesn't exceed its capacity and handles memory allocation failures gracefully using std::unique_ptr. The `findPacketBySequenceNumber` function searches for a packet with a specific sequence number.

