[' To address this task, I'll propose a solution using an unordered_map (C++11) for storing the `NetworkNode` objects, along with a custom synchronization mechanism based on a spinlock to ensure thread safety. The data structure is chosen for its efficient access performance and dynamic resizing capabilities.

Here's a simplified implementation of the NetworkManager class:

```cpp
#include <unordered_map>
#include <mutex>
#include <chrono>
#include <string>

struct NetworkNode {
    int NodeId;
    std::string IpAddress;
    std::int64_t LastSeenTimestamp;
};

class NetworkManager {
private:
    std::unordered_map<std::string, NetworkNode> nodes;
    std::mutex mtx;

public:
    void addNode(const std::string& segment, const NetworkNode& node) {
        std::lock_guard<std::mutex> lock(mtx);
        if (nodes.find(segment) == nodes.end()) {
            nodes[segment] = node;
        } else {
            while (nodes[segment].IpAddress == node.IpAddress) {} // Spin until unique IP address found
            nodes[segment] = node;
        }
    }

    void updateLastSeen(const std::string& segment, const NetworkNode& node) {
        std::lock_guard<std::mutex> lock(mtx);
        if (nodes.find(segment) != nodes.end()) {
            nodes[segment].LastSeenTimestamp = std::chrono::duration_cast<std::int64_t>(std::chrono::system_clock::now().time_since_epoch()).count();
        }
    }

    void updateBatch(const std::string& segment, const std::vector<NetworkNode>& nodes) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = nodes.begin();
        for (; it != nodes.end(); ++it) {
            if (it->IpAddress == nodes[segment].IpAddress) continue; // Skip if IP address already exists in the segment
            nodes[segment] = *it;
        }
    }

