        dataList.push_back(data);
        rntiMap[data.rnti] = dataList.size() - 1;
        currentSize++;
    }

    NFAPI_CRC_INDICATION_PDU_T getData(int rnti) {
        std::unique_lock<std::mutex> lock(listMutex);

        auto it = rntiMap.find(rnti);
        if (it == rntiMap.end) {
            throw std::runtime_error("RNTI not found in the list.");
        }

        auto index = it->second;
        NFAPI_CRC_INDICATION_PDU_T data = dataList[index];
        dataList.erase(dataList.begin() + index);
        rntiMap.erase(it);
        currentSize--;
        lock.unlock();

        return data;
    }
};
```

