#include <pthread.h>
#include <stdbool.h>

typedef void (*task_func)(void*);
struct task {
    task_func func;
    void* args;
    bool running;
};

struct task_queue {
    struct task* head;
    struct task* tail;
    pthread_mutex_t lock;
    pthread_cond_t cond;
};

void enqueue(struct task_queue* q, task_func func, void* args) {
    struct task* t = malloc(sizeof(struct task));
    t->func = func;
    t->args = args;
    t->running = false;

    pthread_mutex_lock(&q->lock);
    if (q->head == NULL) {
        q->head = t;
        q->tail = t;
    } else {
        q->tail->next = t;
        q->tail = t;
    }
    pthread_mutex_unlock(&q->lock);
    pthread_cond_signal(&q->cond);
}
```"]

