using boost::asio::ip::tcp;

struct ConnectionRecord {
    tcp::socket socket;
    tcp::endpoint remote_addr;
    tcp::endpoint local_addr;
    enum class State { NEW, ESTABLISHED, CLOSED } state;
    boost::posix_time::ptime last_activity;
};

std::vector<ConnectionRecord> connections;
std::mutex connections_mutex;
unsigned int timeout_seconds = 60; // default timeout is 1 minute

void check_idle_connections() {
    std::lock_guard<std::mutex> lock(connections_mutex);
    auto now = boost::posix_time::second_clock::local_time();
    connections.erase(
        std::remove_if(connections.begin(), connections.end(),
            [&](const ConnectionRecord &conn) {
                return (conn.state != ConnectionRecord::State::ESTABLISHED ||
                        now - conn.last_activity > boost::posix_time::seconds(timeout_seconds));
            }),
        connections.end()
    );
}

void add_connection(tcp::socket socket, tcp::endpoint remote_addr, tcp::endpoint local_addr) {
    ConnectionRecord new_conn{ std::move(socket), std::move(remote_addr), std::move(local_addr), ConnectionRecord::State::NEW, boost::posix_time::second_clock::local_time() };
    {
        std::lock_guard<std::mutex> lock(connections_mutex);
        connections.push_back(new_conn);
    }
}

void update_connection(ConnectionRecord &conn) {
    conn.last_activity = boost::posix_time::second_clock::local_time();
}

