[' Here is a simplified C++ code example that addresses some of the requirements mentioned. Note that this is a basic implementation and may need further optimization for real-world usage.

```cpp
#include <vector>
#include <unordered_map>
#include <mutex>
#include <chrono>
#include <thread>
#include <iostream>

struct UEContext {
    int ueId;
    std::vector<double> srsParams;
    int tac;
};

class LTEUEContextManager {
private:
    std::vector<UEContext> contexts;
    std::unordered_map<int, int> idToIndex;
    std::mutex mtx;
    size_t bufferSize = 1024; // Adjustable buffer size
    size_t purgeIntervalMs = 60000; // Purge interval in milliseconds

public:
    LTEUEContextManager() {
        std::thread purger(std::bind(&LTEUEContextManager::purgeInactive, this));
        purger.detach();
    }

    void addUEContext(const UEContext& context) {
        std::lock_guard<std::mutex> lock(mtx);
        if (contexts.size() >= bufferSize) {
            auto it = idToIndex.begin();
            advance(it, bufferSize / 2); // Remove half of the oldest contexts
            contexts.erase(it, idToIndex.end());
            idToIndex.erase(it, idToIndex.end());
        }
        contexts.push_back(context);
        idToIndex[context.ueId] = contexts.size() - 1;
    }

    UEContext getUEContextById(int ueId) const {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = idToIndex.find(ueId);
        if (it == idToIndex.end()) {
            throw std::runtime_error("UE Context not found");
        }
        return contexts[it->second];
    }

    void purgeInactive() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::milliseconds(purgeIntervalMs));
            std::lock_guard<std::mutex> lock(mtx);
            auto it = contexts.begin();
            for (; it != contexts.end(); ) {
                if (!it->srsParams.empty() && it->tac > 0) { // Adjust criteria based on actual usage
                    ++it;
                } else {
                    it = contexts.erase(it);
                }
            }
        }
    }
};
```

