struct RNTI_CACHE {
    std::map<uint16_t, bool> cache;
    pthread_mutex_t mutex;
};

struct RX_UE_INFORMATION_TAG {
    uint16_t rnti;
    // ... other fields ...
};

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    bool crc_indication_rel8_tag;
