void* generate_ue_instance(void* arg) {
    pthread_mutex_lock(&rnti_cache.mutex);
    uint16_t rnti = next_rnti++;
    if (rnti_cache.cache.find(rnti) != rnti_cache.cache.end()) {
        pthread_mutex_unlock(&rnti_cache.mutex);
        return nullptr;
    }
    rnti_cache.cache[rnti] = true;
    pthread_mutex_unlock(&rnti_cache.mutex);

    NFAPI_CRC_INDICATION_PDU_T ue_instance;
    ue_instance.rx_ue_information_tag.rnti = rnti;
    ue_instance.crc_indication_rel8_tag = rand() % 2;

    ue_instances.push_back(ue_instance);
    return &ue_instances.back();
}

NFAPI_CRC_INDICATION_PDU_T* create_ue_instance(uint32_t N) {
    if (N > ue_instances.size()) {
        std::vector<NFAPI_CRC_INDICATION_PDU_T> new_ue_instances(N);
        for (auto& instance : new_ue_instances) {
            instance = *generate_ue_instance(nullptr);
            if (!instance) return nullptr;
        }
        ue_instances.swap(new_ue_instances);
    }

    auto it = ue_instances.end() - N;
    return &*it;
}
