    EVP_KDF_derivation(&ctx, prk, AES_BLOCK_SIZE);
    memcpy(pdu->key, prk, AES_KEYSIZE_256);

    memset(pdu->iv, 0, AES_BLOCK_SIZE);

    pdu->indication.cicr[0] = rand() % 2;
}

void parse_png(const char *path, unsigned char **data, size_t *size) {
