    png_read_info(png_ptr, info_ptr);
    png_get_IHDR(png_ptr, info_ptr, &bit_depth, &color_type, NULL, NULL, NULL, NULL, NULL);

    *size = png_get_image_length(png_ptr, info_ptr) * png_get_bytes_per_pixel(png_ptr, info_ptr);
    *data = malloc(*size);
    png_read_image(png_ptr, *data);
    fclose(fp);
    png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
}

const char *default_theme_dir = "themes/default";
