```cpp
#include <iostream>
#include <vector>
#include <unordered_set>
#include <random>
#include <chrono>
#include <cstdint>
#include <memory>

struct SensorReading {
    double temperature;
    double humidity;
};

struct NetworkEvent {
    uint64_t eventTag;
    std::uint64_t timestamp;
    std::vector<SensorReading> sensorReadings;
};

std::unordered_set<uint64_t> usedEventTags;

std::unique_ptr<NetworkEvent[]> initializeEvents(size_t size, int sensorType) {
    std::unique_ptr<NetworkEvent[]> events(new NetworkEvent[size]);

    std::default_random_engine generator;
    std::uniform_int_distribution<> distribution(0, std::numeric_limits<uint64_t>::max());

    for (size_t i = 0; i < size; ++i) {
        uint64_t eventTag;
        do {
            eventTag = distribution(generator);
        } while (usedEventTags.find(eventTag) != usedEventTags.end());

        usedEventTags.insert(eventTag);
        events[i].eventTag = eventTag;
        events[i].timestamp = std::chrono::duration_cast<std::uint64_t>(std::chrono::system_clock::now().time_since_epoch()).count();

        switch (sensorType) {
            case 0: // Temperature-only readings
                events[i].sensorReadings.emplace_back(SensorReading{distribution(generator), 0});
                break;
            case 1: // Humidity-only readings
                events[i].sensorReadings.emplace_back(SensorReading{0, distribution(generator)});
                break;
            case 2: // Full readings
                events[i].sensorReadings.emplace_back(SensorReading{distribution(generator), distribution(generator)});
                break;
            default:
                std::cerr << "Invalid sensor type provided." << std::endl;
        }
    }

    return events;
}

void logDiscrepancies(const std::unordered_set<uint64_t>& usedEventTags) {
    if (!usedEventTags.size() == usedEventTags.count()) {
        std::cerr << "Duplicate event tags detected:" << std::endl;
        for (auto it = usedEventTags.begin(); it != usedEventTags.end(); ++it) {
            auto secondIt = std::find(it + 1, usedEventTags.end(), *it);
            if (secondIt != usedEventTags.end()) {
                std::cerr << *it << " and " << *secondIt << " are duplicates." << std::endl;
            }
        }
    }
}
```

