void parse_args(int argc, char* argv[], forward_list<string>& input_file, Config& config) {
    map<string, int> options = {{ "--help", 1 }, { "-c", 2 }, { "-o", 3 }};
    string api_config_key = "api";

    forward_list<string> args;
    for (int i = 1; i < argc; ++i) {
        istringstream iss(argv[i]);
        string arg;
        if (!(iss >> arg)) break;
        args.push_front(move(arg));
    }

    forward_list<string> parsed_args;
    for (auto it = args.begin(); it != args.end(); ++it) {
        auto found = options.find(*it);
        if (found != options.end()) {
            parsed_args.push_front(move(*it));
            if (++found->second >= argc) {
                throw runtime_error("Missing argument for option: " + *it);
            }
            parsed_args.push_front(argv[found->second]);
        } else if (*it == api_config_key) {
            if (++it == args.end()) {
                throw runtime_error("Missing argument for option: " + api_config_key);
            }
            config.api_url = *it;
        } else {
            if (input_file.empty()) {
                input_file = move(args);
            } else {
                throw runtime_error("Invalid option: " + *it);
            }
        }
    }
}

void insert_after(forward_list<string>& lines, const string& target, const string& insert) {
    auto it = lines.begin();
    if (it != lines.end() && *it == target) {
        forward_list<string> new_lines(++it);
        new_lines.splice_after(new_lines.begin(), lines, it);
        new_lines.push_front(insert);
        lines.splice(it, new_lines);
    } else {
        lines.push_back(insert);
    }
}

void read_input(forward_list<string>& lines, ifstream& file) {
    string line;
    while (getline(file, line)) {
        lines.push_back(move(line));
    }
}

