    Config config;
    try {
        parse_args(argc, argv, input_file, config);
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        cout << "Usage: " << argv[0] << " [--help|-c <output_file>|-o <output_file>] [input_file]\n";
        return 1;
    }

    ifstream file(input_file.front());
    if (!file) {
        cerr << "Error: Could not open input file: " << input_file.front() << endl;
        return 1;
