static pthread_spinlock_t lock = PTHREAD_SPINLOCK_INITIALIZER;

void generate_unique_tag(uint16_t* tag) {
    uint32_t index = 0;
    do {
        *tag = (uint16_t)(index = (index + 1) % HASH_MODULO);
    } while (test_and_set_bit(index, bitset));

    set_bit(index, bitset);
}

void init_pdus() {
    pthread_spin_lock(&lock);

    for (size_t i = 0; i < MAX_NUM_PDUS; ++i) {
        generate_unique_tag(&pdu_array[i].rx_ue_information_tag);
        pdu_array[i].rnti = i + 1; // Assuming RNTI is a simple incrementing sequence
        pdu_array[i].crc_indication_rel8_tag = rand();
    }

    pthread_spin_unlock(&lock);
}
