void init_pool(struct pool* pool, size_t capacity) {
    pool->data = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->capacity = capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* acquire(struct pool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size < pool->capacity) {
        ++pool->size;
        return &pool->data[pool->size - 1];
    }
    pthread_mutex_unlock(&pool->lock);
    fprintf(stderr, "No available elements in the pool\n");
    exit(EXIT_FAILURE);
}

void release(struct pool* pool, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&pool->lock);
    if (element >= pool->data && element < pool->data + pool->size) {
        --pool->size;
    } else {
        fprintf(stderr, "Invalid element in the pool\n");
        exit(EXIT_FAILURE);
