    if (!data) {
        fprintf(stderr, "Memory allocation failed. Exiting...\n");
        exit(EXIT_FAILURE);
    }
}

void populateArray() {
    for (int i = 0; i < arraySize; ++i) {
        data[i].RX_UE_INFORMATION_TAG = i * 2 + rand() % 5;
        if (data[i].RX_UE_INFORMATION_TAG >= TAG_LIMIT) {
            fprintf(stderr, "Generated RX_UE_INFORMATION_TAG exceeded the limit. Exiting...\n");
            exit(EXIT_FAILURE);
        }
    }
}

void generateCRCFlags() {
