        data[i].RNTI = rand() % MAX_RNTI + 1;
        uint32_t seed = data[i].RNTI * 31 + time(NULL);
        for (int j = 0; j < 4; ++j) {
            data[i].CRC_INDICATION_REL8_TAG[j] = seed % 256;
            seed /= 256;
        }
    }
}

uint32_t getArraySize() {
    return arraySize;
}

void freeArray() {
    if (data) {
        free(data);
        data = NULL;
        arraySize = 0;
    }
}

void resizeArray(int M) {
    NFAPI_CRC_INDICATION_PDU_T* tempData = calloc(M, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!tempData) {
        fprintf(stderr, "Memory allocation failed. Exiting...\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < arraySize && i < M; ++i) {
        tempData[i] = data[i];
    }

    free(data);
    data = tempData;
    arraySize = M;
}
```

