function authenticateUser($clientId, $clientSecret, $redirectUri, $code) {
    // Initialize OAuth 2.0 client with your access token and refresh token
    $oauthClient = new \League\OAuth2\Client\Provider\GenericProvider([
        'clientId' => $clientId,
        'clientSecret' => $clientSecret,
        'redirectUri' => $redirectUri,
    ]);

    try {
        $accessTokenResponse = $oauthClient->getAccessToken('authorization_code', [
            'code' => $code,
        ]);

        // Store the access token in a session variable
        $_SESSION['access_token'] = $accessTokenResponse->getAccessToken();

        // Retrieve user information using the access token
        $userInfo = $oauthClient->getResourceOwner($accessTokenResponse->getAccessToken());

        return $userInfo;
    } catch (\Exception $e) {
        // Handle authentication failures gracefully
        echo "Error: " . $e->getMessage();
        return false;
    }
}
