void generateNfareMD5Hashes(int N, std::vector<uint8_t>* hashes, std::vector<NFAPI_CRC_INDICATION_PDU_T>* pduList, int numThreads, double timeout, int retryCount) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, nullptr);

    std::vector<DataRetrievalParams> params(numThreads);
    for (int i = 0; i < numThreads; ++i) {
        params[i].index = i;
        params[i].pduList = pduList;
        params[i].mutex = &mutex;
    }

    std::vector<pthread_t> threads(numThreads);
    for (int i = 0; i < numThreads; ++i) {
