        memcpy(buffer, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        MD5_Digest(buffer, sizeof(buffer), digest);
        hashes->push_back(std::vector<uint8_t>(digest, digest + MD5_DIGEST_LENGTH));
    }

    // Clean up and log any data retrieval failures
    int failureCount = 0;
    for (const auto& pdu : *pduList) {
