            return std::hash<NetworkElementID>()(state.id);
        }
    };
};

std::unordered_map<NetworkElementID, NetworkElementState, NetworkElementState::NetworkElementHash> networkElements;
std::mutex networkElementsMutex;

void addNetworkElement(const NetworkElementState& newElement) {
    std::lock_guard<std::mutex> lock(networkElementsMutex);

    if (networkElements.find(newElement.id) != networkElements.end()) {
        std::cerr << "Error: Duplicate NetworkElementID detected: " << newElement.id << "\n";
        return;
    }

    if (networkElements.count(newElement.ip + ":" + std::to_string(newElement.port)) > 1) {
        std::cerr << "Error: Duplicate IP and port combination detected: " << newElement.ip << ":" << newElement.port << "\n";
        return;
    }

    networkElements[newElement.id] = newElement;
}

void updateNetworkElement(const NetworkElementID& id, const NetworkElementState& updatedElement) {
    std::lock_guard<std::mutex> lock(networkElementsMutex);

    auto it = networkElements.find(id);
    if (it == networkElements.end()) {
        std::cerr << "Error: NetworkElementID not found: " << id << "\n";
        return;
    }

    it->second = updatedElement;
}

NetworkElementState getNetworkElement(const NetworkElementID& id) {
    std::lock_guard<std::mutex> lock(networkElementsMutex);

    auto it = networkElements.find(id);
    if (it == networkElements.end()) {
        NetworkElementState empty;
        empty.is_online = false;
        return empty;
    }

    return it->second;
}
