                    }
                }

                int exitValue = process.waitFor();
                if (exitValue != 0) {
                    System.err.println("Command exited with non-zero status code: " + exitValue);
                }
            } catch (IOException | InterruptedException e) {
                System.err.println("Error executing command: " + e.getMessage());
            } finally {
                process.destroy();
            }
        }
    }
}
