#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} record;

typedef struct {
    size_t index;
    long offset;
} lookup;

void* generate_lookup(void *arg) {
    record *records = (record *) arg;
    size_t num_records = *(size_t*)((char*)arg + sizeof(record*));
    pthread_t self = pthread_self();

    // Generate a unique random index within the range of records
    size_t index;
    do {
        index = rand() % num_records;
    } while (indexes[index] != -1);

    record r = records[index];
    lookup *lookups = (lookup*)realloc(lookups, sizeof(lookup) * (num_lookups + 1));
    lookups[num_lookups].index = index;
    lookups[num_lookups].offset = r.offset;
    num_lookups++;

    // Mark the index as used in the records array
    indexes[index] = num_lookups;

    pthread_exit(NULL);
}

int init_dataset(size_t num_records, size_t num_lookups, long min_key, long max_key, long *offsets, lookup **lookups) {
    record *records = NULL;
    size_t *indexes = calloc(num_records, sizeof(size_t));

    if (!records || !indexes) {
        free(indexes);
        return -1;
    }

    posix_memalign((void**)&records, 64, num_records * sizeof(record));

    // Initialize records with random keys and offsets
    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        records[i].offset = offsets[i];
        indexes[i] = -1; // Mark all indices as unused initially
    }

    pthread_t threads[num_threads];
    lookup *local_lookups = calloc(num_lookups, sizeof(lookup));
    *lookups = local_lookups;

    size_t num_threads = (num_records > NUM_THREADS) ? NUM_THREADS : (size_t)num_records;
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, generate_lookup, &records);
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(indexes);
    free(local_lookups);

    return 0;
}

// Frees all allocated memory and sets the lookups to NULL
void free_dataset(lookup **lookups) {
    free(*lookups);
    *lookups = NULL;
}
```

This code assumes that `NUM_THREADS` is defined as a constant, and you have provided an array of offsets for each record. The function uses the C11 standard features like `posix_memalign`, `pthread_t`, and `pthread_create/join`."]

[' Here is a simplified version of the requested C function using pthreads and a custom memory pool allocator for optimal memory usage. The function leverages a thread-safe hash table (using pthread_hash_table) for rapid RNTI lookups and manages a dynamic array of `NFAPI_CRC_INDICATION_PDU_T` structures.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <pthread_hash_table.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom memory pool allocator
typedef struct mem_block {
    size_t size;
    struct mem_block *next;
    char data[1];
} MemBlock;

MemBlock* mem_pool = NULL;
size_t mem_pool_capacity = 0;
size_t mem_pool_allocated = 0;

void* mem_pool_alloc(size_t size) {
    if (mem_pool_capacity <= mem_pool_allocated + size) {
        MemBlock *new_block = malloc(sizeof(MemBlock) + size);
        new_block->size = size;
        new_block->next = mem_pool;
        mem_pool = new_block;
        mem_pool_capacity += size;
    }
    MemBlock *current = mem_pool;
    while (current->next && current->next->size >= size) {
        current = current->next;
    }
    void* result = current->data;
    current->data += size;
    current->size -= size;
    return result;
}

pthread_hash_table_t rnti_ht;

void init_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t* array_len) {
    *array = (NFAPI_CRC_INDICATION_PDU_T*)mem_pool_alloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10000);
    *array_len = 0;

    pthread_hash_table_init(&rnti_ht, sizeof(uint32_t), NULL, NULL, NULL);
}

void free_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t array_len) {
    for (size_t i = 0; i < array_len; ++i) {
        pthread_hash_table_remove(&rnti_ht, &array[i].rnti);
    }
    free(array);
}

void add_element(NFAPI_CRC_INDICATION_PDU_T* array, size_t* array_len, RX_UE_INFORMATION_TAG tag, uint32_t rnti, CRC_INDICATION_REL8_TAG crc_indication_tag) {
    while (1) {
        rnti++;
        if (!pthread_hash_table_contains(&rnti_ht, &rnti)) {
            array[*array_len].tag = tag;
            array[*array_len].rnti = rnti;
            array[*array_len].crc_indication_tag = crc_indication_tag;
            array[*array_len++].crcflag = rand() % 2;
            pthread_hash_table_insert(&rnti_ht, &rnti, &array[*array_len - 1]);
            break;
        }
    }
}

void update_status(NFAPI_CRC_INDICATION_PDU_T* array, size_t array_len, uint32_t rnti, uint8_t new_crcflag) {
    for (size_t i = 0; i < array_len; ++i) {
        if (array[i].rnti == rnti) {
            array[i].crcflag = new_crcflag;
            break;
        }
    }
}
```

