class DynamicArrayManager {
public:
    DynamicArrayManager(int maxSize, std::vector<uint32_t> validRNTIRange)
        : maxSize_(maxSize), validRNTIs_(std::move(validRNTIRange)) {}

    std::vector<NFAPI_CRC_INDICATION_PDU_T> processBatch(
        const std::initializer_list<NFAPI_CRC_INDICATION_PDU_T>& structures) {
        std::vector<NFAPI_CRC_INDICATION_PDU_T> result;
        std::mt19937 rng(std::chrono::system_clock::now().time_since_epoch().count());
        for (const auto& structure : structures) {
            if (structure.sequence_number <= 0 || structure.sequence_number > maxSize_) {
                throw std::invalid_argument("Sequence number out of bounds");
            }

            if (structuresWithSameRNTI_.find(structure.rnti) != structuresWithSameRNTI_.end()) {
                throw std::invalid_argument("Duplicate RNTI found");
            }

            if (structure.rnti < validRNTIs_.front() || structure.rnti > validRNTIs_.back()) {
                throw std::invalid_argument("Invalid RNTI value");
