    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t theme_mutex = PTHREAD_MUTEX_INITIALIZER;
static char* theme_dir = "./themes";

void create_theme_dir(const char* path) {
    struct stat st;
    if (stat(path, &st) != 0) {
        mkdir(path, 0755);
    }
}

Line* read_line(FILE* file) {
    Line* line = malloc(sizeof(Line));
    size_t len = 0;
    char c;

    while ((c = fgetc(file)) != EOF && c != '\n') {
        line->line = realloc(line->line, ++len);
        line->line[len - 1] = c;
    }

    if (c == '\n') {
        line->line = realloc(line->line, len);
        line->len = len;
        line->line[len] = '\0';
    }

    return line;
}

void parse_and_print(Line* line) {
    char** fields = NULL;
    char delimiter[] = ",";
    char* token = strtok(line->line, delimiter);
    size_t field_count = 0;

    while (token != NULL) {
        if (field_count >= 2) {
            double num1 = atof(fields[field_count - 2]);
            double num2 = atof(token);
            printf("%.6f\n", (num1 + num2) / 2);
        }

        if (field_count == 0) {
            fields = realloc(fields, ++field_count * sizeof(char*));
            fields[field_count - 1] = strdup(token);
        } else {
            fields = realloc(fields, ++field_count * sizeof(char*));
            fields[field_count - 1] = NULL;
            token = strtok(NULL, delimiter);
            if (token != NULL) {
                fields[field_count - 2] = strdup(token);
            }
        }
    }

    free(line->line);
    free(line);
    free(fields);
}

void* process_file(void* arg) {
    FILE* file = (FILE*)arg;
    Line* line;

    while ((line = read_line(file)) != NULL) {
        parse_and_print(line);
    }

    free(line);
    fclose(file);

    return NULL;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return -1;
    }

    create_theme_dir(theme_dir);

    FILE* file = fopen(argv[1], "r");
    if (file == NULL) {
        perror("Error opening file");
        return -1;
    }

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, process_file, file);
    pthread_join(thread_id, NULL);

    return 0;
}
```

