            std::memcpy(&pdu.crcIndication.CRCFLAG, buffer, sizeof(pdu.crcIndication.CRCFLAG));
            buffer += sizeof(pdu.crcIndication.CRCFLAG);

            validateCRCFlag(pdu.crcIndication.CRCFLAG);

