        crcFlag = gen_.generate() & 0xFFFFFFFF;
    }

    void validateCRCFlag(uint32_t crcFlag) const {
        uint32_t calculatedCrcFlag = (crcFlag >> 16) ^ (crcFlag << 16);
        if (calculatedCrcFlag != crcFlag) {
            throw std::runtime_error("Invalid CRC flag");
        }
    }

