    char url[256];
    int retries;
    pthread_mutex_t mutex;
} UploadTask;

void generate_pdus(NFAPI_CRC_INDICATION_PDU_T** pdus, size_t n) {
    *pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (size_t i = 0; i < n; ++i) {
        (*pdus)[i].rx_ue_information_tag = i + 1;
        (*pdus)[i].rnti = rand() % 65536;
        (*pdus)[i].crcflag = rand() % 2;
    }
}

void* upload(void* arg) {
    UploadTask* task = (UploadTask*)arg;
    int success = 0;
    for (int i = 0; i < 4; ++i) {
        sleep(rand() % 5 + 1); // simulate network latency
        if (!success) {
            snprintf(task->url, sizeof(task->url), "http://example.com/upload/%lu", task->pdu->rx_ue_information_tag);
            success = 1;
        }
    }

    if (success) {
        pthread_mutex_lock(&task->mutex);
        strcpy(task->url, "http://example.com/upload/" + task->url); // concatenate domain for logging purposes
        pthread_mutex_unlock(&task->mutex);
        printf("Uploaded PDU with RX_UE_INFORMATION_TAG: %lu to %s\n", task->pdu->rx_ue_information_tag, task->url);
    } else {
        pthread_mutex_lock(&task->mutex);
        snprintf(task->url, sizeof(task->url), "http://example.com/upload_failed/%d_retries", task->retries + 1);
        pthread_mutex_unlock(&task->mutex);
        printf("Failed to upload PDU with RX_UE_INFORMATION_TAG: %lu after %d retries\n", task->pdu->rx_ue_information_tag, task->retries + 1);
    }

    free(task->pdu);
    free(task);
    return NULL;
}

void log_upload(UploadTask* task) {
    pthread_mutex_lock(&task->mutex);
    printf("Logging upload: %s\n", task->url);
    pthread_mutex_unlock(&task->mutex);
}

void* generate_and_upload(NFAPI_CRC_INDICATION_PDU_T** pdus, size_t n, int (*log_func)(UploadTask*)) {
    UploadTask* tasks = (UploadTask*)malloc(n * sizeof(UploadTask));

    for (size_t i = 0; i < n; ++i) {
        tasks[i].pdu = &((*pdus)[i]);
        tasks[i].retries = 0;
        pthread_mutex_init(&tasks[i].mutex, NULL);
    }

    pthread_t threads[n];

    for (size_t i = 0; i < n; ++i) {
        pthread_create(&threads[i], NULL, upload, &tasks[i]);
    }

    for (size_t i = 0; i < n; ++i) {
        pthread_join(threads[i], NULL);
    }

    for (size_t i = 0; i < n; ++i) {
        log_func(&tasks[i]);
    }

    free(tasks);

    char* urls = (char*)malloc((n + 1) * sizeof(char) * 256);
    size_t pos = 0;
    for (size_t i = 0; i < n; ++i) {
        strcpy(&urls[pos], tasks[i].url);
        pos += strlen(tasks[i].url) + 1;
    }
    urls[pos] = '\0';

    return urls;
}
```

