    friend class boost::serialization::access;

    template<class Archive>
    void serialize(Archive & ar, const unsigned int version) {
        ar & crcflag;
    }
};

class CRCIndicationManager {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    mutex mtx;
    uint64_t successfulOps = 0;
    uint64_t failedOps = 0;
    boost::random::mt19937 rng;

public:
    CRCIndicationManager(const std::string& filename, size_t initialSize) {
        loadFromFile(filename);
        if (initialSize > data.size()) {
            data.resize(initialSize);
            for (auto& elem : data) {
                elem.crc_indication_rel8_tag.crcflag = rng();
            }
        }
    }

    ~CRCIndicationManager() {
        saveToFile("temp.bin");
        boost::filesystem::remove("data.bin");
        boost::filesystem::rename("temp.bin", "data.bin");
    }

    void add(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        lock_guard<mutex> lk(mtx);
        data.push_back(pdu);
        successfulOps++;
    }

    bool get(size_t index, NFAPI_CRC_INDICATION_PDU_T& pdu) {
        lock_guard<mutex> lk(mtx);
        if (index >= data.size()) {
            failedOps++;
            return false;
        }
        pdu = data[index];
        successfulOps++;
        return true;
    }

    void saveToFile(const std::string& filename) {
        ofstream file(filename, ios::binary | ios::trunc);
        boost::archive::binary_oarchive oa(file);
        oa & make_nvp("data", data);
        file.close();
    }

    void loadFromFile(const std::string& filename) {
        ifstream file(filename, ios::binary);
        boost::archive::binary_iarchive ia(file);
        ia & make_nvp("data", data);
        file.close();
    }

    uint64_t getSuccessfulOps() const { return successfulOps; }
    uint64_t getFailedOps() const { return failedOps; }
};
