    measurement->next = head;
    head = measurement;
    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CELL_MEASUREMENTS_T* remove_measurement(uint32_t cell_id) {
    NFAPI_CELL_MEASUREMENTS_T *current = head, *prev = NULL;
    pthread_mutex_lock(&list_mutex);
    while (current != NULL && current->cell_id != cell_id) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) return NULL;
    if (prev == NULL) head = current->next;
    else prev->next = current->next;
    pthread_mutex_unlock(&list_mutex);
    return current;
}

