    NFAPI_CELL_MEASUREMENTS_T **new_head = &head;
    while (1) {
        NFAPI_CELL_MEASUREMENTS_T *measurement = malloc(sizeof(NFAPI_CELL_MEASUREMENTS_T));
        if (fread(&measurement->cell_id, sizeof(uint32_t), 1, file) != 1 ||
            fread(&measurement->measurement_type, sizeof(uint32_t), 1, file) != 1 ||
            fread(&measurement->measurement_value, sizeof(double), 1, file) != 1) {
            break;
        }
        measurement->next = *new_head;
        *new_head = measurement;
        new_head = &measurement->next;
