[' Here's a basic outline for a C# utility class that addresses the given programming task. This code is not exhaustive but serves as a starting point for further development and optimization.

```csharp
using System;
using System.IO;
using System.IO.Compression;
using Newtonsoft.Json;
using Newtonsoft.Json.Serialization;

public sealed class DataLoader
{
    private readonly JsonSerializerSettings _serializerSettings = new JsonSerializerSettings
    {
        Formatting = Formatting.None,
        NullValueHandling = NullValueHandling.Ignore,
        MissingMemberHandling = MissingMemberHandling.Ignore
    };

    public T Load<T>(string filePath) where T : new()
    {
        try
        {
            using var fileStream = File.OpenRead(filePath);
            return LoadData<T>(fileStream, GetCompressionFormat(filePath));
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading data from '{filePath}': {ex.Message}");
            throw;
        }
    }

    private CompressionFormat GetCompressionFormat(string filePath)
    {
        var extension = Path.GetExtension(filePath).ToLowerInvariant();
        return extension switch
        {
            ".gz" => CompressionFormat.Gzip,
            ".deflate" => CompressionFormat.Deflate,
            _ => CompressionFormat.None
        };
    }

    private T LoadData<T>(Stream fileStream, CompressionFormat compressionFormat)
    {
        using var compressedStream = new GZipStream(fileStream, compressionFormat == CompressionFormat.Gzip ? CompressionMode.Decompress : CompressionMode.Decompress);
        using var reader = new StreamReader(compressedStream);
        return JsonSerializer.Deserialize<T>(reader.ReadToEnd(), _serializerSettings);
    }
}
```

