typedef struct {
    pthread_t thread_id;
    int rnti;
    RNTI_TAG rnti_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    NFAPI_CRC_INDICATION_PDU_T *next;
    NFAPI_CRC_INDICATION_PDU_T *prev;
} Node;

Node* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
int num_created = 0;

void generate_unique_rnti(Node **node) {
    while (true) {
        (*node)->rnti = rand() % INT_MAX;
        if (!find_node_by_rnti(*node)) break;
    }
}

bool find_node_by_rnti(Node *node) {
    Node *current = head;
    pthread_mutex_lock(&list_mutex);
    while (current != NULL) {
        if (current->rnti == node->rnti) {
            pthread_mutex_unlock(&list_mutex);
            return true;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);
    return false;
}

void add_to_list(Node *node) {
    pthread_mutex_lock(&list_mutex);
    if (head == NULL) {
        head = node;
        node->next = NULL;
        node->prev = NULL;
    } else {
        node->next = head;
        node->prev = NULL;
        head->prev = node;
        head = node;
    }
    pthread_mutex_unlock(&list_mutex);
}

void remove_from_list(Node *node) {
    pthread_mutex_lock(&list_mutex);
    if (head == node) {
        head = head->next;
        if (head != NULL) head->prev = NULL;
    } else {
        Node *current = head;
        while (current->next != node) current = current->next;
        current->next = node->next;
        if (node->next != NULL) node->next->prev = current;
    }
    pthread_mutex_unlock(&list_mutex);
}

void* create_structure(void *arg) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    generate_unique_rnti(new_node);
    new_node->crc_indication_rel8_tag.CRCFLAG = rand() % 100 > 90; // Set CRCFLAG with a probability of 90%

    add_to_list(new_node);
    num_created++;

    return new_node;
}

void deallocate_structure(Node *node) {
    remove_from_list(node);
    free(node);
}

void print_num_created() {
    pthread_mutex_lock(&list_mutex);
    printf("Number of created structures: %d\n", num_created);
    pthread_mutex_unlock(&list_mutex);
}
