class ArrayManager {
public:
    ArrayManager(size_t initialCapacity) : data_(initialCapacity), capacity_(initialCapacity), size_(0) {}

    ~ArrayManager() { clear(); }

    void insert(size_t index, const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        if (index >= capacity_) resize(2 * capacity_);

        for (size_t i = size_; i > index; --i)
            data_[i] = data_[i - 1];

        data_[index] = pdu;
        ++size_;
    }

