using System.Net.Http;
using System.Text.Json;

public class DynamicValueGenerator
{
    private readonly double _minValue;
    private readonly double _maxValue;
    private readonly bool _isRangeValid;
    private readonly DateTime _lastValidationTime;

    public DynamicValueGenerator(HttpClient httpClient)
    {
        var configuration = FetchConfiguration(httpClient);

        if (!configuration.TryGetValue("minValue", out double minValue) ||
            !configuration.TryGetValue("maxValue", out double maxValue))
        {
            throw new ConfigurationException("Invalid configuration.");
        }

        _minValue = Math.Min(minValue, maxValue);
        _maxValue = Math.Max(minValue, maxValue);

        if (_minValue >= _maxValue)
        {
            throw new ConfigurationException("Invalid range: minValue >= maxValue.");
        }

        _isRangeValid = true;
        _lastValidationTime = DateTime.UtcNow;
    }

    public double GenerateRandomFloat()
    {
        if (!_isRangeValid || DateTime.UtcNow - _lastValidationTime > TimeSpan.FromMinutes(5))
        {
            ValidateRange();
        }

        return new Random().NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GenerateRandomInt()
    {
        return (int)(GenerateRandomFloat() + 0.5);
    }

    private void ValidateRange()
    {
        if (_minValue >= _maxValue)
        {
            throw new ConfigurationException("Invalid range: minValue >= maxValue.");
        }

        _isRangeValid = true;
        _lastValidationTime = DateTime.UtcNow;
    }

    private Dictionary<string, object> FetchConfiguration(HttpClient httpClient)
    {
        try
        {
            var response = httpClient.GetAsync("https://your-config-service.com/dynamic-value-generator").Result;
            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException($"Failed to fetch configuration: {response.StatusCode}");
            }

            return JsonSerializer.Deserialize<Dictionary<string, object>>(await response.Content.ReadAsStreamAsync());
        }
        catch (Exception ex)
        {
            throw new ConfigurationException("Failed to fetch configuration.", ex);
        }
    }

    private class ConfigurationException : Exception
    {
        public ConfigurationException() { }
        public ConfigurationException(string message) : base(message) { }
        public ConfigurationException(string message, Exception innerException) : base(message, innerException) { }
    }

    public override string ToString() => $"DynamicValueGenerator: minValue={_minValue}, maxValue={_maxValue}";
}
```

