    }

    let log_builder = LogBuilder::new()
        .filter(None, LevelFilter::Info)
        .format_timestamp(None)
        .target(Target::Stderr);

    Logger::init(log_builder.build())?;

    Ok(())
}

fn set_env_var(key: &str, value: String) {
    use std::os::unix::prelude::EnvExt;

    let mut env = ::std::process::env();
    env.insert(key, value);
    env.write_to_file().unwrap();
}

