    new_node->channelFrequency = channelFrequency;
    new_node->next = NULL;

    return new_node;
}

UeMeasurementResult* init_linked_list(int size, int id_start, int frequency_step) {
    UeMeasurementResult *head = NULL, *current = NULL;

    for (int i = 0; i < size; ++i) {
        int id = id_start + i;
        time_t timestamp = time(NULL);
        int signalStrength = rand() % 100 + 1; // Simulate random signal strength
        int channelFrequency = frequency_step * i;

        UeMeasurementResult* new_node = create_ue_measurement(id, timestamp, signalStrength, channelFrequency);
        if (!new_node) {
            free_linked_list(head);
            return NULL;
        }

        if (!head) {
            head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    return head;
}

void free_linked_list(UeMeasurementResult *head) {
