    memcpy(&node->data, &data, sizeof(UeMeasurementResult));

    if (list->size == 0) {
        list->head = node;
        list->tail = node;
    } else {
        node->prev = list->tail;
        list->tail->next = node;
        list->tail = node;
    }
    list->size++;
}

void delete_at_head(List* list) {
    if (list->size == 0) return;

    Node* head = list->head;
    list->head = list->head->next;
    if (list->head) list->head->prev = NULL;
    else list->tail = NULL;

    free(head);
    list->size--;
}

void delete_at_tail(List* list) {
