class DynamicValueGenerator {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T*> structures;
    float min, max;
    bool includeMin, includeMax;
    std::mutex mutex;
    static constexpr int MAX_STRUCTURES = 1000;

public:
    DynamicValueGenerator(float min, float max, bool includeMin, bool includeMax)
        : min(min), max(max), includeMin(includeMin), includeMax(includeMax) {}

    void AddStructure(NFAPI_CRC_INDICATION_PDU_T* structure) {
        std::unique_lock<std::mutex> lock(mutex);
        if (structures.size() >= MAX_STRUCTURES) {
            std::cerr << "Error: Cannot add more structures, limit exceeded." << std::endl;
            return;
        }
        structures.push_back(structure);
    }

    float GetRandomFloat() {
        std::unique_lock<std::mutex> lock(mutex);
        if (min > max) {
            std::cerr << "Error: Minimum value is greater than maximum value." << std::endl;
            return 0.0f;
        }
        float range = max - min;
        if (includeMin && includeMax) {
            return min + static_cast<float>(rand()) / RAND_MAX * range;
        } else if (includeMin) {
            return min + static_cast<float>(rand()) / (RAND_MAX + 1.0f) * range;
        } else if (includeMax) {
            return min + static_cast<float>(rand() % static_cast<int>(range)) / range * range;
        } else {
            return static_cast<float>(rand()) / RAND_MAX * range + min;
        }
    }

    int GetRandomInt() {
        float randomFloat = GetRandomFloat();
        return static_cast<int>(randomFloat);
    }

    void SetRange(float newMin, float newMax, bool includeNewMin, bool includeNewMax) {
        std::unique_lock<std::mutex> lock(mutex);
        min = newMin;
        max = newMax;
        includeMin = includeNewMin;
        includeMax = includeNewMax;
    }

    std::string ToString() const {
        std::ostringstream os;
        os << "DynamicValueGenerator: ";
        if (includeMin) {
            os << "[";
        }
        os << min << ", ";
        if (!includeMax) {
            os << "<";
        }
        os << max << ", ";
        if (includeMax) {
            os << "]";
        }
        if (includeMin && !includeMax) {
            os << "(inclusive min, exclusive max)";
        } else if (!includeMin && includeMax) {
            os << "(exclusive min, inclusive max)";
        } else {
            os << "(both inclusive)";
        }
        return os.str();
    }
};
