#include <map>
#include <string>

struct LTE_RRC_NAS_Transport_PDU {
    int UE_ID;
    NAS_Message message;
};

class DynamicArray {
public:
    void add(const LTE_RRC_NAS_Transport_PDU& pdu) {
        if (data.count(pdu.UE_ID) == 0) {
            data[pdu.UE_ID] = std::vector<LTE_RRC_NAS_Transport_PDU>{pdu};
            summary.emplace(pdu.message, 1);
