} LTE_RRC_NAS_Transport_PDU;

typedef struct node {
    LTE_RRC_NAS_Transport_PDU data;
    struct node* next;
    pthread_mutex_t lock;
} Node;

Node** create_array(size_t size) {
    Node** array = malloc(sizeof(Node*) * size);
    for (size_t i = 0; i < size; ++i) {
        array[i] = NULL;
    }
    return array;
}

void destroy_array(Node** array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        Node* current = array[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(array);
}

