class DynamicList {
public:
    DynamicList() : head(nullptr), size(0) {}

    void add(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
        if (pdu == nullptr) {
            throw std::invalid_argument("Invalid pointer");
        }

        if (size + 1 > MAX_SIZE) {
            std::cerr << "Error: Exceeded maximum size limit" << std::endl;
            return;
