        auto newNode = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>();
        new (newNode.get()) NFAPI_CRC_INDICATION_PDU_T{*pdu};
        newNode->next = head;
        head = std::move(newNode);
        size++;
    }

    void updateConfig(const RAN_CONFIG& config) {
