        this->globalCooldown = 0;
        this->lastCriticalHit = std::chrono::steady_clock::now();
    }

    void performAttack(int attackId) {
        auto it = attacks.find(attackId);
        if (it == attacks.end()) return;

        Attack& attack = it->second;
        if (std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - attack.lastUse).count() < attack.cooldown) {
            std::cout << "Attack on cooldown." << std::endl;
            return;
