        globalCooldown = 0;

        if (std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - lastCriticalHit).count() > 1000) { // Critical hit every second
            globalCooldown = 0;
        } else {
            globalCooldown += attack.cooldown * 2;
        }
    }

