        return NULL;
    }

    unsigned int unique_tags[N] = {0}; // Array to store used tags
    unsigned char consecutive_flags[N] = {0}; // Array to store consecutive flags
    unsigned int current_tag = 1; // Start tag from 1

    for (unsigned int i = 0; i < N; ++i) {
        arr[i].tag = current_tag++;
        arr[i].rnti = /* Set RNTI value */;
        arr[i].crc_indication = /* Set CRC_INDICATION_REL8_TAG value */;

        // Find a unique tag and non-consecutive flag
        do {
