unsigned int allocated = 0;

void init_memory_pool(unsigned int size) {
    capacity = size;
    pool = (Node*)malloc(capacity * sizeof(Node));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for the pool\n");
        exit(EXIT_FAILURE);
    }

    for (unsigned int i = 0; i < capacity; ++i) {
        Node* node = &pool[i];
        node->next = &pool[(i + 1) % capacity];
        node->prev = &pool[(i - 1 + capacity) % capacity];
        node->data.RX_UE_INFORMATION_TAG = /* initialize tag */;
        node->data.RNTI = /* initialize RNTI */;
        node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    pool[capacity - 1].next = NULL;
    pool[0].prev = NULL;
}
