public:
    LinkedList() : head(nullptr), tail(nullptr), num_nodes(0) {}

    ~LinkedList() {
        clear();
    }

    void push_back(const NR_UPLINK_TRAFFIC_INFORMATION& info) {
        auto new_node = std::make_unique<Node>(info);
        if (!new_node) {
            throw std::bad_alloc();
        }

        if (head == nullptr) {
            head = std::move(new_node);
            tail = head.get();
        } else {
            tail->next = std::move(new_node);
            tail = tail->next.get();
        }
        ++num_nodes;
    }

    void clear() {
        Node* current = head.get();
        while (current) {
            Node* next = current->next.get();
            delete current;
            current = next;
        }
        head.reset();
        tail = nullptr;
        num_nodes = 0;
    }

    int getNumNodes() const {
