    if (active_connections >= max_connections) return NULL;

    tcp_context *ctx = calloc(1, sizeof(tcp_context));
    if (!ctx) {
        log("Failed to allocate memory for context");
        return NULL;
    }

    // Initialize socket and address here

    sem_init(&ctx->sem_conn, 0, 1);
    sem_init(&ctx->sem_backpressure, 0, 0);

    pool = realloc(pool, (pool_size + 1) * sizeof(tcp_context));
    if (!pool) {
        free(ctx);
        log("Failed to allocate memory for pool");
        return NULL;
    }

    pool[pool_size++] = ctx;
    active_connections++;

    return ctx;
}

void deallocate_context(tcp_context *ctx) {
    if (!ctx || pool_size == 0) return;

    sem_destroy(&ctx->sem_conn);
    sem_destroy(&ctx->sem_backpressure);

    // Close socket here

    memmove(&pool[pool_size - 1], ctx, sizeof(tcp_context));
    pool[pool_size--] = NULL;
    active_connections--;

    free(ctx);
}

void handle_connection(tcp_context *ctx) {
    // Handle incoming connection requests here
}

void manage_backpressure() {
    // Implement backpressure handling mechanism here
}

int main() {
    init_pool();

    while (1) {
        sem_wait(&sem_pool);

        tcp_context *ctx = allocate_context();
        if (!ctx) continue;

        handle_connection(ctx);
        manage_backpressure();

        sem_post(&sem_pool);
    }

    return 0;
}
