struct DATA_PACKET {
    int packet_id;
    size_t payload_size;
    std::chrono::system_clock::time_point timestamp;
};

class MemoryManager {
public:
    MemoryManager(size_t initial_capacity, size_t max_capacity)
        : data_(initial_capacity), capacity_(initial_capacity), max_capacity_(max_capacity), logFile_("log.txt") {}

    DATA_PACKET& operator[](size_t index) {
        if (index >= capacity_) {
            resize(2 * capacity_);
        }
        return data_[index];
    }

    void resize(size_t newCapacity) {
        if (newCapacity > max_capacity_) {
            std::cerr << "Error: Cannot exceed maximum capacity." << std::endl;
            return;
        }

        auto oldData = data_;
        data_.resize(newCapacity);
        for (size_t i = 0; i < capacity_; ++i) {
            if (i < newCapacity) {
                data_[i] = std::move(oldData[i]);
            }
        }
        capacity_ = newCapacity;
    }

    void notifyGrowth() {
        std::lock_guard<std::mutex> lock(logMutex_);
        logFile_ << "Memory growth: from " << capacity_ << " to " << 2 * capacity_ << std::endl;
    }

private:
    std::vector<DATA_PACKET> data_;
    size_t capacity_{0};
    size_t max_capacity_{0};
    std::ofstream logFile_;
    mutex logMutex_;
};

void generatePayload(MemoryManager& manager, int id) {
    std::uniform_int_distribution<> distribution(10, 100);
    manager[id].payload_size = distribution(generator_);
    manager[id].timestamp = std::chrono::system_clock::now();
}

void logEvent(const std::string& event) {
    std::lock_guard<std::mutex> lock(logMutex_);
    logFile_ << event << std::endl;
}

int main() {
    std::random_device rd;
    std::mt19937 generator_(rd());

    MemoryManager manager(10, 1024 * 1024); // Initial capacity: 10 elements, Max capacity: 1MB

    std::vector<std::thread> threads;
    for (size_t i = 0; i < 10; ++i) {
        threads.emplace_back(generatePayload, std::ref(manager), i);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    logEvent("Memory usage: " + std::to_string(manager.capacity_));

    return 0;
}
```

