Next, let's create a custom allocator:

```c
#include <stdlib.h>
#include <string.h>

typedef struct {
    size_t blockSize;
    void* start;
    void* end;
    void* current;
} Allocator;

void allocator_init(Allocator* allocator, size_t blockSize) {
    allocator->blockSize = blockSize;
    allocator->start = malloc(blockSize * 2); // Reserve extra space for efficient reuse
    allocator->end = allocator->start + blockSize * 2;
    allocator->current = allocator->start;
}

void* allocator_allocate(Allocator* allocator) {
    if (allocator->current >= allocator->end) {
        allocator->end += blockSize * 2; // Expand the memory block when necessary
    }
    void* result = allocator->current;
    allocator->current += allocator->blockSize;
    return result;
}

void allocator_deallocate(Allocator* allocator, void* ptr) {
    if (ptr < allocator->start || ptr >= allocator->end) {
        fprintf(stderr, "Invalid memory block\n");
        exit(EXIT_FAILURE);
    }
    ptr = (char*)ptr - ((char*)allocator->start - (char*)ptr);
    *((char*)ptr) = 0; // Mark the block as free for reuse
}
```

Now, let's create a function to manage the list:

```c
List* list_create(size_t blockSize, size_t nodeSize) {
    List* list = malloc(sizeof(List));
    Allocator allocator;
    allocator_init(&allocator, blockSize);
    list->allocator = &allocator;
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

void list_insert(List* list, const RX_UE_INFORMATION_TAG tag, const RNTI rnti, const CRC_INDICATION_REL8_TAG crc_indication, bool crcflag) {
    if (rnti < MIN_RNTI || rnti > MAX_RNTI) {
        fprintf(stderr, "Invalid RNTI value\n");
        return;
    }

    Node* node = (Node*)allocator_allocate(list->allocator);
    node->id = ++list->size;
    node->tag = tag;
    node->rnti = rnti;
    node->crc_indication = crc_indication;
    node->crcflag = crcflag;
    node->next = NULL;
    node->prev = list->tail;

    if (list->head == NULL) {
        list->head = node;
    }

    if (list->tail != NULL) {
        list->tail->next = node;
    }

    list->tail = node;
}

void list_reset(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        allocator_deallocate(list->allocator, current);
        current = next;
    }
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
}
```']

