class DynamicArray {
public:
    explicit DynamicArray(size_t initialCapacity) : data_(initialCapacity) {}

    void push_back(const NFAPI_CRC_INDICATION_PDU_T& element) {
        if (data_.empty() || data_.back().RNTI != 0) { // Ensure no duplicate RNTIs and valid structure
            if (data_.size() == data_.capacity()) {
