void insertNode(List* list, Node* node) {
    if (!node) return;

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->next = list->head;
        list->head->prev = node;
        list->head = node;
    }

    list->size++;
}

void removeNode(List* list, Node* node) {
    if (node == NULL || list->size <= 0) return;

    if (list->size == 1) {
        free(node);
        list->head = NULL;
        list->tail = NULL;
    } else if (node == list->head) {
        list->head = node->next;
        list->head->prev = NULL;
        free(node);
    } else if (node == list->tail) {
        list->tail = node->prev;
        list->tail->next = NULL;
        free(node);
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
        free(node);
    }

    list->size--;
}
