```c
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    void* ptr;
    size_t size;
    struct block *next;
} Block;

typedef struct {
    Block head;
    size_t allocated;
    size_t free;
    void (*log)(const char*, ...);
} Allocator;

Allocator allocator = {
    .head = {.ptr = NULL, .size = 0, .next = NULL},
    .allocated = 0,
    .free = 0,
};

void* my_malloc(size_t size) {
    if (!size) return NULL;

    Block *current = &allocator.head;
    while (current->next != NULL) current = current->next;

    if (current->size >= size) {
        void* result = current->ptr;
        current->ptr = current->ptr + size;
        current->size -= size;
        return result;
    }

    Block* new_block = (Block*)malloc(sizeof(Block) + size);
    if (!new_block) return NULL;

    new_block->next = &allocator.head;
    allocator.head.next = new_block;
    allocator.free += sizeof(Block);
    allocator.allocated += size;

    return new_block->ptr;
}

void my_free(void* ptr) {
    if (!ptr) return;

    Block* current = &allocator.head;
    while (current->next != NULL) {
        if (current->next->ptr == ptr) {
            void* temp = current->next->ptr;
            current->next->ptr = current->next->ptr + current->next->size;
            current->next->size -= sizeof(Block);
            if (current->next->size == 0) {
                Block* next_block = current->next->next;
                free(current->next);
                allocator.free += sizeof(Block);
                current->next = next_block;
            }
            return;
        }
        current = current->next;
    }
}
