    public double nextDouble() {
        lock.lock();
        try {
            if (maxValue - minValue <= 0) {
                throw new IllegalArgumentException("minValue must be less than maxValue.");
            }
            return minValue + random.nextDouble() * (maxValue - minValue);
        } finally {
            lock.unlock();
        }
    }

    public int nextInt() {
        lock.lock();
        try {
            if (maxValue - minValue <= 0) {
                throw new IllegalArgumentException("minValue must be less than maxValue.");
