    int identifier;
    int value;
    bool crcFlag;
};

vector<Record> generateRecords(int count, int minValue, int maxValue) {
    vector<Record> records(count);
    default_random_engine generator;
    uniform_int_distribution<int> distribution(minValue, maxValue);

    for (auto &record : records) {
        record.tag = RX_UE_INFORMATION_TAG; // Assuming this is a constant
        record.identifier = RNTI;            // Assuming this is a constant
        record.value = distribution(generator);
        record.crcFlag = bool(rand() % 2);
    }

    return records;
}

vector<pair<string, string>> generateNFAPCRCIndicationAndRetrieveUserData(int NFAPI_CRC_INDICATION_PDU_COUNT, int RX_UE_INFORMATION_TAG, int RNTI, char charSet[], int supervisorId, int timeout) {
    vector<Record> records = generateRecords(NFAPI_CRC_INDICATION_PDU_COUNT, 0, INT_MAX);

    string hashedToken;
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, charSet, strlen(charSet));
    SHA256_Final((unsigned char*)&hashedToken[0], &ctx);

    stringstream ss;
    ss << hex << setw(64) << internal << uppercase << hashedToken.substr(0, 64);
    hashedToken = ss.str();

    try {
        Session session;
        Query query = session.sql("SELECT name, city, address FROM Employees WHERE supervisor_id = ?", supervisorId);
        RowResult result = query.execute();

        vector<pair<string, string>> data;
        for (const auto &row : result) {
            data.push_back(make_pair("name", row[0].get<string>()));
            data.push_back(make_pair("city", row[1].get<string>()));
            data.push_back(make_pair("address", row[2].get<string>()));
        }

        return {make_pair("hashedToken", hashedToken), make_pair("data", move(data))};
    } catch (const Error &e) {
        cerr << "Error: " << e.what() << endl;
        throw;
    }
}
