struct NRCellConfig {
    int cellId;
    std::vector<int> bandwidthPartitions;
    int defaultPagingPeriod;
};

std::unique_ptr<NRCellConfig[]> initializeNRCellConfigArray(const std::string& filename, int numCells) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        spdlog::error("Failed to open configuration file: {}", filename);
        return nullptr;
    }

    nlohmann::json j;
    try {
        file >> j;
    } catch (const std::exception& e) {
        spdlog::error("Error parsing JSON file: {}", e.what());
        return nullptr;
    }

    auto configArray = std::make_unique<NRCellConfig[]>(numCells);
    int index = 0;
    for (const auto& cell : j.items()) {
        if (index >= numCells) break;

        try {
            configArray[index].cellId = cell.key().get<int>();
            configArray[index].bandwidthPartitions = cell.value()["bandwidthPartitions"].get<std::vector<int>>();
            configArray[index].defaultPagingPeriod = cell.value()["defaultPagingPeriod"].get<int>();
        } catch (const std::exception& e) {
            spdlog::warn("Missing or invalid field in configuration file: {}", e.what());
            // Provide sensible defaults if necessary
        }
        index++;
    }

    return configArray;
}
