#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/hmac.h>
#include <pthread.h>
#include <sys/mman.h>
#include <log4c.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    const EVP_CIPHER *cipher;
    const EVP_MD *hash;
} Algorithm;

struct pool {
    size_t count;
    Algorithm alg;
    NFAPI_CRC_INDICATION_PDU_T *data;
    pthread_mutex_t lock;
};

void *create_pool(size_t size, const Algorithm *alg) {
    void *mem = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    struct pool *pool = mem;
    pool->count = size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pool->alg = *alg;
    pool->data = (NFAPI_CRC_INDICATION_PDU_T *)mem;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void free_pool(struct pool *pool) {
    munmap(pool, pool->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_destroy(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T *acquire_from_pool(struct pool *pool) {
    pthread_mutex_lock(&pool->lock);
    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool->data[0];
    memmove(&pool->data[0], &pool->data[1], (pool->count - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->data[pool->count - 1] = *pdu;
    pthread_mutex_unlock(&pool->lock);
    return pdu;
}

void log_event(const char *message) {
    static const int log_level = LOG4C_LEVEL_INFO;
    Log4cConfigureMinimal("logfile.conf", LOG4C_READ_CONFIG_FROM_FILE);
    Log4cCategorySetLevel(LOG4C_ROOT_CATEGORY, log_level);
    Log4cCategoryGetLogger(LOG4C_ROOT_CATEGORY)->info(message);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s N\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    size_t n = atoi(argv[1]);
    struct pool *pool = create_pool(n * sizeof(NFAPI_CRC_INDICATION_PDU_T), (const Algorithm){EVP_aes_256_gcm(), SHA256});

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = acquire_from_pool(pool);
        pdu->tag.value = i;
        pdu->rnti = i + 123456;
        pdu->crc_indication.crcflag = rand() % 2;

        // Implement AES encryption and HMAC-SHA256 here using the provided algorithms

        log_event("Created PDU");
    }

    free_pool(pool);
    return EXIT_SUCCESS;
}
```

