#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct ConnectionRequestData {
    int session_id;
    char source_ip[32];
    char destination_ip[32];
    int priority;
} ConnectionRequestData;

// Hash function for IP addresses (Jenkins hash)
unsigned long ip_hash(const char *ip) {
    unsigned long hash = 0;
    while (*ip) {
        hash += *ip++;
        0x5bd1e995 ^= (hash << 24);
        hash = hash ^ (hash >> 32);
    }
    return hash;
}

// Custom hash table structure with a load factor of 0.75 and separate chaining for collision resolution
typedef struct HashTable {
    int size;
    int count;
    ConnectionRequestData **data;
    pthread_mutex_t mutex;
} HashTable;

// Allocate memory for a new hash table with the given size
HashTable *new_hash_table(int size) {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->size = size;
    ht->count = 0;
    ht->data = calloc(size, sizeof(ConnectionRequestData*));
    pthread_mutex_init(&ht->mutex, NULL);
    return ht;
}

// Insert a new connection request into the hash table
void insert(HashTable *ht, ConnectionRequestData data) {
    unsigned long index = ip_hash(data.source_ip) % ht->size;
    while (ht->data[index]) {
        if (strcmp(ht->data[index]->source_ip, data.source_ip) == 0 && ht->data[index]->session_id == data.session_id) {
            fprintf(stderr, "Error: Duplicate session ID found.\n");
            return;
        }
        index = (index + 1) % ht->size;
    }
    ht->data[index] = malloc(sizeof(ConnectionRequestData));
    memcpy(ht->data[index], &data, sizeof(ConnectionRequestData));
    ht->count++;
}

// Delete a connection request from the hash table by session ID
void delete_by_id(HashTable *ht, int session_id) {
    for (int i = 0; i < ht->size; ++i) {
        ConnectionRequestData *data = ht->data[i];
        if (!data || data->session_id != session_id) continue;
        free(data);
        ht->data[i] = NULL;
        ht->count--;
        break;
    }
}

// Iterate over all active connections with a priority above the given threshold
void iterate_above_threshold(HashTable *ht, int threshold) {
    pthread_mutex_lock(&ht->mutex);
    for (int i = 0; i < ht->size; ++i) {
        ConnectionRequestData *data = ht->data[i];
        if (!data || data->priority <= threshold) continue;
        printf("Session ID: %d, Source IP: %s, Destination IP: %s, Priority: %d\n", data->session_id, data->source_ip, data->destination_ip, data->priority);
    }
    pthread_mutex_unlock(&ht->mutex);
}

// Clear the hash table and free all allocated memory
void clear(HashTable *ht) {
    for (int i = 0; i < ht->size; ++i) {
        ConnectionRequestData *data = ht->data[i];
        if (!data) continue;
        free(data);
        ht->data[i] = NULL;
    }
    free(ht->data);
    ht->data = NULL;
    ht->count = 0;
}
```

This implementation uses a separate chaining approach for collision resolution, with each bucket containing a linked list of connections. The Jenkins hash function is used to distribute the connections evenly across the buckets while minimizing collisions. A mutex is employed to protect critical sections and ensure thread safety.

To integrate an IP geolocation service, you can replace the `ip_hash` function with a custom implementation that first calls the geolocation API to obtain the country code for each IP address before hashing it. However, this may introduce latency due to API calls and require careful dependency management. Alternatively, you could maintain a local IP-to-country mapping table for faster lookups at the cost of increased memory footprint and periodic updates.

For further optimization, consider using a more efficient hash function or implementing a different collision resolution strategy like open addressing. Additionally, consider using a thread pool to manage concurrent access to the hash table from multiple threads.']

