function copyBufferBytes(buffers, length) {
    if (!Array.isArray(buffers) || !Number.isInteger(length)) return null;

    const result = Buffer.allocUnsafe(length);
    let offset = 0;

    for (const buffer of buffers) {
        if (!Buffer.isBuffer(buffer)) continue;

        const copyLength = Math.min(buffer.length - offset, length - result.length);
        result.write(buffer.slice(offset, offset + copyLength), 0, copyLength);
        offset += copyLength;
    }

    return result;
}
```

