[' Here's a C function that meets the requirements you've outlined. This implementation uses a file as the data source, but it can be easily extended to handle other sources like network streams or databases by modifying the `read_data` function.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct Node {
    int key;
    struct Node *next;
} Node;

Node* read_and_allocate(FILE *file) {
    Node *current = malloc(sizeof(Node));
    if (!current) {
        perror("Memory allocation failure");
        return NULL;
    }

    if (fscanf(file, "%d%*c", &current->key) != 1) {
        free(current);
        return NULL;
    }

    current->next = read_and_allocate(file);
    if (!current->next && ferror(file)) {
        perror("Error reading data");
        free(current);
        return NULL;
    }

    return current;
}

Node* load_list_from_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    Node *head = read_and_allocate(file);
    if (!head) {
        fclose(file);
        return NULL;
    }

    while (fgetc(file) != EOF) {
        head->next = read_and_allocate(file);
        if (!head->next) {
            perror("Memory allocation failure");
            free_list(head);
            fclose(file);
            return NULL;
        }
        head = head->next;
    }

    fclose(file);
    return head;
}

void free_list(Node *node) {
    while (node != NULL) {
        Node *temp = node;
        node = node->next;
        free(temp);
    }
}
```

