void processCSV(const std::string& filename) {
    std::ifstream file(filename, std::ios::in | std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return;
    }

    size_t bufferSize = 1024 * 1024; // 1 MB chunk size
    char* buffer = new char[bufferSize];
    size_t bytesRead;

    while ((bytesRead = file.readsome(buffer, bufferSize)) > 0) {
        boost::csv::csv_parser parser{buffer, bytesRead};
        for (auto&& row : parser) {
            try {
                auto productIdIt = products.find(row[0].get());
                Product& product = productIdIt != products.end() ? *productIdIt->second.second : products[row[0].get()] = { row[0].get(), Product{} };
                double sales = std::stod(row[1].get()) * exchangeRate; // Convert to standard currency
                product.totalSales += sales;
            } catch (const std::exception& e) {
                std::cerr << "Error parsing line: " << e.what() << std::endl;
            }
        }
    }

    delete[] buffer;
}

void fetchExchangeRate() {
    cpr::Response r = cpr::Get(cpr::Url{"https://api.exchangerate-api.com/v4/latest/USD"});
    if (r.status_code == cpr::StatusCode::Ok) {
        auto json = nlohmann::json::parse(r.text);
        exchangeRate = json["rates"]["EUR"]; // Replace "EUR" with the desired standard currency
    } else {
        std::cerr << "Error fetching exchange rate: " << r.status_code << std::endl;
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <csv_file>" << std::endl;
        return 1;
    }

    processCSV(argv[1]);
    fetchExchangeRate();

    for (const auto& product : products) {
        std::cout << product.first << ": " << product.second.totalSales << std::endl;
    }

    return 0;
}
```

