void get_pbkdf2_iterations(int* iter) {
    struct rlimit lim;
    int max_iters = 1000000;
    getrlimit(RLIMIT_CPU, &lim);
    *iter = (lim.rlim_cur > max_iters) ? lim.rlim_cur : max_iters;
}

void derive_key(unsigned char* key, const unsigned char* passwd, const unsigned char* salt, int iter, size_t len) {
    unsigned char derived[EVP_MAX_KEY_LENGTH];
    EVP_BytesToKey(EVP_pbkdf2_hmac(), EVP_sha256(), salt, passwd, len, iter, derived);
    memcpy(key, derived, len);
}

void aes256gcm_init(aes256gcm_ctx* ctx, const unsigned char* passwd, size_t passwd_len, const unsigned char* salt, size_t salt_len) {
    int iter;
    get_pbkdf2_iterations(&iter);

    derive_key(ctx->key, passwd, salt, iter, sizeof(ctx->key));
    ctx->iv[0] = 0x00;
    RAND_bytes(ctx->iv + 1, AES_GCM_IV_LENGTH - 1);

    EVP_CIPHER_CTX_init(ctx->ctx);
    EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key, ctx->iv);
}

void aes256gcm_cleanup(aes256gcm_ctx* ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
}

int main() {
    const size_t passwd_len = 32;
    const size_t salt_len = 16;
    unsigned char passwd[passwd_len];
    unsigned char salt[salt_len];

    // Read password and salt from input or other sources
    // ...

    aes256gcm_ctx ctx;
    aes256gcm_init(&ctx, passwd, passwd_len, salt, salt_len);

    // Use the initialized cipher for encryption/decryption
    // ...

    aes256gcm_cleanup(&ctx);

    return 0;
}
```

