int validate_token(const char *json_str) {
    json_t *root = json_loads(json_str, 0, NULL);
    if (!root) {
        fprintf(stderr, "Failed to parse JSON\n");
        return -1;
    }

    TokenResponse token;
    json_token_get_object(root, &token);

    // Validate required fields
    if (!json_is_string(json_object_get(root, "access_token")) ||
        !json_is_integer(json_object_get(root, "expires_in")) ||
        !json_is_string(json_object_get(root, "token_type"))) {
        fprintf(stderr, "Invalid JSON structure\n");
        json_decref(root);
        return -1;
    }

    // Validate token_type
    const char *token_type = json_string_value(json_object_get(root, "token_type"));
    if (strcmp(token_type, "Bearer") != 0) {
        fprintf(stderr, "Invalid token type: %s\n", token_type);
        json_decref(root);
        return -1;
    }

    // Validate expires_in
    int expires_in = json_integer_value(json_object_get(root, "expires_in"));
    if (expires_in <= 0) {
        fprintf(stderr, "Invalid expires_in value: %d\n", expires_in);
        json_decref(root);
        return -1;
    }

    // Validate refresh_token (optional)
    const char *refresh_token = json_string_value(json_object_get(root, "refresh_token"));
    if (refresh_token && strlen(refresh_token) > 256) {
        fprintf(stderr, "Invalid refresh_token length: %zu\n", strlen(refresh_token));
        json_decref(root);
        return -1;
    }

    // Account for clock skew and handle potential race conditions
    time_t current_time = time(NULL);
    if (current_time > (time_t)expires_in + 30) {
        fprintf(stderr, "Token has expired\n");
        json_decref(root);
        return -1;
    }

    // Fetch additional token metadata if needed (not shown here for brevity)

    // Store the validated token data
    token.access_token = strdup(json_string_value(json_object_get(root, "access_token")));
    token.expires_in = expires_in;
    token.token_type = strdup(token_type);
    token.refresh_token = refresh_token ? strdup(refresh_token) : NULL;

    // Use the validated token data as needed

    json_decref(root);
    return 0;
}
```

