    NFAPI_CRC_INDICATION_PDU *last = *head_ref;
    while (last->next != NULL)
        last = last->next;

    last->next = new_node;
}

void free_list(NFAPI_CRC_INDICATION_PDU **head_ref) {
    NFAPI_CRC_INDICATION_PDU *temp = *head_ref;
    while (*head_ref != NULL) {
        temp = *head_ref;
        *head_ref = (*head_ref)->next;
        free(temp);
    }
}

NFAPI_CRC_INDICATION_PDU* create_list(uint32_t tag, uint16_t rnti, unsigned int n) {
    NFAPI_CRC_INDICATION_PDU *head = NULL;

    for (unsigned int i = 0; i < n; ++i) {
