import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;

public class MD5 {
    private static final String ALGORITHM = "HmacMD5";

    public static byte[] hash(byte[] data) throws NoSuchAlgorithmException, InvalidKeyException {
        Mac mac = Mac.getInstance(ALGORITHM);
        SecretKeySpec secretKey = new SecretKeySpec(Arrays.copyOfRange(data, 0, 16), ALGORITHM);
        mac.init(secretKey);
        return mac.doFinal(data);
    }

