    private static final ConcurrentHashMap<String, Path> cache = new ConcurrentHashMap<>();

    public boolean fileExists(String url) throws IOException {
        try (URL connection = new URL(url)) {
            if (connection.getContentLength() > 0) {
                return true;
            }
        } catch (IOException e) {
            // Handle network connectivity issues and transient errors
        }
        return false;
