            Path cachedPath = Files.createTempFile(Paths.get(localCacheDir), key, null);
            try (InputStream inputStream = new URL(url).openStream()) {
                Files.copy(inputStream, cachedPath);
            } catch (IOException e) {
                // Handle I/O errors and retry logic
            }
            cache.put(key, cachedPath);
        }
        return cache.get(key);
