const { Buffer } = require('buffer');

// Configuration parameters
const MAX_UE_ID = 10000;
const MAX_CRCFLAG = 255;

// Custom function to copy buffer bytes
function copyBufferBytes(buffers, start, length) {
  const result = Buffer.allocUnsafe(length);

  let pos = 0;
  for (let i = 0; i < buffers.length && pos < length; i++) {
    if (buffers[i]) {
      const end = Math.min(pos + length, buffers[i].length);
      result.writeBuffer(buffers[i].slice(start, end), pos);
      pos += end - start;
    }
  }

  return result;
}

// Generate CRC indications
function generateNfarxCrcIndications(numIndications) {
  const indications = [];

  // Ensure unique UE IDs and RNTIs
  const ueIds = new Set();
  let rnti = 1;

  for (let i = 0; i < numIndications; i++) {
    const ueId = ueIds.values().next().value + 1;
    ueIds.add(ueId);

    if (ueId > MAX_UE_ID) {
      console.warn(`Maximum UE ID (${MAX_UE_ID}) reached, resetting RNTI to 1`);
      rnti = 1;
    }

    const crcIndication = {
      rxUeInformationTag: Buffer.allocUnsafe(4),
      rnti: Buffer.from([rnti]),
      crcIndicationRel8Tag: {
        crcFlag: Math.floor(Math.random() * (MAX_CRCFLAG + 1))
      }
    };

    indications.push(crcIndication);
    rnti++;
  }

  return indications;
}
