struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    bool crcflag;
};

std::mutex list_mutex;
std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> data_list;
boost::circular_buffer<NFAPI_CRC_INDICATION_PDU_T> buffer(1024); // Buffer for temporary storage

bool isValidRNTI(uint32_t rnti) {
    return rnti > 0 && rnti < UINT32_MAX;
}

bool isValidCRCFLAG(bool crcflag) {
    return crcflag >= false && crcflag <= true;
}

void addToList(NFAPI_CRC_INDICATION_PDU_T&& data) {
    std::unique_lock<std::mutex> lock(list_mutex);

    // Check for duplicate RNTI and valid CRCFLAG
    for (const auto& item : data_list) {
        if (item->rnti == data.rnti && !isValidCRCFLAG(data.crcflag)) {
            lock.unlock();
            return;
        }
    }

    // Add the data to the list
    data_list.emplace_back(std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(data));
}

void processBuffer() {
    std::unique_lock<std::mutex> lock(list_mutex);

    while (!buffer.empty()) {
        auto data = buffer.front();
        if (isValidRNTI(data.rnti) && isValidCRCFLAG(data.crcflag)) {
            addToList(std::move(data));
            buffer.pop_front();
        } else {
            buffer.pop_front();
            break;
        }
    }
}

void logPerformanceMetrics() {
    BOOST_LOG_TRIVIAL(info) << "Number of elements in the list: " << data_list.size();
    BOOST_LOG_TRIVIAL(info) << "Size of the buffer: " << buffer.size();
}
