```cpp
#include <iostream>
#include <chrono>
#include <list>
#include <mutex>
#include <random>
#include <vector>

struct LTE_RRC_UE_CONTEXT {
    int UE_ID;
    int CELL_ID;
    enum class NAS_STATE { IDLE, CONNECTED, DISCONNECTED };
    NAS_STATE state;
    std::chrono::time_point<std::chrono::system_clock> lastUpdate;
};

class DynamicLinkedList {
private:
    std::list<LTE_RRC_UE_CONTEXT> nodes;
    std::mutex mtx;
    unsigned long maxNodes = 1000000;

public:
    void addNode(const LTE_RRC_UE_CONTEXT& node) {
        if (nodes.size() >= maxNodes) {
            auto it = nodes.begin();
            std::advance(it, static_cast<long>(maxNodes) / 2);
            auto minUpdate = it->lastUpdate;
            for (auto i = it; i != nodes.end(); ++i) {
                if (i->lastUpdate < minUpdate) {
                    minUpdate = i->lastUpdate;
                    it = i;
                }
            }
            nodes.erase(it);
        }
        std::lock_guard<std::mutex> lock(mtx);
        nodes.push_back(node);
    }

    void removeInactiveNodes() {
        auto now = std::chrono::system_clock::now();
        auto thirtyMinutesAgo = now - std::chrono::minutes(30);
        std::lock_guard<std::mutex> lock(mtx);
        nodes.remove_if([=](const LTE_RRC_UE_CONTEXT& node) {
            return node.lastUpdate < thirtyMinutesAgo;
        });
    }
};
```

This implementation uses a `std::list` for the dynamic linked list, which provides efficient insertion and removal of elements at both ends. The `addNode()` function checks if the number of nodes exceeds the maximum limit and removes inactive nodes before adding a new one. The `removeInactiveNodes()` function removes all nodes that have been inactive for more than 30 minutes.

The code uses a mutex to ensure thread safety during list operations, minimizing potential race conditions or deadlocks. Lock-free data structures could be considered for further optimization if necessary.

