public:
    explicit DynamicList(size_t capacity) : data_(capacity), capacity_(capacity) {}

    ListError initialize() {
        if (data_.empty()) {
            data_.resize(1, NFAPI_CRC_INDICATION_PDU_T{});
            data_[0].RX_UE_INFORMATION_TAG = 0;
            data_[0].RNTI = 0;
            data_[0].CRCFLAG = false;
