        auto it = elements_.find({element.RX_UE_INFORMATION_TAG, element.RNTI});
        if (it != elements_.end()) return ListError::ListFull;

        data_.emplace_back(element);
        elements_[{element.RX_UE_INFORMATION_TAG, element.RNTI}] = data_.size() - 1;

        if (data_.size() > capacity_) {
            resize();
        }
        return ListError::Success;
    }

