#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint32_t crcflag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU;

NFAPI_CRC_INDICATION_PDU* pool = NULL;
size_t max_pool_size = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void rolling_checksum(uint32_t *data, size_t len) {
    uint32_t sum = 0;
    for (size_t i = 0; i < len; ++i) {
        sum += *(data + i);
        sum = (sum >> 16) ^ (sum & 0xFFFF) ^ (sum << 15);
    }
}

NFAPI_CRC_INDICATION_PDU* create_structure() {
    NFAPI_CRC_INDICATION_PDU *new_node = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!new_node) {
        fprintf(stderr, "Error: Memory allocation failure\n");
        return NULL;
    }

    pthread_mutex_lock(&pool_mutex);
    if (pool && max_pool_size > 0 && pool_size() >= max_pool_size) {
        free(new_node);
        pthread_mutex_unlock(&pool_mutex);
        fprintf(stderr, "Error: Pool size exceeded the maximum limit\n");
        return NULL;
    }

    rolling_checksum((uint32_t*)&new_node->tag, sizeof(RX_UE_INFORMATION_TAG));
    rolling_checksum((uint32_t*)&new_node->rnti, sizeof(RNTI));
    new_node->crcflag = new_node->crcflag ^ sum;

    if (!pool) {
        pool = new_node;
        new_node->next = NULL;
    } else {
        NFAPI_CRC_INDICATION_PDU *last = pool;
        while (last->next) last = last->next;
        last->next = new_node;
        new_node->next = NULL;
    }

    pthread_mutex_unlock(&pool_mutex);
    return new_node;
}

size_t pool_size() {
    size_t count = 0;
    NFAPI_CRC_INDICATION_PDU *current = pool;
    while (current) {
        ++count;
        current = current->next;
    }
    return count;
}
```

