}

Node_t* find_or_create_rnti(Node_t **head, uint16_t rnti) {
    Node_t *current = *head;
    while (current != NULL) {
        if (current->RNTI == rnti) {
            return current;
        }
        current = current->next;
    }

    Node_t *new_node = create_node();
    new_node->RNTI = rnti;
    set_random_crcflag(new_node);

    new_node->next = *head;
    *head = new_node;
    return new_node;
}

void print_list(Node_t *head) {
    Node_t *current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u\n", current->RX_UE_INFORMATION_TAG, current->RNTI);
        current = current->next;
    }
}

void populate_list(Node_t **head, int node_count) {
    srand(time(NULL));

    for (int i = 0; i < node_count; ++i) {
        find_or_create_rnti(head, i + 1);
    }
