void init_crc_indication(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->crc_indication.crci = 0;
    for (int i = 0; i < 10; ++i) {
        pdu->crc_indication.crcflag[i] = rand() % 2;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdus(unsigned int N) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (unsigned int i = 0; i < N; ++i) {
        pdus[i].tag.rnti = i + 1; // Assuming RNTI values start from 1
        init_crc_indication(&pdus[i]);
    }

    return pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus, unsigned int N) {
    if (pdus) {
        free(pdus);
    }
}
